INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86923, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "西", "is_correct": true, "explanation": "正确：与“向东走”形成对照，表示另一个方向。"}, {"text": "东西", "is_correct": false, "explanation": "搭配：「东西」在此指“物品”或不具体的方向，「向东西走」不能指一个具体方向，句子不成立。"}, {"text": "西服", "is_correct": false, "explanation": "搭配：「西服」是衣服，不能表示方向。"}, {"text": "西洋", "is_correct": false, "explanation": "语义：「西洋」指西方的国家或地区，句中需要的是具体方向。"}], "explanations": {"西": "正确：与“向东走”形成对照，表示另一个方向。", "东西": "搭配：「东西」在此指“物品”或不具体的方向，「向东西走」不能指一个具体方向，句子不成立。", "西服": "搭配：「西服」是衣服，不能表示方向。", "西洋": "语义：「西洋」指西方的国家或地区，句中需要的是具体方向。"}, "sentence_index": 6, "correct_answer": "西"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我买了一套西，很便宜。", "explanation": "这里应该用〈西服〉。〈西〉单独作名词指衣服不规范，要说〈西服〉。"}, {"text": "她穿的衣服很西，大家都喜欢。", "explanation": "这里应该用〈西式〉。〈西〉作形容词修饰衣服不规范，描述风格要说〈西式〉。"}, {"text": "这条路很西，我们每天走。", "explanation": "这里应该用〈西式〉。〈西〉作形容词不能直接修饰路，描述西式街道要说〈西式〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70e18ada-3134-4ff9-8ed5-f024c8f396f4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86923, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "晚上太阳往西落下来，天就黑了。", "corrected_sentence": "晚上太阳往西落下去，天就黑了。", "error_description": "错误形式：「往西落下来」，补语「来」用错。正确形式：「往西落下去」。太阳落下是离开说话人的方向，要用「去」；「来」表示朝说话人的方向。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70e18ada-3134-4ff9-8ed5-f024c8f396f4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86923, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这条路一直在西走，就到了火车站。", "corrected_sentence": "这条路一直往西走，就到了火车站。", "error_description": "错误形式：「在西走」，用了「在」。正确形式：「往西走」。「在」表示位置，不能引出动作的方向；表示方向要用「往」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70e18ada-3134-4ff9-8ed5-f024c8f396f4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
