INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86924, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "方向名，太阳落下的一边，与“东”相对。", "primary_collocate": null, "pronunciation": "xī", "ipa": "ɕi˥", "syllable_count": 1, "sentences": [{"text": "从这里往西走，就能看到地铁站。", "target_word": "西", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "太阳每天从东边升起，向西落下。", "target_word": "西", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这条河由东向西流，穿过整个城市。", "target_word": "西", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这间屋子的窗户朝西，下午很热。", "target_word": "西", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这条路从东到西，一共有五公里。", "target_word": "西", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "车到路口以后，请向西拐。", "target_word": "西", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他家的房子坐西朝东。", "target_word": "西", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "飞机往西飞了五个小时。", "target_word": "西", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "地图上，上北下南，左西右东。", "target_word": "西", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "鸟儿向西飞去，天慢慢黑了。", "target_word": "西", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "西边", "label": "复合词"}, {"form": "西方", "label": "复合词"}, {"form": "西部", "label": "复合词"}], "register": "中性", "sense_fingerprint": "方向名，与东相对，太阳落下的方向", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 1 above tier T1: 3 words above tier T1 (max 2): 东边 (Zipf 3.76), 升起 (Zipf 3.91), 落下 (Zipf 3.98)']::text[], 'a7a1d248-553b-4926-a225-0466394be207') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86924, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "西", "is_correct": true, "explanation": "正确：表示方向，与“往……走”搭配。"}, {"text": "西服", "is_correct": false, "explanation": "搭配：「西服」是衣服，不能与“往……走”搭配表示方向。"}, {"text": "东西", "is_correct": false, "explanation": "搭配：「东西」指“物品”，「往东西走」不能指一个具体方向。"}, {"text": "西餐", "is_correct": false, "explanation": "搭配：「西餐」是食物，不能与“往……走”搭配。"}], "explanations": {"西": "正确：表示方向，与“往……走”搭配。", "西服": "搭配：「西服」是衣服，不能与“往……走”搭配表示方向。", "东西": "搭配：「东西」指“物品”，「往东西走」不能指一个具体方向。", "西餐": "搭配：「西餐」是食物，不能与“往……走”搭配。"}, "sentence_index": 0, "correct_answer": "西"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他很喜欢西的音乐，经常听。", "explanation": "这里应该用〈西方〉或〈西洋〉。〈西〉不能直接修饰音乐表示“西方的”，要说〈西方音乐〉。"}, {"text": "这个饭店的菜很西，我很喜欢。", "explanation": "这里应该用〈西式〉。〈西〉作形容词表示“西式”不规范，描述菜式要说〈西式〉。"}, {"text": "我们今天吃西吧。", "explanation": "这里应该用〈西餐〉。〈西〉不能单独指西餐，要说〈西餐〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70e18ada-3134-4ff9-8ed5-f024c8f396f4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86924, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "西", "is_correct": true, "explanation": "正确：「坐西朝东」是固定的方位说法，「西」表示房屋背靠的方向。"}, {"text": "东", "is_correct": false, "explanation": "语义：「坐东朝东」两个方向重复，与句中的「朝东」冲突。"}, {"text": "西瓜", "is_correct": false, "explanation": "搭配：「西瓜」是水果，不能用来表示房屋的朝向。"}, {"text": "西药", "is_correct": false, "explanation": "搭配：「西药」是药品，不能与“坐……”搭配表示朝向。"}], "explanations": {"西": "正确：「坐西朝东」是固定的方位说法，「西」表示房屋背靠的方向。", "东": "语义：「坐东朝东」两个方向重复，与句中的「朝东」冲突。", "西瓜": "搭配：「西瓜」是水果，不能用来表示房屋的朝向。", "西药": "搭配：「西药」是药品，不能与“坐……”搭配表示朝向。"}, "sentence_index": 6, "correct_answer": "西"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们家的装修很西，门口有一棵大树。", "explanation": "这里应该用〈西式〉。〈西〉表示“西式”时不能直接修饰装修，要说〈西式〉。"}, {"text": "这本书的封面很西，我很喜欢。", "explanation": "这里应该用〈西式〉。〈西〉作形容词表示“西式”不规范，描述封面要说〈西式〉。"}, {"text": "这家饭店的西很好吃。", "explanation": "这里应该用〈西餐〉。〈西〉不能单独作名词指西餐，要说〈西餐〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70e18ada-3134-4ff9-8ed5-f024c8f396f4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86924, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "车子一直西开，过了河就是老城区。", "corrected_sentence": "车子一直往西开，过了河就是老城区。", "error_description": "错误形式：「西开」，漏掉了介词「往」。正确形式：「往西开」。表示沿着某个方向行驶，要用「往」引出方向。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70e18ada-3134-4ff9-8ed5-f024c8f396f4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86924, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们往西的走，就到了湖边。", "corrected_sentence": "我们往西走，就到了湖边。", "error_description": "错误形式：「往西的走」，在「西」和「走」之间多加了「的」。正确形式：「往西走」。「往西」是状语，后面直接接动词，不能加「的」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70e18ada-3134-4ff9-8ed5-f024c8f396f4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
