INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86929, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "金是黄黄亮亮、很贵重的东西。", "primary_collocate": null, "pronunciation": "jīn", "ipa": "tɕin˥", "syllable_count": 1, "sentences": [{"text": "这个杯子是金的，亮亮的。", "target_word": "金", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "金很亮，也很贵。", "target_word": "金", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明家有一块金。", "target_word": "金", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在河边找到了一块金。", "target_word": "金", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "阳光下，那块金闪闪发光。", "target_word": "金", "complexity_tier": "T3", "furigana": "yáng guāng xià nà kuài jīn shǎn shǎn fā guāng", "sentence_source": "generated"}, {"text": "这块金很重，我拿不动。", "target_word": "金", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "金是黄色的，大家都喜欢。", "target_word": "金", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把金放在了盒子里。", "target_word": "金", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "谁不喜欢又黄又亮的金呢？", "target_word": "金", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那条金的项链看起来很贵。", "target_word": "金", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "黄金", "label": "复合"}, {"form": "金子", "label": "复合"}, {"form": "金色", "label": "复合"}], "register": "通用", "sense_fingerprint": "黄黄亮亮、很贵重的东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dabb8dab-b90b-4c44-8fec-11f552bb446a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86929, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "金", "is_correct": true, "explanation": "金：黄黄亮亮、很贵重的东西，本题的正确答案。"}, {"text": "近", "is_correct": false, "explanation": "近 jìn（第四声）与 金 jīn（第一声）声调不同，意思是靠近。"}, {"text": "精", "is_correct": false, "explanation": "精 jīng 与 金 jīn 韵母不同（-ing 与 -in），意思是精细、精华。"}, {"text": "君", "is_correct": false, "explanation": "君 jūn 与 金 jīn 韵母不同（-un 与 -in），意思是君主。"}, {"text": "紧", "is_correct": false, "explanation": "紧 jǐn（第三声）与 金 jīn（第一声）声调不同，意思是紧张、紧固。"}, {"text": "亲", "is_correct": false, "explanation": "亲 qīn 与 金 jīn 只差声母（q 与 j），意思是亲近。"}], "explanations": {"金": "金：黄黄亮亮、很贵重的东西，本题的正确答案。", "近": "近 jìn（第四声）与 金 jīn（第一声）声调不同，意思是靠近。", "精": "精 jīng 与 金 jīn 韵母不同（-ing 与 -in），意思是精细、精华。", "君": "君 jūn 与 金 jīn 韵母不同（-un 与 -in），意思是君主。", "紧": "紧 jǐn（第三声）与 金 jīn（第一声）声调不同，意思是紧张、紧固。", "亲": "亲 qīn 与 金 jīn 只差声母（q 与 j），意思是亲近。"}, "sentence_index": null, "correct_answer": "金"}, "level_3": {"options": [{"text": "金", "is_correct": true, "explanation": "“金的”指用黄金做的，正好说明杯子的材质。"}, {"text": "布", "is_correct": false, "explanation": "体貌：布做的杯子柔软、不会亮亮的，与“亮亮的”矛盾。"}, {"text": "纸", "is_correct": false, "explanation": "语义：纸做的杯子不反光，不会是“亮亮的”。"}, {"text": "土", "is_correct": false, "explanation": "体貌：土做的杯子灰暗，与“亮亮的”的外观不符。"}], "explanations": {"金": "“金的”指用黄金做的，正好说明杯子的材质。", "布": "体貌：布做的杯子柔软、不会亮亮的，与“亮亮的”矛盾。", "纸": "语义：纸做的杯子不反光，不会是“亮亮的”。", "土": "体貌：土做的杯子灰暗，与“亮亮的”的外观不符。"}, "sentence_index": 0, "correct_answer": "金"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个玩具是金的，一块钱就能买到一个。", "explanation": "这里与〈金〉的意思不符：〈金〉指很贵重的东西，不能指一块钱就能买到的玩具。"}, {"text": "这把旧伞上的金很便宜，一块钱就能买到。", "explanation": "这里与〈金〉的意思不符：〈金〉指很贵重的东西，这里描述的价格却很低。"}, {"text": "他在河边找到了一朵金。", "explanation": "这里量词用错：“朵”用于花、云等，金块应说“块”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c3bb0a1a-67c0-4958-ba6c-f5cef83a1758') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86929, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "金", "is_correct": true, "explanation": "金：黄黄亮亮、很贵重的东西，本题的正确答案。"}, {"text": "惊", "is_correct": false, "explanation": "惊 jīng 与 金 jīn 韵母不同（-ing 与 -in），意思是惊讶。"}, {"text": "经", "is_correct": false, "explanation": "经 jīng 与 金 jīn 韵母不同（-ing 与 -in），意思是经过。"}, {"text": "心", "is_correct": false, "explanation": "心 xīn 与 金 jīn 只差声母（x 与 j），意思是心脏、心思。"}, {"text": "进", "is_correct": false, "explanation": "进 jìn（第四声）与 金 jīn（第一声）声调不同，意思是进入。"}, {"text": "京", "is_correct": false, "explanation": "京 jīng 与 金 jīn 韵母不同（-ing 与 -in），意思是首都。"}], "explanations": {"金": "金：黄黄亮亮、很贵重的东西，本题的正确答案。", "惊": "惊 jīng 与 金 jīn 韵母不同（-ing 与 -in），意思是惊讶。", "经": "经 jīng 与 金 jīn 韵母不同（-ing 与 -in），意思是经过。", "心": "心 xīn 与 金 jīn 只差声母（x 与 j），意思是心脏、心思。", "进": "进 jìn（第四声）与 金 jīn（第一声）声调不同，意思是进入。", "京": "京 jīng 与 金 jīn 韵母不同（-ing 与 -in），意思是首都。"}, "sentence_index": null, "correct_answer": "金"}, "level_3": {"options": [{"text": "金", "is_correct": true, "explanation": "金是黄色的，这里说的正是金的颜色，句子通顺。"}, {"text": "雪", "is_correct": false, "explanation": "语义：雪是白色的，不是黄色的。"}, {"text": "血", "is_correct": false, "explanation": "语义：血是红色的，不能说“血是黄色的”。"}, {"text": "冰", "is_correct": false, "explanation": "搭配：说冰的颜色通常用“白色”“透明”，与“黄色的”搭配不通。"}], "explanations": {"金": "金是黄色的，这里说的正是金的颜色，句子通顺。", "雪": "语义：雪是白色的，不是黄色的。", "血": "语义：血是红色的，不能说“血是黄色的”。", "冰": "搭配：说冰的颜色通常用“白色”“透明”，与“黄色的”搭配不通。"}, "sentence_index": 6, "correct_answer": "金"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我家的金快用完了，爸爸很着急。", "explanation": "这里应该用〈钱〉。〈金〉不表示钱，说“家里的钱快用完了”要用〈钱〉。"}, {"text": "那只金很亮，看起来很贵。", "explanation": "这里量词用错：“只”不用于金块，应说“那块金”或“那条金”。"}, {"text": "这张金很重，我拿不动。", "explanation": "这里量词用错：“张”用于扁平物，不能用来数金块。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c3bb0a1a-67c0-4958-ba6c-f5cef83a1758') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86929, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他把那只金卖了，换了不少钱。", "corrected_sentence": "他把那块金卖了，换了不少钱。", "error_description": "金块的量词应用“块”，“只”用于动物或成对物品中的一个，不能用来数金块。正确说法是“那块金”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c3bb0a1a-67c0-4958-ba6c-f5cef83a1758') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86929, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她找到了一张金，很高兴。", "corrected_sentence": "她找到了一块金，很高兴。", "error_description": "金块的量词应用“块”，“张”用于纸、桌子等扁平物，不能用来数金子。正确说法是“一块金”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c3bb0a1a-67c0-4958-ba6c-f5cef83a1758') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
