INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86930, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "一种黄色的贵重金属；也泛指金属。", "primary_collocate": null, "pronunciation": "jīn", "ipa": "tɕin˥", "syllable_count": 1, "sentences": [{"text": "金、银、铜、铁都是金属。", "target_word": "金", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个戒指是金的，不是银的。", "target_word": "金", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "金比银贵。", "target_word": "金", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他有一条金做的项链。", "target_word": "金", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "金很软，可以做成各种样子。", "target_word": "金", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你的耳环是金还是银？", "target_word": "金", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这块奖牌是金的。", "target_word": "金", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "金不会生锈。", "target_word": "金", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶买了一个金的手镯。", "target_word": "金", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "金在火里会变软。", "target_word": "金", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "黄金", "label": "复合"}, {"form": "金子", "label": "复合"}, {"form": "金属", "label": "复合"}], "register": "通用", "sense_fingerprint": "黄金这种贵重金属，也泛指金属", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dabb8dab-b90b-4c44-8fec-11f552bb446a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86930, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "金", "is_correct": true, "explanation": "金：黄色的贵重金属，本题的正确答案。"}, {"text": "紧", "is_correct": false, "explanation": "紧 jǐn（第三声）与 金 jīn（第一声）声调不同，意思是紧张、紧固，不是金属。"}, {"text": "进", "is_correct": false, "explanation": "进 jìn（第四声）与 金 jīn（第一声）声调不同，意思是进入。"}, {"text": "精", "is_correct": false, "explanation": "精 jīng 与 金 jīn 韵母不同（-ing 与 -in），意思是精细、精华。"}, {"text": "君", "is_correct": false, "explanation": "君 jūn 与 金 jīn 韵母不同（-un 与 -in），意思是君主。"}, {"text": "京", "is_correct": false, "explanation": "京 jīng 与 金 jīn 韵母不同（-ing 与 -in），意思是首都。"}], "explanations": {"金": "金：黄色的贵重金属，本题的正确答案。", "紧": "紧 jǐn（第三声）与 金 jīn（第一声）声调不同，意思是紧张、紧固，不是金属。", "进": "进 jìn（第四声）与 金 jīn（第一声）声调不同，意思是进入。", "精": "精 jīng 与 金 jīn 韵母不同（-ing 与 -in），意思是精细、精华。", "君": "君 jūn 与 金 jīn 韵母不同（-un 与 -in），意思是君主。", "京": "京 jīng 与 金 jīn 韵母不同（-ing 与 -in），意思是首都。"}, "sentence_index": null, "correct_answer": "金"}, "level_3": {"options": [{"text": "金", "is_correct": true, "explanation": "金是金属，与银、铜、铁并列，正好放在空格里。"}, {"text": "木", "is_correct": false, "explanation": "语义：木是木材，不属于金属，与银、铜、铁并列不成立。"}, {"text": "石", "is_correct": false, "explanation": "语义：石是岩石，不是金属，句子说的是四种金属。"}, {"text": "水", "is_correct": false, "explanation": "搭配：“都是金属”要求并列成分都是金属类名词，“水”与“金属”搭配不通。"}], "explanations": {"金": "金是金属，与银、铜、铁并列，正好放在空格里。", "木": "语义：木是木材，不属于金属，与银、铜、铁并列不成立。", "石": "语义：石是岩石，不是金属，句子说的是四种金属。", "水": "搭配：“都是金属”要求并列成分都是金属类名词，“水”与“金属”搭配不通。"}, "sentence_index": 0, "correct_answer": "金"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我身上没有金了，只能坐公交车。", "explanation": "这里应该用〈钱〉。〈金〉指黄色贵重金属，不能表示钱；说“没有钱”要用〈钱〉。"}, {"text": "他买了一张金。", "explanation": "这里应该用〈块〉或〈条〉。金块、金条用“块”“条”来数；“张”用于纸、桌子等扁平物，不能用来数金子。"}, {"text": "这个月的金不够交房租了。", "explanation": "这里应该用〈钱〉。〈金〉不表示钱，说“不够交房租”要用〈钱〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c3bb0a1a-67c0-4958-ba6c-f5cef83a1758') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86930, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "金", "is_correct": true, "explanation": "金：黄色的贵重金属，本题的正确答案。"}, {"text": "近", "is_correct": false, "explanation": "近 jìn（第四声）与 金 jīn（第一声）声调不同，意思是靠近。"}, {"text": "惊", "is_correct": false, "explanation": "惊 jīng 与 金 jīn 韵母不同（-ing 与 -in），意思是惊讶。"}, {"text": "经", "is_correct": false, "explanation": "经 jīng 与 金 jīn 韵母不同（-ing 与 -in），意思是经过、经历。"}, {"text": "心", "is_correct": false, "explanation": "心 xīn 与 金 jīn 只差声母（x 与 j），意思是心脏、心思。"}, {"text": "亲", "is_correct": false, "explanation": "亲 qīn 与 金 jīn 只差声母（q 与 j），意思是亲近。"}], "explanations": {"金": "金：黄色的贵重金属，本题的正确答案。", "近": "近 jìn（第四声）与 金 jīn（第一声）声调不同，意思是靠近。", "惊": "惊 jīng 与 金 jīn 韵母不同（-ing 与 -in），意思是惊讶。", "经": "经 jīng 与 金 jīn 韵母不同（-ing 与 -in），意思是经过、经历。", "心": "心 xīn 与 金 jīn 只差声母（x 与 j），意思是心脏、心思。", "亲": "亲 qīn 与 金 jīn 只差声母（q 与 j），意思是亲近。"}, "sentence_index": null, "correct_answer": "金"}, "level_3": {"options": [{"text": "金", "is_correct": true, "explanation": "奖牌常用金、银、铜等金属制作，“金的”正好指材质。"}, {"text": "雨", "is_correct": false, "explanation": "语义：雨不是可以用来制作奖牌的材料。"}, {"text": "火", "is_correct": false, "explanation": "语义：火不能用来制作奖牌，句子说的是奖牌的材质。"}, {"text": "云", "is_correct": false, "explanation": "搭配：“奖牌”的材质通常说金、银、铜，“云”不能作为奖牌的材料。"}], "explanations": {"金": "奖牌常用金、银、铜等金属制作，“金的”正好指材质。", "雨": "语义：雨不是可以用来制作奖牌的材料。", "火": "语义：火不能用来制作奖牌，句子说的是奖牌的材质。", "云": "搭配：“奖牌”的材质通常说金、银、铜，“云”不能作为奖牌的材料。"}, "sentence_index": 6, "correct_answer": "金"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我家的金越来越少，妈妈很着急。", "explanation": "这里应该用〈钱〉。〈金〉不表示钱，说“家里的钱越来越少”要用〈钱〉。"}, {"text": "他买了一只金。", "explanation": "这里量词用错：“只”用于动物或成对物品中的一个，金块应说“块”。"}, {"text": "他攒的金都花完了，只好去借钱。", "explanation": "这里应该用〈钱〉。〈金〉不表示钱，说“花完了钱”要用〈钱〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c3bb0a1a-67c0-4958-ba6c-f5cef83a1758') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86930, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他在店里买了三只金。", "corrected_sentence": "他在店里买了三块金。", "error_description": "金块的量词应用“块”，不能用“只”（“只”用于动物或成对物品中的一个）。正确说法是“三块金”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c3bb0a1a-67c0-4958-ba6c-f5cef83a1758') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86930, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那张金很重，我抬不动。", "corrected_sentence": "那块金很重，我抬不动。", "error_description": "金块的量词应用“块”，“张”用于纸、桌子等扁平物，不能用来数金子。正确说法是“那块金”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c3bb0a1a-67c0-4958-ba6c-f5cef83a1758') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86933, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "下月", "is_correct": true, "explanation": "下月：指本月之后的一个月，与「上月」相对，是反义关系。"}, {"text": "今年", "is_correct": false, "explanation": "「今年」指这一整年，与「上月」不构成反义关系。"}, {"text": "去年", "is_correct": false, "explanation": "「去年」指前一整年，与「上月」不构成反义关系。"}, {"text": "明天", "is_correct": false, "explanation": "「明天」指次日，与「上月」不构成反义关系。"}], "correct_answer": "下月", "explanations": {"下月": "下月：指本月之后的一个月，与「上月」相对，是反义关系。", "今年": "「今年」指这一整年，与「上月」不构成反义关系。", "去年": "「去年」指前一整年，与「上月」不构成反义关系。", "明天": "「明天」指次日，与「上月」不构成反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7d9819ae-3470-4917-9d2d-1441aada02da') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86933, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "下月", "is_correct": true, "explanation": "下月：指本月之后的一个月，与「上月」相对，是反义关系。"}, {"text": "昨天", "is_correct": false, "explanation": "「昨天」指前一天，与「上月」不构成反义关系。"}, {"text": "周末", "is_correct": false, "explanation": "「周末」指一周的末尾两天，与「上月」不构成反义关系。"}, {"text": "前年", "is_correct": false, "explanation": "「前年」指两年之前，与「上月」不构成反义关系。"}], "correct_answer": "下月", "explanations": {"下月": "下月：指本月之后的一个月，与「上月」相对，是反义关系。", "昨天": "「昨天」指前一天，与「上月」不构成反义关系。", "周末": "「周末」指一周的末尾两天，与「上月」不构成反义关系。", "前年": "「前年」指两年之前，与「上月」不构成反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7d9819ae-3470-4917-9d2d-1441aada02da') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86933, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "上月是这个月前面的那一个月。", "primary_collocate": null, "pronunciation": "shàng yuè", "ipa": "ʂɑŋ˥˩ ɥɛ˥˩", "syllable_count": 2, "sentences": [{"text": "现在是五月，上月是四月。", "target_word": "上月", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "上月我去了上海，这个月在家。", "target_word": "上月", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天是十月三号，上月的工作已经做完了。", "target_word": "上月", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我上月买的手机，这个月就坏了。", "target_word": "上月", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "上月天气很冷，这个月暖和多了。", "target_word": "上月", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他上月搬了家，现在住在学校旁边。", "target_word": "上月", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个月比上月忙，我每天都加班。", "target_word": "上月", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "上月的电费已经交了，下个月再交。", "target_word": "上月", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "上月二十号我们见过面，今天又见了。", "target_word": "上月", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说上月的考试，大家做得很好。", "target_word": "上月", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "上月底", "label": "复合词"}], "register": "中性", "sense_fingerprint": "上月：本月之前的那个月", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a666923a-00f0-43ce-9ee1-f1406e0ad8d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86933, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "上月", "is_correct": true, "explanation": "上月：指本月的前一个月，与「现在是五月」相符，可以填入。"}, {"text": "本月", "is_correct": false, "explanation": "语义：「本月」就是现在的五月，不能再说它是四月。"}, {"text": "下月", "is_correct": false, "explanation": "语义：「下月」指这个月之后的一个月，是六月，与「是四月」不符。"}, {"text": "去年", "is_correct": false, "explanation": "搭配：「去年」指一整年之前，不能用来与同一年的月份作前后对应。"}], "explanations": {"上月": "上月：指本月的前一个月，与「现在是五月」相符，可以填入。", "本月": "语义：「本月」就是现在的五月，不能再说它是四月。", "下月": "语义：「下月」指这个月之后的一个月，是六月，与「是四月」不符。", "去年": "搭配：「去年」指一整年之前，不能用来与同一年的月份作前后对应。"}, "sentence_index": 0, "correct_answer": "上月"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我上月三十年前出生在北京。", "explanation": "这里应该用〈三十年前〉。上月指上一个月，与''三十年前''冲突，不能用来说明很久以前的出生时间。"}, {"text": "上月的会议明天举行。", "explanation": "这里应该用〈下月〉。上月指过去的月份，不能用来说明将来举行的会议。"}, {"text": "我今天上月去了超市。", "explanation": "这里应该用〈昨天〉。上月指整个上一个月，不能用来说明某一天的外出。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7d9819ae-3470-4917-9d2d-1441aada02da') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86933, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "上月", "is_correct": true, "explanation": "上月：指本月的前一个月，与「这个月」相对比较，可以填入。"}, {"text": "这个月", "is_correct": false, "explanation": "语义：「这个月」本身就是比较的对象，「这个月比这个月忙」没有意义。"}, {"text": "今年", "is_correct": false, "explanation": "语义：「今年」指整年，与「这个月」不能作为同类时间进行比较。"}, {"text": "周末", "is_correct": false, "explanation": "搭配：「周末」是很短的一段时间，与「这个月」比较，「这个月比周末忙」不搭配。"}], "explanations": {"上月": "上月：指本月的前一个月，与「这个月」相对比较，可以填入。", "这个月": "语义：「这个月」本身就是比较的对象，「这个月比这个月忙」没有意义。", "今年": "语义：「今年」指整年，与「这个月」不能作为同类时间进行比较。", "周末": "搭配：「周末」是很短的一段时间，与「这个月」比较，「这个月比周末忙」不搭配。"}, "sentence_index": 6, "correct_answer": "上月"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "现在是上月。", "explanation": "这里应该用〈这个月〉。「现在」指当前的月份，上月是过去的月份，不能说「现在是上月」。"}, {"text": "这次考试上月就要开始了。", "explanation": "这里应该用〈下个月〉。上月指已经过去的月份，不能用来说明将要开始的考试。"}, {"text": "上月的假期是下个星期。", "explanation": "这里应该用〈这个月〉。上月指已经过去的月份，不能用来指当前安排的假期时间。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7d9819ae-3470-4917-9d2d-1441aada02da') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86933, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "上月了我去了北京。", "corrected_sentence": "上月我去了北京。", "error_description": "错误：「了」放在了「上月」后面，写成「上月了」。「上月」是时间词，「了」应紧跟在动词「去」后面，正确写法是「上月我去了北京」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7d9819ae-3470-4917-9d2d-1441aada02da') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86933, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这上月我们去了一次北京。", "corrected_sentence": "上月我们去了一次北京。", "error_description": "错误：「这」放在了「上月」前面，写成「这上月」。「上月」是表示时间的词，不能用「这」来修饰。正确写法是「上月我们去了一次北京」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7d9819ae-3470-4917-9d2d-1441aada02da') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86947, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a5f4d9a8-94a8-45a0-b85f-25d39fce93ce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86947, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a5f4d9a8-94a8-45a0-b85f-25d39fce93ce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86947, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "宣传是把一件事说给很多人听，让大家知道。", "primary_collocate": null, "pronunciation": "xuān chuán", "ipa": "ɕɥɛn˥ ʈʂʰwan˧˥", "syllable_count": 2, "sentences": [{"text": "我们要宣传这个好消息。", "target_word": "宣传", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学校宣传明天的音乐会。", "target_word": "宣传", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他在网上宣传新开的小店。", "target_word": "宣传", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请你帮我们宣传一下这次活动。", "target_word": "宣传", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师在课上宣传下周的比赛。", "target_word": "宣传", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司用海报宣传新手机。", "target_word": "宣传", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他们在街上宣传着环保活动。", "target_word": "宣传", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小王去年宣传过这个节日。", "target_word": "宣传", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们得多宣传这家新开的饭馆。", "target_word": "宣传", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "商店门口的人正在宣传打折的消息。", "target_word": "宣传", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "宣传了", "label": "体标"}, {"form": "宣传着", "label": "体标"}, {"form": "宣传过", "label": "体标"}, {"form": "宣传片", "label": "复合"}], "register": "中性", "sense_fingerprint": "把消息、活动、店铺等告诉很多人，让大家知道", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab628bc3-ddad-4bad-aa8a-0184cfa7bf3e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86947, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "宣传", "is_correct": true, "explanation": "宣传：把好消息告诉很多人，符合句意。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”用于食物，不能说“吃好消息”。"}, {"text": "擦", "is_correct": false, "explanation": "搭配：“擦”用于表面和器物，不能擦“好消息”。"}, {"text": "躲", "is_correct": false, "explanation": "语义：“躲”是避开，与值得告诉大家的“好消息”相冲突。"}], "explanations": {"宣传": "宣传：把好消息告诉很多人，符合句意。", "吃": "搭配：“吃”用于食物，不能说“吃好消息”。", "擦": "搭配：“擦”用于表面和器物，不能擦“好消息”。", "躲": "语义：“躲”是避开，与值得告诉大家的“好消息”相冲突。"}, "sentence_index": 0, "correct_answer": "宣传"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在日记里宣传了这件事。", "explanation": "这里应该用〈记录〉或〈写〉。宣传是向大众传播消息，日记是私人记录，不能用宣传。"}, {"text": "他宣传了自己的心跳。", "explanation": "这里应该用〈感受〉。宣传的对象须是消息、活动等信息，“心跳”是身体感觉，不能宣传。"}, {"text": "他宣传了一杯水。", "explanation": "这里“一杯水”不是可以宣传的对象，应说〈推销〉或〈卖〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a5f4d9a8-94a8-45a0-b85f-25d39fce93ce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86947, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "宣传", "is_correct": true, "explanation": "宣传：向街上的人传播环保活动，符合句意。"}, {"text": "走", "is_correct": false, "explanation": "语义：“走”指行走，与“宣传”的意思不合，不能说“走环保活动”。"}, {"text": "结束", "is_correct": false, "explanation": "语义：“结束”指终止，与“宣传”让大家知道的意思不合。"}, {"text": "睡", "is_correct": false, "explanation": "配价：“睡”是不及物动词，不能带宾语，且“睡着”会被理解为入睡。"}], "explanations": {"宣传": "宣传：向街上的人传播环保活动，符合句意。", "走": "语义：“走”指行走，与“宣传”的意思不合，不能说“走环保活动”。", "结束": "语义：“结束”指终止，与“宣传”让大家知道的意思不合。", "睡": "配价：“睡”是不及物动词，不能带宾语，且“睡着”会被理解为入睡。"}, "sentence_index": 6, "correct_answer": "宣传"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我宣传朋友这家饭馆很好吃。", "explanation": "这里应该用〈告诉〉。宣传是面向很多人传播信息，只对一位朋友说要用〈告诉〉。"}, {"text": "这块石头宣传了这次活动。", "explanation": "这里“宣传”与〈告知〉混淆：宣传的主语须是人或机构，“石头”无法发出信息，应换成〈通知〉类的人类主语。"}, {"text": "她宣传了自己的困惑。", "explanation": "这里应该用〈倾诉〉。宣传是向大众传播信息，内心困惑要向人〈倾诉〉，不能用“宣传”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a5f4d9a8-94a8-45a0-b85f-25d39fce93ce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86947, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他们在街上宣传了着新的环保口号。", "corrected_sentence": "他们在街上宣传着新的环保口号。", "error_description": "体标重复：“了”和“着”不能同时用在同一个动词后，应只用“宣传着”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a5f4d9a8-94a8-45a0-b85f-25d39fce93ce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86947, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她把新书宣传得很好得。", "corrected_sentence": "她把新书宣传得很好。", "error_description": "多余的“得”：补语“很好”后面不能再加“得”。正确形式：“宣传得很好”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a5f4d9a8-94a8-45a0-b85f-25d39fce93ce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86948, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a5f4d9a8-94a8-45a0-b85f-25d39fce93ce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
