INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86955, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "后人是很久以后才出生的人。", "primary_collocate": null, "pronunciation": "hòu rén", "ipa": "xou̯⁵¹ ʐən³⁵", "syllable_count": 2, "sentences": [{"text": "古人留下的书，后人还在读。", "target_word": "后人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "后人从这些老画里认识了当时的生活。", "target_word": "后人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座桥是为后人修的。", "target_word": "后人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们今天做的事，后人会看到。", "target_word": "后人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多年以后，后人才明白他的想法。", "target_word": "后人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，要给后人留下干净的河。", "target_word": "后人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "后人常常拿这位诗人和别的诗人比。", "target_word": "后人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些历史故事让后人知道以前发生了什么。", "target_word": "后人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他写了一本日记，想让后人了解这个时代。", "target_word": "后人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一千年前的城墙，后人至今还在保护。", "target_word": "后人", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "很久以后才出生的人，泛指后来的一代代人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dabb8dab-b90b-4c44-8fec-11f552bb446a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86955, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "后人", "is_correct": true, "explanation": "后人：很久以后才出生的人，“留下的书，还在读”正好指这些人。"}, {"text": "祖先", "is_correct": false, "explanation": "语义：祖先已经去世，不能“还在读”古人留下的书。"}, {"text": "石头", "is_correct": false, "explanation": "搭配：“还在读”的施事须是能读书的人，“石头”不能与“读”搭配。"}, {"text": "小鸟", "is_correct": false, "explanation": "语义：小鸟不会读书，句子不通。"}], "explanations": {"后人": "后人：很久以后才出生的人，“留下的书，还在读”正好指这些人。", "祖先": "语义：祖先已经去世，不能“还在读”古人留下的书。", "石头": "搭配：“还在读”的施事须是能读书的人，“石头”不能与“读”搭配。", "小鸟": "语义：小鸟不会读书，句子不通。"}, "sentence_index": 0, "correct_answer": "后人"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这只猫的后人有五只。", "explanation": "这里应该用〈后代〉。〈后人〉专指人，猫的子代要说〈后代〉。"}, {"text": "后人在一百年前就修好了这座桥，很多人都来看。", "explanation": "这里应该用〈祖先〉。〈后人〉指很久以后才出生的人，不能用于一百年前已经完成的事。"}, {"text": "今天在座的后人都是我的老同学。", "explanation": "这里应该用〈同辈〉。〈后人〉指很久以后才出生的人，不能指同时代的人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c3bb0a1a-67c0-4958-ba6c-f5cef83a1758') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86955, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "后人", "is_correct": true, "explanation": "后人：很久以后才出生的人，能够“拿这位诗人和别的诗人比”。"}, {"text": "花朵", "is_correct": false, "explanation": "搭配：“拿……比”的主体要求是能比较的人，“花朵”不能作比较的主体。"}, {"text": "河流", "is_correct": false, "explanation": "语义：河流不会比较诗人，句子不通。"}, {"text": "云朵", "is_correct": false, "explanation": "语义：云朵不能拿诗人来做比较，句子没有意义。"}], "explanations": {"后人": "后人：很久以后才出生的人，能够“拿这位诗人和别的诗人比”。", "花朵": "搭配：“拿……比”的主体要求是能比较的人，“花朵”不能作比较的主体。", "河流": "语义：河流不会比较诗人，句子不通。", "云朵": "语义：云朵不能拿诗人来做比较，句子没有意义。"}, "sentence_index": 6, "correct_answer": "后人"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这棵老树的后人长得很高。", "explanation": "这里应该用〈后代〉。〈后人〉专指人，不用于树木；树木的子代要说〈后代〉。"}, {"text": "一千年前的城墙，一座后人至今还在保护。", "explanation": "这里量词用错：“座”用于山、房屋等，不用于人，这里应说〈位〉或〈个〉。"}, {"text": "我们的后人一千年前就修好了这座城墙。", "explanation": "时间上矛盾：〈后人〉指很久以后才出生的人，不能在一千年前修城墙。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c3bb0a1a-67c0-4958-ba6c-f5cef83a1758') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86955, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这些画是留给很多只后人的。", "corrected_sentence": "这些画是留给很多后人的。", "error_description": "量词错误：“后人”指人，“只”多用于动物，不能用来修饰人。“很多”后直接接名词即可。正确说法是“这些画是留给很多后人的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c3bb0a1a-67c0-4958-ba6c-f5cef83a1758') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86955, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这件事，很多只后人都会记住。", "corrected_sentence": "这件事，很多后人都会记住。", "error_description": "量词错误：“后人”指人，“只”多用于动物，不能用来数人。“很多”后直接接名词即可，不必加“只”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c3bb0a1a-67c0-4958-ba6c-f5cef83a1758') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
