INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86974, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c3bb0a1a-67c0-4958-ba6c-f5cef83a1758') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86974, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "每一天；天天。", "primary_collocate": null, "pronunciation": "měi tiān", "ipa": "meɪ̯²¹⁴ tʰiɛn⁵⁵", "syllable_count": 2, "sentences": [{"text": "他每天吃两个苹果。", "target_word": "每天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每天下午，老人都在河边散步。", "target_word": "每天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我每天用手机听中文歌。", "target_word": "每天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "姐姐每天去图书馆看书。", "target_word": "每天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她每天学习汉语一个小时。", "target_word": "每天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每天我都给奶奶打电话。", "target_word": "每天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生说他每天要喝六杯水。", "target_word": "每天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条路每天都有很多车。", "target_word": "每天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们每天唱着歌去学校。", "target_word": "每天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们班每天有五节课。", "target_word": "每天", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "每一天、天天，表示动作按天重复", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dabb8dab-b90b-4c44-8fec-11f552bb446a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86974, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "每天", "is_correct": true, "explanation": "正确：“他每天吃两个苹果”，“每天”表示按天重复，与日常进食相符。"}, {"text": "每秒", "is_correct": false, "explanation": "语义：“每秒”间隔极短，每秒吃两个苹果不合常理。"}, {"text": "每分钟", "is_correct": false, "explanation": "语义：“每分钟”间隔太短，每分钟吃两个苹果不是正常的说法。"}, {"text": "每年", "is_correct": false, "explanation": "搭配：“每年”是年度周期，不与“吃两个苹果”这种日常饮食搭配。"}], "explanations": {"每天": "正确：“他每天吃两个苹果”，“每天”表示按天重复，与日常进食相符。", "每秒": "语义：“每秒”间隔极短，每秒吃两个苹果不合常理。", "每分钟": "语义：“每分钟”间隔太短，每分钟吃两个苹果不是正常的说法。", "每年": "搭配：“每年”是年度周期，不与“吃两个苹果”这种日常饮食搭配。"}, "sentence_index": 0, "correct_answer": "每天"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他每天生日都请朋友吃饭。", "explanation": "这里应该用〈每年〉。生日一年只有一次，“每天”表示按天重复，不能说“每天生日”。"}, {"text": "这个社团每天组织活动，每两周一次。", "explanation": "这里应该用〈定期〉。“定期”指按一定周期进行，“每两周一次”与“每天”矛盾。"}, {"text": "他每天在周末去图书馆，平时在家。", "explanation": "这里应该用〈有时〉。“每天”表示没有例外，而“平时在家”说明并非每天去图书馆，前后矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c3bb0a1a-67c0-4958-ba6c-f5cef83a1758') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86974, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "每天", "is_correct": true, "explanation": "正确：“医生说他每天要喝六杯水”，“每天”符合日常饮水的建议。"}, {"text": "每周", "is_correct": false, "explanation": "语义：每周喝六杯水的量远低于医生建议的日常饮水量，不合语境。"}, {"text": "每月", "is_correct": false, "explanation": "搭配：“每月”的周期过长，与“要喝六杯水”这种日常需求不搭配。"}, {"text": "每小时", "is_correct": false, "explanation": "语义：每小时喝六杯水超出正常的饮水量，不合常理。"}], "explanations": {"每天": "正确：“医生说他每天要喝六杯水”，“每天”符合日常饮水的建议。", "每周": "语义：每周喝六杯水的量远低于医生建议的日常饮水量，不合语境。", "每月": "搭配：“每月”的周期过长，与“要喝六杯水”这种日常需求不搭配。", "每小时": "语义：每小时喝六杯水超出正常的饮水量，不合常理。"}, "sentence_index": 6, "correct_answer": "每天"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这所学校每天举办一次运动会。", "explanation": "这里应该用〈每年〉。运动会通常一年举办一次；“每天”表示每一天，与这种周期性活动矛盾。"}, {"text": "我每天加班，一个月只有两次。", "explanation": "这里应该用〈偶尔〉。“每天加班”与“一个月只有两次”矛盾；“偶尔”表示不常发生，才与后半句相符。"}, {"text": "这个班每天都有一次测验，周末没有。", "explanation": "这里应该用〈每周〉。“每天”包括周末，与“周末没有”矛盾；“每周都有一次测验，周末没有”才相符。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c3bb0a1a-67c0-4958-ba6c-f5cef83a1758') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86974, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "哥哥每天天下午去跑步。", "corrected_sentence": "哥哥每天下午去跑步。", "error_description": "“每天”后面不能再加一个“天”，“每天天”是错误的，应说“每天”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c3bb0a1a-67c0-4958-ba6c-f5cef83a1758') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86974, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老师每天了都在办公室备课。", "corrected_sentence": "老师每天都在办公室备课。", "error_description": "“了”不能插在“每天”和“都”之间，“每天了都”是错误的，应说“每天都”。正确说法是“老师每天都在办公室备课”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c3bb0a1a-67c0-4958-ba6c-f5cef83a1758') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
