INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87011, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "基本单位是用来数数、量东西的最主要的那个单位。", "primary_collocate": null, "pronunciation": "jī běn dān wèi", "ipa": "tɕi˥ pən˨˩ tan˥ uei˥˩", "syllable_count": 4, "sentences": [{"text": "米是长度的基本单位。", "target_word": "基本单位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "千克是重量的基本单位。", "target_word": "基本单位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "秒是时间的基本单位。", "target_word": "基本单位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在中国，钱的基本单位是元。", "target_word": "基本单位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "数东西的时候，个是最常用的基本单位。", "target_word": "基本单位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们先学长度的基本单位，再学面积。", "target_word": "基本单位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "升是容量的基本单位。", "target_word": "基本单位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师问：“温度的基本单位是什么？”", "target_word": "基本单位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你写出重量的基本单位。", "target_word": "基本单位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张表里长度的基本单位是厘米。", "target_word": "基本单位", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}], "register": "中性", "sense_fingerprint": "计数或计量用的最主要的单位，如米、秒、元", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3410f726-dd8b-4348-a976-24df9c72ab9e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87011, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "颜色", "is_correct": false, "explanation": "语义：颜色是物体的外观，不能指长度的单位。"}, {"text": "基本单位", "is_correct": true, "explanation": "正确。米是长度的基本单位，与“米是长度的……”相符。"}, {"text": "声音", "is_correct": false, "explanation": "语义：声音不是计量的对象，不能说“长度的声音”。"}, {"text": "高度", "is_correct": false, "explanation": "搭配：“长度”与“高度”并列，“长度的高度”不通，高度不是长度的单位。"}], "explanations": {"颜色": "语义：颜色是物体的外观，不能指长度的单位。", "基本单位": "正确。米是长度的基本单位，与“米是长度的……”相符。", "声音": "语义：声音不是计量的对象，不能说“长度的声音”。", "高度": "搭配：“长度”与“高度”并列，“长度的高度”不通，高度不是长度的单位。"}, "sentence_index": 0, "correct_answer": "基本单位"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家店的基本单位很便宜。", "explanation": "这里应该用〈价格〉。基本单位是计量的基准单位，商品的贵贱要说价格。"}, {"text": "这家工厂的产品基本单位很严格。", "explanation": "这里应该用〈标准〉。基本单位是计量的基准，对产品的严格要求要说标准。"}, {"text": "这个病人的基本单位很高。", "explanation": "这里应该说〈体温〉。基本单位是计量的基准，人体的温度要说体温。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7fec978a-81e6-4ea1-a989-64a4071cd0d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87011, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "味道", "is_correct": false, "explanation": "语义：味道是食物或气体的感受，不能指容量的单位。"}, {"text": "基本单位", "is_correct": true, "explanation": "正确。升是容量的基本单位，与“升是容量的……”相符。"}, {"text": "形状", "is_correct": false, "explanation": "语义：形状是物体的外形，不能作为计量的单位。"}, {"text": "重量", "is_correct": false, "explanation": "搭配：“容量”与“重量”不能搭配，容量的单位不能说成“容量的重量”。"}], "explanations": {"味道": "语义：味道是食物或气体的感受，不能指容量的单位。", "基本单位": "正确。升是容量的基本单位，与“升是容量的……”相符。", "形状": "语义：形状是物体的外形，不能作为计量的单位。", "重量": "搭配：“容量”与“重量”不能搭配，容量的单位不能说成“容量的重量”。"}, "sentence_index": 6, "correct_answer": "基本单位"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这辆汽车的基本单位很快。", "explanation": "这里应该用〈速度〉。基本单位是计量的基准，汽车的快慢要说速度。"}, {"text": "这种电池的基本单位很长。", "explanation": "这里应该用〈寿命〉。基本单位是计量的基准，电池能用多久要说寿命。"}, {"text": "他的数学基本单位很好。", "explanation": "这里应该用〈成绩〉。基本单位是计量的基准，学习的好坏要说成绩。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7fec978a-81e6-4ea1-a989-64a4071cd0d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87011, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们学习了三张基本单位。", "corrected_sentence": "我们学习了三个基本单位。", "error_description": "「基本单位」的量词应为「个」。「张」用于纸张、桌子等平面的东西，不能用来数「基本单位」。正确说法：我们学习了三个基本单位。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7fec978a-81e6-4ea1-a989-64a4071cd0d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87011, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们学习了两粒基本单位。", "corrected_sentence": "我们学习了两个基本单位。", "error_description": "「基本单位」的量词应为「个」。「粒」用于米、沙等细小的颗粒，不能用来数「基本单位」。正确说法：我们学习了两个基本单位。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7fec978a-81e6-4ea1-a989-64a4071cd0d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
