INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87013, 1, 'prompt1_core', '{"pos": "量词", "semantic_class": "function", "definition": "张是数纸、桌子这些平平的东西的词。", "primary_collocate": null, "pronunciation": "zhāng", "ipa": "ʈʂɑŋ˥", "syllable_count": 1, "sentences": [{"text": "桌子上有一张纸。", "target_word": "张", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我买了两张电影票。", "target_word": "张", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "墙上有一张大地图。", "target_word": "张", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他给我看了一张旧照片。", "target_word": "张", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请给我一张白纸。", "target_word": "张", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "房间里有一张小桌子。", "target_word": "张", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "她手里拿着一张车票。", "target_word": "张", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想要一张新的生日卡片。", "target_word": "张", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他画过一张很大的画。", "target_word": "张", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张桌子很大，可以坐八个人。", "target_word": "张", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "張", "label": "繁体"}, {"form": "张张", "label": "重叠"}], "register": "中性", "sense_fingerprint": "量词，用于纸、票、照片、地图、桌子等平面的东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab628bc3-ddad-4bad-aa8a-0184cfa7bf3e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87013, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "张", "is_correct": true, "explanation": "张 zhāng（第一声）：本题词目，量词，用于纸、票等平面的东西。"}, {"text": "账", "is_correct": false, "explanation": "zhàng（第四声）与 zhāng（第一声）声调不同，意思是账目。"}, {"text": "涨", "is_correct": false, "explanation": "zhǎng（第三声）与 zhāng（第一声）声调不同，意思是上涨。"}, {"text": "脏", "is_correct": false, "explanation": "zāng 与 zhāng 声母不同（z 与 zh），意思是不干净。"}, {"text": "争", "is_correct": false, "explanation": "zhēng 与 zhāng 韵母不同（eng 与 ang），意思是争夺。"}], "explanations": {"张": "张 zhāng（第一声）：本题词目，量词，用于纸、票等平面的东西。", "账": "zhàng（第四声）与 zhāng（第一声）声调不同，意思是账目。", "涨": "zhǎng（第三声）与 zhāng（第一声）声调不同，意思是上涨。", "脏": "zāng 与 zhāng 声母不同（z 与 zh），意思是不干净。", "争": "zhēng 与 zhāng 韵母不同（eng 与 ang），意思是争夺。"}, "sentence_index": null, "correct_answer": "张"}, "level_3": {"options": [{"text": "张", "is_correct": true, "explanation": "张：量词，用于纸等平面的东西，符合句意。"}, {"text": "本", "is_correct": false, "explanation": "语义：“本”指装订成册的书籍，与单张的纸语义不合。"}, {"text": "首", "is_correct": false, "explanation": "搭配：“首”用于诗歌、歌曲，不能用于纸。"}, {"text": "支", "is_correct": false, "explanation": "搭配：“支”用于细长的棍状物，不能用于纸。"}], "explanations": {"张": "张：量词，用于纸等平面的东西，符合句意。", "本": "语义：“本”指装订成册的书籍，与单张的纸语义不合。", "首": "搭配：“首”用于诗歌、歌曲，不能用于纸。", "支": "搭配：“支”用于细长的棍状物，不能用于纸。"}, "sentence_index": 0, "correct_answer": "张"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他给我看了一座旧照片。", "explanation": "这里应该用〈张〉。“座”用于山、房屋等大型固定的东西，照片不这么数。"}, {"text": "他给我看了一支旧照片。", "explanation": "这里应该用〈张〉。“支”用于细长的棍状物，照片不这么数。"}, {"text": "他给我看了一颗旧照片。", "explanation": "这里应该用〈张〉。“颗”用于粒状的圆物，照片不这么数。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a5f4d9a8-94a8-45a0-b85f-25d39fce93ce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87013, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "张", "is_correct": true, "explanation": "张 zhāng（第一声）：本题词目，量词，用于车票等平面的东西。"}, {"text": "掌", "is_correct": false, "explanation": "zhǎng（第三声）与 zhāng（第一声）声调不同，意思是手掌。"}, {"text": "蒸", "is_correct": false, "explanation": "zhēng 与 zhāng 韵母不同（eng 与 ang），意思是蒸煮。"}, {"text": "伤", "is_correct": false, "explanation": "shāng 与 zhāng 声母不同（sh 与 zh），意思是受伤。"}, {"text": "胀", "is_correct": false, "explanation": "zhàng（第四声）与 zhāng（第一声）声调不同，意思是膨胀。"}], "explanations": {"张": "张 zhāng（第一声）：本题词目，量词，用于车票等平面的东西。", "掌": "zhǎng（第三声）与 zhāng（第一声）声调不同，意思是手掌。", "蒸": "zhēng 与 zhāng 韵母不同（eng 与 ang），意思是蒸煮。", "伤": "shāng 与 zhāng 声母不同（sh 与 zh），意思是受伤。", "胀": "zhàng（第四声）与 zhāng（第一声）声调不同，意思是膨胀。"}, "sentence_index": null, "correct_answer": "张"}, "level_3": {"options": [{"text": "张", "is_correct": true, "explanation": "张：量词，用于车票等平面的东西，符合句意。"}, {"text": "册", "is_correct": false, "explanation": "搭配：“册”用于书籍、簿册，不能用于车票。"}, {"text": "台", "is_correct": false, "explanation": "搭配：“台”用于机器、车辆等，不能用于车票。"}, {"text": "幅", "is_correct": false, "explanation": "搭配：“幅”用于字画、图画，不能用于车票。"}], "explanations": {"张": "张：量词，用于车票等平面的东西，符合句意。", "册": "搭配：“册”用于书籍、簿册，不能用于车票。", "台": "搭配：“台”用于机器、车辆等，不能用于车票。", "幅": "搭配：“幅”用于字画、图画，不能用于车票。"}, "sentence_index": 6, "correct_answer": "张"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这辆桌子很大，可以坐八个人。", "explanation": "这里应该用〈张〉。“辆”用于车辆，桌子不这么数。"}, {"text": "这朵桌子很大，可以坐八个人。", "explanation": "这里应该用〈张〉。“朵”用于花、云等，桌子不这么数。"}, {"text": "这头桌子很大，可以坐八个人。", "explanation": "这里应该用〈张〉。“头”用于牲畜等大型动物，桌子不这么数。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a5f4d9a8-94a8-45a0-b85f-25d39fce93ce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_versio