INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87014, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "阳台上放着一张旧沙发，他的一张脚受伤了。", "corrected_sentence": "阳台上放着一张旧沙发，他的一只脚受伤了。", "error_description": "量词错误：“脚”成对，应该用“只”，不能用“张”（“张”用于床、脸等有平面或能张合的东西）。应说“他的一只脚受伤了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a5f4d9a8-94a8-45a0-b85f-25d39fce93ce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87014, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "照片里那张脸我很熟，他的一张腿受伤了。", "corrected_sentence": "照片里那张脸我很熟，他的一条腿受伤了。", "error_description": "量词错误：“腿”用“条”，不能用“张”（“张”用于脸、床等有平面或能张合的东西）。应说“他的一条腿受伤了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a5f4d9a8-94a8-45a0-b85f-25d39fce93ce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
