INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87016, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "property", "definition": "物体的体积、面积或尺寸的大与小。", "primary_collocate": null, "pronunciation": "dà xiǎo", "ipa": "ta˥˩ ɕjaʊ˨˩˦", "syllable_count": 2, "sentences": [{"text": "请量一下这块地的大小。", "target_word": "大小", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这间教室的大小是五十平方米。", "target_word": "大小", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "照片的大小不能太大。", "target_word": "大小", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这块木板的大小是两米乘一米。", "target_word": "大小", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "房子的大小决定了价钱。", "target_word": "大小", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你要先知道窗户的大小，再买窗帘。", "target_word": "大小", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张纸的大小是多少厘米？", "target_word": "大小", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用尺子量了书的大小。", "target_word": "大小", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个行李箱大小合适，可以带上飞机。", "target_word": "大小", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们看看这块布的大小够不够。", "target_word": "大小", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "名词；物体体积、面积、尺寸的量度", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70e7459b-ce0f-48a0-8a3f-b3644c33e3f7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87016, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "大小", "is_correct": true, "explanation": "大小（dà xiǎo）：物体的体积、面积或尺寸的大与小，正是本题要选的词。"}, {"text": "大笑", "is_correct": false, "explanation": "大笑（dà xiào）与 大小 只在第二字声调不同（第四声与第三声），意思是大声地笑。"}, {"text": "大校", "is_correct": false, "explanation": "大校（dà xiào）与 大小 只在第二字声调不同（第四声），意思是军衔之一。"}, {"text": "大脚", "is_correct": false, "explanation": "大脚（dà jiǎo）与 大小 第二字只差声母（j 与 x），意思是脚大。"}], "explanations": {"大小": "大小（dà xiǎo）：物体的体积、面积或尺寸的大与小，正是本题要选的词。", "大笑": "大笑（dà xiào）与 大小 只在第二字声调不同（第四声与第三声），意思是大声地笑。", "大校": "大校（dà xiào）与 大小 只在第二字声调不同（第四声），意思是军衔之一。", "大脚": "大脚（dà jiǎo）与 大小 第二字只差声母（j 与 x），意思是脚大。"}, "sentence_index": null, "correct_answer": "大小"}, "level_3": {"options": [{"text": "大小", "is_correct": true, "explanation": "大小：要量的是地的尺寸，符合「量一下这块地的大小」。"}, {"text": "重量", "is_correct": false, "explanation": "语义：「重量」指物体的轻重，量一块地的重量不合常理。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：「年龄」只用于人或动物，不能用来说土地。"}, {"text": "身量", "is_correct": false, "explanation": "语域：「身量」是书面语，指人的身高体形，用于土地既不合语域也不合语义。"}], "explanations": {"大小": "大小：要量的是地的尺寸，符合「量一下这块地的大小」。", "重量": "语义：「重量」指物体的轻重，量一块地的重量不合常理。", "年龄": "语义：「年龄」只用于人或动物，不能用来说土地。", "身量": "语域：「身量」是书面语，指人的身高体形，用于土地既不合语域也不合语义。"}, "sentence_index": 0, "correct_answer": "大小"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这场电影的大小是两个小时。", "explanation": "这里应该用〈时长〉。「大小」指物体的体积或尺寸，不能用来说电影放映多久。"}, {"text": "这列火车的大小很快。", "explanation": "这里应该用〈速度〉。「大小」指尺寸，不能用来形容火车的快慢。"}, {"text": "这件衣服的大小很鲜艳。", "explanation": "这里应该用〈颜色〉。「大小」指尺寸，不能用来形容衣服的颜色。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '223ca4a0-75e9-44e0-8a77-bf4baaef43f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87016, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "大小", "is_correct": true, "explanation": "大小：询问的是纸的尺寸，「多少厘米」可以用来问长度或宽度，符合句意。"}, {"text": "价格", "is_correct": false, "explanation": "语义：「价格」指买卖的价钱，与「多少厘米」的计量相矛盾。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：「多少厘米」只用于问长度或宽度，不能用来问颜色。"}, {"text": "味道", "is_correct": false, "explanation": "语义：「味道」指气味或滋味，纸不能用厘米来计量味道。"}], "explanations": {"大小": "大小：询问的是纸的尺寸，「多少厘米」可以用来问长度或宽度，符合句意。", "价格": "语义：「价格」指买卖的价钱，与「多少厘米」的计量相矛盾。", "颜色": "搭配：「多少厘米」只用于问长度或宽度，不能用来问颜色。", "味道": "语义：「味道」指气味或滋味，纸不能用厘米来计量味道。"}, "sentence_index": 6, "correct_answer": "大小"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这碗汤的大小很咸。", "explanation": "这里应该用〈味道〉。「大小」指尺寸，不能用来形容汤的咸淡。"}, {"text": "这箱苹果的大小是十公斤。", "explanation": "这里应该用〈重量〉。「大小」指体积或尺寸，不能用来计量重量。"}, {"text": "这道菜的大小很香。", "explanation": "这里应该用〈香味〉。「大小」指尺寸，不能用来形容菜的香味。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '223ca4a0-75e9-44e0-8a77-bf4baaef43f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87016, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个包装有三个大小可以选。", "corrected_sentence": "这个包装有三种大小可以选。", "error_description": "错误：「三个大小」；正确：「三种大小」。「大小」指尺寸的类别，计量时用量词「种」，不用「个」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '223ca4a0-75e9-44e0-8a77-bf4baaef43f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87016, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "你知道这块布的多大小吗？", "corrected_sentence": "你知道这块布的大小吗？", "error_description": "错误：「的多大小」；正确：「的大小」。「多」只与形容词「大」组成「多大」，不能与名词「大小」组合。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '223ca4a0-75e9-44e0-8a77-bf4baaef43f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
