INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87021, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "婚姻是一个男人和一个女人结了婚，成为一家人。", "primary_collocate": null, "pronunciation": "hūn yīn", "ipa": "xwən˥ in˥", "syllable_count": 2, "sentences": [{"text": "他们的婚姻很幸福，每天都有笑声。", "target_word": "婚姻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷和奶奶的婚姻已经有五十年了。", "target_word": "婚姻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好的婚姻需要两个人互相信任。", "target_word": "婚姻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她对自己的婚姻非常满意。", "target_word": "婚姻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这段婚姻让他有了一个温暖的家。", "target_word": "婚姻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "结婚以后，婚姻生活和以前不一样。", "target_word": "婚姻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们的婚姻只维持了三年就结束了。", "target_word": "婚姻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈常说，婚姻是两家人的事。", "target_word": "婚姻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她很用心地经营自己的婚姻。", "target_word": "婚姻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友的婚姻出了问题，他很难过。", "target_word": "婚姻", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "段", "label": "量词"}], "register": "中性", "sense_fingerprint": "婚姻：男女结婚后成为一家人的生活状态", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '46f86a8e-c93b-4cfe-95df-f413bcbe6177') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87021, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "婚姻", "is_correct": true, "explanation": "正确。“婚姻”指结婚后两人的生活关系，可以幸福，并与“每天都有笑声”相配。"}, {"text": "婚礼", "is_correct": false, "explanation": "语义：婚礼是一次性的仪式，不能用“每天都有笑声”描述它的持续状态。"}, {"text": "汽车", "is_correct": false, "explanation": "语义：汽车是机器，不能感到幸福，也发不出笑声。"}, {"text": "房子", "is_correct": false, "explanation": "语义：房子是物体，不会感到幸福，也不会有笑声。"}], "explanations": {"婚姻": "正确。“婚姻”指结婚后两人的生活关系，可以幸福，并与“每天都有笑声”相配。", "婚礼": "语义：婚礼是一次性的仪式，不能用“每天都有笑声”描述它的持续状态。", "汽车": "语义：汽车是机器，不能感到幸福，也发不出笑声。", "房子": "语义：房子是物体，不会感到幸福，也不会有笑声。"}, "sentence_index": 0, "correct_answer": "婚姻"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他们终于买到了温暖的婚姻。", "explanation": "这里应该用〈房子〉。买到的是房子这类实物，婚姻是两人之间的关系，不能买。"}, {"text": "我们的婚姻在春天举行得很顺利。", "explanation": "这里应该用〈婚礼〉。婚礼是可以举行的仪式，婚姻是结婚后的关系，不能“举行”。"}, {"text": "他是我的婚姻，我们一起生活了十年。", "explanation": "这里应该用〈爱人〉。爱人指配偶这个人，婚姻是两人之间的关系，不能指人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '491bcf82-a5b3-404e-b5b2-c49d94b80e18') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87021, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "天气", "is_correct": false, "explanation": "语义：天气是自然现象，不能作为“维持三年后结束”的对象。"}, {"text": "婚姻", "is_correct": true, "explanation": "正确。“婚姻”是可以“维持”一段时间后“结束”的两人关系，符合语境。"}, {"text": "外貌", "is_correct": false, "explanation": "体貌：外貌是人的外在形象，不能说“维持三年就结束”。"}, {"text": "孩子", "is_correct": false, "explanation": "语义：孩子是人，不是关系或状态，不能说“维持三年就结束”。"}], "explanations": {"天气": "语义：天气是自然现象，不能作为“维持三年后结束”的对象。", "婚姻": "正确。“婚姻”是可以“维持”一段时间后“结束”的两人关系，符合语境。", "外貌": "体貌：外貌是人的外在形象，不能说“维持三年就结束”。", "孩子": "语义：孩子是人，不是关系或状态，不能说“维持三年就结束”。"}, "sentence_index": 6, "correct_answer": "婚姻"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这段婚姻有五个成员，大家都很和睦。", "explanation": "这里应该用〈家庭〉。家庭由成员组成，婚姻是两人结合的关系，不能说有几个成员。"}, {"text": "她从包里拿出了婚姻。", "explanation": "这里应该用〈结婚证〉。结婚证是可以拿出的证件，婚姻是关系，不是实物。"}, {"text": "她的婚姻已经不小了。", "explanation": "这里应该用〈年龄〉。年龄可以说大或小，婚姻不能用“不小”来形容。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '491bcf82-a5b3-404e-b5b2-c49d94b80e18') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87021, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们经历了一只很长的婚姻。", "corrected_sentence": "我们经历了一段很长的婚姻。", "error_description": "量词错误：“婚姻”应该用量词“段”，不能用“只”（“只”用于动物或成对物品中的单个）。错误形式：一只婚姻；正确形式：一段婚姻。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '491bcf82-a5b3-404e-b5b2-c49d94b80e18') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87021, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们努力维持这只婚姻。", "corrected_sentence": "他们努力维持这段婚姻。", "error_description": "量词错误：“婚姻”应该用量词“段”，不能用“只”。错误形式：这只婚姻；正确形式：这段婚姻。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '491bcf82-a5b3-404e-b5b2-c49d94b80e18') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
