INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87022, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "男女双方经法律或社会承认而结成夫妻的关系。", "primary_collocate": null, "pronunciation": "hūn yīn", "ipa": "xwən˥ in˥", "syllable_count": 2, "sentences": [{"text": "法律保护合法的婚姻。", "target_word": "婚姻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个国家不承认这种婚姻。", "target_word": "婚姻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们的婚姻在法律上已经结束了。", "target_word": "婚姻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "结婚时要先到民政局登记，婚姻才有效。", "target_word": "婚姻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "婚姻关系需要法律承认。", "target_word": "婚姻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两个人没有登记，不算合法婚姻。", "target_word": "婚姻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "法律规定，婚姻自由，别人不能干涉。", "target_word": "婚姻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想结束这段婚姻，决定去法院。", "target_word": "婚姻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "法官说，这段婚姻从一开始就无效。", "target_word": "婚姻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "离婚以后，婚姻关系就不存在了。", "target_word": "婚姻", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "段", "label": "量词"}], "register": "正式", "sense_fingerprint": "婚姻：经法律或社会承认的夫妻关系", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '46f86a8e-c93b-4cfe-95df-f413bcbe6177') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87022, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "感情", "is_correct": false, "explanation": "语义：感情是心理状态，不是法律保护的关系，不能说“合法的感情”。"}, {"text": "婚姻", "is_correct": true, "explanation": "正确。“婚姻”是经法律承认的夫妻关系，可以“合法”，并受法律保护。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气是自然现象，不可能“合法”，法律也不保护它。"}, {"text": "信用", "is_correct": false, "explanation": "搭配：“合法的”一般修饰婚姻、收入、行为，不说“合法的信用”。"}], "explanations": {"感情": "语义：感情是心理状态，不是法律保护的关系，不能说“合法的感情”。", "婚姻": "正确。“婚姻”是经法律承认的夫妻关系，可以“合法”，并受法律保护。", "天气": "语义：天气是自然现象，不可能“合法”，法律也不保护它。", "信用": "搭配：“合法的”一般修饰婚姻、收入、行为，不说“合法的信用”。"}, "sentence_index": 0, "correct_answer": "婚姻"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他们在律师的见证下签订了婚姻。", "explanation": "这里应该用〈合同〉。签订用于合同、协议，婚姻是关系，不能签订。"}, {"text": "他决定起诉婚姻。", "explanation": "这里应该用〈对方〉。起诉的对象是人或机构，婚姻是关系，不能被起诉。"}, {"text": "婚姻保护公民的权利。", "explanation": "这里应该用〈宪法〉。宪法是保护者，婚姻是关系，不能做“保护”的主语。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '491bcf82-a5b3-404e-b5b2-c49d94b80e18') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87022, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "身高", "is_correct": false, "explanation": "体貌：身高是身体特征，不属于可以“自由”、别人不能干涉的事。"}, {"text": "粮食", "is_correct": false, "explanation": "语义：粮食是物资，不是个人可以自由决定、受法律保护的关系。"}, {"text": "婚姻", "is_correct": true, "explanation": "正确。“婚姻自由”指结婚与否由个人决定，别人不能干涉，符合语境。"}, {"text": "工资", "is_correct": false, "explanation": "搭配：“自由”通常修饰婚姻、信仰、言论等，不说“工资自由”。"}], "explanations": {"身高": "体貌：身高是身体特征，不属于可以“自由”、别人不能干涉的事。", "粮食": "语义：粮食是物资，不是个人可以自由决定、受法律保护的关系。", "婚姻": "正确。“婚姻自由”指结婚与否由个人决定，别人不能干涉，符合语境。", "工资": "搭配：“自由”通常修饰婚姻、信仰、言论等，不说“工资自由”。"}, "sentence_index": 6, "correct_answer": "婚姻"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "婚姻在教堂举行，很多人都来了。", "explanation": "这里应该用〈婚礼〉。婚礼是可以举行的仪式，婚姻是关系，不能“举行”。"}, {"text": "这段婚姻有很多员工，大家都很努力。", "explanation": "这里应该用〈公司〉。公司有员工，婚姻是两人之间的关系，不能说有员工。"}, {"text": "他把婚姻搬上了车。", "explanation": "这里应该用〈行李〉。搬用于行李、家具等实物，婚姻是两人之间的法律关系，不能被搬动。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '491bcf82-a5b3-404e-b5b2-c49d94b80e18') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87022, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这种婚姻被不法律承认。", "corrected_sentence": "这种婚姻不被法律承认。", "error_description": "否定词“不”应放在“被”之前。错误形式：被不法律承认；正确形式：不被法律承认。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '491bcf82-a5b3-404e-b5b2-c49d94b80e18') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87022, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "法院把这只婚姻判为无效。", "corrected_sentence": "法院把这段婚姻判为无效。", "error_description": "量词错误：“婚姻”应该用量词“段”，不能用“只”。错误形式：这只婚姻；正确形式：这段婚姻。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '491bcf82-a5b3-404e-b5b2-c49d94b80e18') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87025, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "古代", "is_correct": true, "explanation": "古代与现代相对，指离今天较远的时期，二者是反义关系。"}, {"text": "农村", "is_correct": false, "explanation": "农村是地域概念，与时期无关，不与“现代”构成反义。"}, {"text": "海洋", "is_correct": false, "explanation": "海洋是自然地理事物，与“现代”无关。"}, {"text": "运动", "is_correct": false, "explanation": "运动指身体活动或社会活动，与“现代”不构成反义关系。"}], "correct_answer": "古代", "explanations": {"古代": "古代与现代相对，指离今天较远的时期，二者是反义关系。", "农村": "农村是地域概念，与时期无关，不与“现代”构成反义。", "海洋": "海洋是自然地理事物，与“现代”无关。", "运动": "运动指身体活动或社会活动，与“现代”不构成反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '05d51723-abb3-4319-a185-155b7c3c894e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87025, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "古代", "is_correct": true, "explanation": "古代与现代相对，指离今天较远的时期，二者是反义关系。"}, {"text": "乡村", "is_correct": false, "explanation": "乡村是地域概念，与时期无关，不与“现代”构成反义。"}, {"text": "森林", "is_correct": false, "explanation": "森林是自然事物，与“现代”无关。"}, {"text": "火车", "is_correct": false, "explanation": "火车是交通工具，与“现代”不构成反义关系。"}], "correct_answer": "古代", "explanations": {"古代": "古代与现代相对，指离今天较远的时期，二者是反义关系。", "乡村": "乡村是地域概念，与时期无关，不与“现代”构成反义。", "森林": "森林是自然事物，与“现代”无关。", "火车": "火车是交通工具，与“现代”不构成反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '05d51723-abb3-4319-a185-155b7c3c894e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87025, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "现代是离我们现在不太远的这个时代。", "primary_collocate": null, "pronunciation": "xiàn dài", "ipa": "ɕjɛn˥˩ taɪ˥˩", "syllable_count": 2, "sentences": [{"text": "古代的人写信，现代的人发短信。", "target_word": "现代", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座桥是现代才建起来的。", "target_word": "现代", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要比较古代和现代的房子。", "target_word": "现代", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书讲的是中国现代的历史。", "target_word": "现代", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "现代离我们不太远，只有一百年。", "target_word": "现代", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "博物馆左边是古代的东西，右边是现代的东西。", "target_word": "现代", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这是一幅现代的画，不是古代的。", "target_word": "现代", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些照片属于现代，看起来不太旧。", "target_word": "现代", "complexity_tier": "T3", "furigana": "zhè xiē zhào piàn shǔ yú xiàn dài, kàn qǐ lái bú tài jiù", "sentence_source": "generated"}, {"text": "在现代，中国发生了很大的变化。", "target_word": "现代", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "现代的作家写的小说，我都喜欢。", "target_word": "现代", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "现代人", "label": "复合"}, {"form": "现代化", "label": "复合"}], "register": "中性", "sense_fingerprint": "现代：与古代相对，离今天不太远的时期", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b92bc1c1-4d96-48cc-99fc-e04394caba7e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87025, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "现代", "is_correct": true, "explanation": "正确：与前句“古代”形成对比，表示当今的人。"}, {"text": "古代", "is_correct": false, "explanation": "语义：前后两句都说“古代”，失去了与“现代”的对比。"}, {"text": "远古", "is_correct": false, "explanation": "语义：远古时代还没有短信，与“发短信”相矛盾。"}, {"text": "明朝", "is_correct": false, "explanation": "搭配：“明朝”是朝代名，与“的人发短信”的时间搭配不通。"}], "explanations": {"现代": "正确：与前句“古代”形成对比，表示当今的人。", "古代": "语义：前后两句都说“古代”，失去了与“现代”的对比。", "远古": "语义：远古时代还没有短信，与“发短信”相矛盾。", "明朝": "搭配：“明朝”是朝代名，与“的人发短信”的时间搭配不通。"}, "sentence_index": 0, "correct_answer": "现代"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我的现代很努力。", "explanation": "这里应该用〈同学〉。现代是时间名词，只指一段时代，不能指人，“我的同学很努力”中的人要用〈同学〉。"}, {"text": "这位现代很认真。", "explanation": "这里应该用〈老师〉。现代指时代，不能指人，“这位老师很认真”中的人要用〈老师〉。"}, {"text": "现代很热。", "explanation": "这里应该用〈今天〉。现代指一个时代，不能指某一天的天气。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '05d51723-abb3-4319-a185-155b7c3c894e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87025, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "现代", "is_correct": true, "explanation": "正确：与后半句“不是古代的”相对，表示当代的画。"}, {"text": "古代", "is_correct": false, "explanation": "语义：“不是古代的”与“古代的画”自相矛盾，句意不通。"}, {"text": "唐朝", "is_correct": false, "explanation": "语义：唐朝属于古代，与“不是古代的”的对比相矛盾。"}, {"text": "汉朝", "is_correct": false, "explanation": "语义：汉朝属于古代，与“不是古代的”的对比相矛盾。"}], "explanations": {"现代": "正确：与后半句“不是古代的”相对，表示当代的画。", "古代": "语义：“不是古代的”与“古代的画”自相矛盾，句意不通。", "唐朝": "语义：唐朝属于古代，与“不是古代的”的对比相矛盾。", "汉朝": "语义：汉朝属于古代，与“不是古代的”的对比相矛盾。"}, "sentence_index": 6, "correct_answer": "现代"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "现代是下午三点。", "explanation": "这里应该用〈现在〉。现代是指一个时代的名词，不能用来指具体的时刻。"}, {"text": "他每天在现代上班八小时。", "explanation": "这里应该用〈公司〉。现代不是工作的场所，要说“在公司上班”。"}, {"text": "我们明天去现代吃饭。", "explanation": "这里应该用〈餐厅〉。现代是时代名称，不能作地点名词，去吃饭要说“去餐厅”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '05d51723-abb3-4319-a185-155b7c3c894e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87025, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "现代了的建筑和古代的很不一样。", "corrected_sentence": "现代的建筑和古代的很不一样。", "error_description": "错误：“现代”后多加了“了”，“了”不能插在修饰语和中心语之间。应写作“现代的建筑”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '05d51723-abb3-4319-a185-155b7c3c894e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87025, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "现代地作家写得很好。", "corrected_sentence": "现代的作家写得很好。", "error_description": "错误：修饰名词“作家”要用“的”，“地”用来修饰动词或形容词。应写作“现代的作家”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '05d51723-abb3-4319-a185-155b7c3c894e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87026, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "古代", "is_correct": true, "explanation": "古代与现代在时间上相对，指过去的时代，二者是反义关系。"}, {"text": "历史", "is_correct": false, "explanation": "历史指过去发生的事情及其记载，与“现代”不构成反义关系。"}, {"text": "农村", "is_correct": false, "explanation": "农村是地域概念，与时代无关，不与“现代”构成反义。"}, {"text": "海洋", "is_correct": false, "explanation": "海洋是自然地理事物，与“现代”的时代含义无关。"}], "correct_answer": "古代", "explanations": {"古代": "古代与现代在时间上相对，指过去的时代，二者是反义关系。", "历史": "历史指过去发生的事情及其记载，与“现代”不构成反义关系。", "农村": "农村是地域概念，与时代无关，不与“现代”构成反义。", "海洋": "海洋是自然地理事物，与“现代”的时代含义无关。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '05d51723-abb3-4319-a185-155b7c3c894e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87026, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "古代", "is_correct": true, "explanation": "古代与现代在时间上相对，指过去的时代，二者是反义关系。"}, {"text": "乡村", "is_correct": false, "explanation": "乡村是地域概念，与时代无关，不与“现代”构成反义。"}, {"text": "森林", "is_correct": false, "explanation": "森林是自然事物，与“现代”的时代含义无关。"}, {"text": "火车", "is_correct": false, "explanation": "火车是交通工具，与“现代”不构成反义关系。"}], "correct_answer": "古代", "explanations": {"古代": "古代与现代在时间上相对，指过去的时代，二者是反义关系。", "乡村": "乡村是地域概念，与时代无关，不与“现代”构成反义。", "森林": "森林是自然事物，与“现代”的时代含义无关。", "火车": "火车是交通工具，与“现代”不构成反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '05d51723-abb3-4319-a185-155b7c3c894e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87026, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指当代；现在这个时代。", "primary_collocate": null, "pronunciation": "xiàn dài", "ipa": "ɕjɛn˥˩ taɪ˥˩", "syllable_count": 2, "sentences": [{"text": "在现代，人们可以用手机买东西。", "target_word": "现代", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "现代的生活比以前方便多了。", "target_word": "现代", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他喜欢研究现代的音乐。", "target_word": "现代", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家医院用的是现代的技术。", "target_word": "现代", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "现代的年轻人常常很忙。", "target_word": "现代", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "现代的城市里有很多高楼。", "target_word": "现代", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她在书里写了现代的故事。", "target_word": "现代", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在现代，坐飞机去别的国家很平常。", "target_word": "现代", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个电影说的是现代的事情。", "target_word": "现代", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，现代的孩子知道得很多。", "target_word": "现代", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "现代人", "label": "复合"}, {"form": "现代化", "label": "复合"}], "register": "中性", "sense_fingerprint": "现代：当代，我们现在生活的这个时代", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b92bc1c1-4d96-48cc-99fc-e04394caba7e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87026, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "现代", "is_correct": true, "explanation": "正确：“在现代”指当今这个时代，与用手机买东西的语境相符。"}, {"text": "古代", "is_correct": false, "explanation": "语义：古代没有手机，与“用手机买东西”相矛盾。"}, {"text": "上古", "is_correct": false, "explanation": "语域：“上古”是书面用语，口语中一般不这样说，且与“用手机买东西”冲突。"}, {"text": "明朝", "is_correct": false, "explanation": "语义：明朝时期没有手机，与句中“用手机买东西”冲突。"}], "explanations": {"现代": "正确：“在现代”指当今这个时代，与用手机买东西的语境相符。", "古代": "语义：古代没有手机，与“用手机买东西”相矛盾。", "上古": "语域：“上古”是书面用语，口语中一般不这样说，且与“用手机买东西”冲突。", "明朝": "语义：明朝时期没有手机，与句中“用手机买东西”冲突。"}, "sentence_index": 0, "correct_answer": "现代"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这是一个新的现代。", "explanation": "这里应该用〈时代〉。现代专指当今这一时期，不能说“一个现代”“新的现代”，泛指一段历史要用〈时代〉。"}, {"text": "我的现代很聪明。", "explanation": "这里应该用〈朋友〉。现代是指时代的名词，不能指人，指人要用〈朋友〉。"}, {"text": "那段现代很难忘。", "explanation": "这里应该用〈时期〉。现代专指当下这个时代，不能用来指一段有限的时间。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '05d51723-abb3-4319-a185-155b7c3c894e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87026, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "现代", "is_correct": true, "explanation": "正确：“写了现代的故事”指以当今时代为背景的故事，与句意相符。"}, {"text": "然后", "is_correct": false, "explanation": "语法：“然后”是连词，不能修饰“故事”，“写了然后的故事”不成立。"}, {"text": "因为", "is_correct": false, "explanation": "语法：“因为”是连词，不能修饰“故事”，“写了因为的故事”不成立。"}, {"text": "吗", "is_correct": false, "explanation": "语法：“吗”是语气词，不能修饰名词，“写了吗的故事”不成立。"}], "explanations": {"现代": "正确：“写了现代的故事”指以当今时代为背景的故事，与句意相符。", "然后": "语法：“然后”是连词，不能修饰“故事”，“写了然后的故事”不成立。", "因为": "语法：“因为”是连词，不能修饰“故事”，“写了因为的故事”不成立。", "吗": "语法：“吗”是语气词，不能修饰名词，“写了吗的故事”不成立。"}, "sentence_index": 6, "correct_answer": "现代"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "现代是晚上九点。", "explanation": "这里应该用〈现在〉。现代是指一个时代的名词，不能用来指具体的时刻。"}, {"text": "我们明天去现代吃饭。", "explanation": "这里应该用〈餐厅〉。现代是时代名称，不能作地点名词，去吃饭要说“去餐厅”。"}, {"text": "他每天在现代学习八小时。", "explanation": "这里应该用〈学校〉。现代不是学习的场所，要说“在学校学习”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '05d51723-abb3-4319-a185-155b7c3c894e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87026, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "在现代了，人们常常靠网络学习。", "corrected_sentence": "在现代，人们常常靠网络学习。", "error_description": "错误：“现代”后多加了“了”。“现代”是时间名词，不能带“了”，应去掉“了”，写作“在现代，……”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '05d51723-abb3-4319-a185-155b7c3c894e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87026, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "现代地音乐很受年轻人欢迎。", "corrected_sentence": "现代的音乐很受年轻人欢迎。", "error_description": "错误：修饰名词“音乐”要用“的”，“地”用来修饰动词或形容词。应写作“现代的音乐”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '05d51723-abb3-4319-a185-155b7c3c894e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
