INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87035, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们谈了过这件事。", "corrected_sentence": "我们谈过这件事。", "error_description": "错误：“了”与“过”不能同时用于同一动词，“过”表示经历，应紧跟在“谈”后面，写作“谈过这件事”，去掉多余的“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '05d51723-abb3-4319-a185-155b7c3c894e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
