INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87045, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "办是去做一件事，把它做好。", "primary_collocate": null, "pronunciation": "bàn", "ipa": "pan˥˩", "syllable_count": 1, "sentences": [{"text": "这件事交给我，我一定办好。", "target_word": "办", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你放心，我会把它办完的。", "target_word": "办", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他办这件事很认真。", "target_word": "办", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天我有三件事要办。", "target_word": "办", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师让我去办一件小事。", "target_word": "办", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸出门去办一件事。", "target_word": "办", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个问题不难，很快就能办成。", "target_word": "办", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他答应的事，从来都办得很好。", "target_word": "办", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "快去吧，办完就回来。", "target_word": "办", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友请我帮忙，我马上就去办。", "target_word": "办", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "办了", "label": "体标"}, {"form": "办过", "label": "体标"}, {"form": "办理", "label": "复合"}, {"form": "辦", "label": "繁体"}], "register": "口语", "sense_fingerprint": "办：去做一件事并把它做好、做成", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b92bc1c1-4d96-48cc-99fc-e04394caba7e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87045, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "办", "is_correct": true, "explanation": "正确答案：办（bàn，第四声），意思是去做事并做好。"}, {"text": "班", "is_correct": false, "explanation": "bān（第一声）与 bàn（第四声）声调不同，意思是班级。"}, {"text": "板", "is_correct": false, "explanation": "bǎn（第三声）与 bàn（第四声）声调不同，意思是木板。"}, {"text": "判", "is_correct": false, "explanation": "pàn 与 bàn 声母不同（p 与 b），意思是判断、判决。"}, {"text": "棒", "is_correct": false, "explanation": "bàng 与 bàn 韵尾不同（ng 与 n），意思是棒子、很好。"}, {"text": "慢", "is_correct": false, "explanation": "màn 与 bàn 声母不同（m 与 b），意思是缓慢。"}], "explanations": {"办": "正确答案：办（bàn，第四声），意思是去做事并做好。", "班": "bān（第一声）与 bàn（第四声）声调不同，意思是班级。", "板": "bǎn（第三声）与 bàn（第四声）声调不同，意思是木板。", "判": "pàn 与 bàn 声母不同（p 与 b），意思是判断、判决。", "棒": "bàng 与 bàn 韵尾不同（ng 与 n），意思是棒子、很好。", "慢": "màn 与 bàn 声母不同（m 与 b），意思是缓慢。"}, "sentence_index": null, "correct_answer": "办"}, "level_3": {"options": [{"text": "唱", "is_correct": false, "explanation": "语义：“唱”的对象是歌曲，不能指处理“这件事”。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃”的对象是食物，不能指处理“这件事”。"}, {"text": "办", "is_correct": true, "explanation": "正确：“我一定办好”表示一定把这件事做好，符合句中交付事情的语境。"}, {"text": "洗", "is_correct": false, "explanation": "搭配：“洗”的对象是衣物、餐具等，不能和“这件事”搭配。"}], "explanations": {"唱": "语义：“唱”的对象是歌曲，不能指处理“这件事”。", "吃": "语义：“吃”的对象是食物，不能指处理“这件事”。", "办": "正确：“我一定办好”表示一定把这件事做好，符合句中交付事情的语境。", "洗": "搭配：“洗”的对象是衣物、餐具等，不能和“这件事”搭配。"}, "sentence_index": 0, "correct_answer": "办"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈每天都办碗。", "explanation": "这里应该用〈洗〉。办表示去做事、把事做好，不用于清洗餐具。"}, {"text": "他会办钢琴。", "explanation": "这里应该用〈演奏〉。办指处理事务，不能说“办钢琴”。"}, {"text": "我今天办了两个苹果。", "explanation": "这里应该用〈吃〉。办不能用来指进食。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '05d51723-abb3-4319-a185-155b7c3c894e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87045, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "办", "is_correct": true, "explanation": "正确答案：办（bàn，第四声），意思是去做事并做好。"}, {"text": "笨", "is_correct": false, "explanation": "bèn 与 bàn 韵母不同（en 与 an），意思是笨拙。"}, {"text": "盼", "is_correct": false, "explanation": "pàn 与 bàn 声母不同（p 与 b），意思是盼望。"}, {"text": "败", "is_correct": false, "explanation": "bài 与 bàn 韵母不同（ai 与 an），意思是失败。"}, {"text": "版", "is_correct": false, "explanation": "bǎn（第三声）与 bàn（第四声）声调不同，意思是版本、版面。"}], "explanations": {"办": "正确答案：办（bàn，第四声），意思是去做事并做好。", "笨": "bèn 与 bàn 韵母不同（en 与 an），意思是笨拙。", "盼": "pàn 与 bàn 声母不同（p 与 b），意思是盼望。", "败": "bài 与 bàn 韵母不同（ai 与 an），意思是失败。", "版": "bǎn（第三声）与 bàn（第四声）声调不同，意思是版本、版面。"}, "sentence_index": null, "correct_answer": "办"}, "level_3": {"options": [{"text": "咬", "is_correct": false, "explanation": "语义：“咬”的对象是具体物体，不能指“问题”被处理。"}, {"text": "哭", "is_correct": false, "explanation": "搭配：“哭成”多指哭的结果，如“哭成泪人”，不能与“问题”搭配。"}, {"text": "办", "is_correct": true, "explanation": "正确：“很快就能办成”表示很快就能办出结果，符合句中“问题不难”的语境。"}, {"text": "笑", "is_correct": false, "explanation": "语义：“笑”的动作与“问题”无关，句子无法表达处理问题。"}], "explanations": {"咬": "语义：“咬”的对象是具体物体，不能指“问题”被处理。", "哭": "搭配：“哭成”多指哭的结果，如“哭成泪人”，不能与“问题”搭配。", "办": "正确：“很快就能办成”表示很快就能办出结果，符合句中“问题不难”的语境。", "笑": "语义：“笑”的动作与“问题”无关，句子无法表达处理问题。"}, "sentence_index": 6, "correct_answer": "办"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈在厨房办水。", "explanation": "这里应该用〈烧〉。办不用于加热液体，“办水”不成立。"}, {"text": "她很会办歌。", "explanation": "这里应该用〈唱〉。办不指歌唱，“办歌”不成立。"}, {"text": "我每天认真办字。", "explanation": "这里应该用〈写〉。办不用于书写，“办字”不成立。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '05d51723-abb3-4319-a185-155b7c3c894e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_ve