INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87055, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "不日是过不了几天，就要到了。", "primary_collocate": null, "pronunciation": "bú rì", "ipa": "pu˧˥ ʐʅ˥˩", "syllable_count": 2, "sentences": [{"text": "新书不日就会上市。", "target_word": "不日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不日将回国探亲。", "target_word": "不日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新的地铁线不日开通。", "target_word": "不日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "展览不日开幕，欢迎大家参观。", "target_word": "不日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "校长不日将到我们学校。", "target_word": "不日", "complexity_tier": "T3", "furigana": "xiàozhǎng búrì jiāng dào wǒmen xuéxiào.", "sentence_source": "generated"}, {"text": "这位老人不日就要出院了。", "target_word": "不日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司不日将公布新的计划。", "target_word": "不日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们不日启程前往北京。", "target_word": "不日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "检查结果不日就能出来。", "target_word": "不日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好消息不日会传到你家。", "target_word": "不日", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面语", "sense_fingerprint": "副词；过不了几天就要发生；多用于通知、新闻", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b92bc1c1-4d96-48cc-99fc-e04394caba7e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87055, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "不日", "is_correct": true, "explanation": "正确答案：不日（bú rì），意思是过几天就要。"}, {"text": "不是", "is_correct": false, "explanation": "shì 与 rì 声母不同（sh 与 r），意思是“不是”。"}, {"text": "不利", "is_correct": false, "explanation": "lì 与 rì 声母不同（l 与 r），意思是不利于。"}, {"text": "不计", "is_correct": false, "explanation": "jì 与 rì 声母不同（j 与 r），意思是不计较、不计算。"}], "explanations": {"不日": "正确答案：不日（bú rì），意思是过几天就要。", "不是": "shì 与 rì 声母不同（sh 与 r），意思是“不是”。", "不利": "lì 与 rì 声母不同（l 与 r），意思是不利于。", "不计": "jì 与 rì 声母不同（j 与 r），意思是不计较、不计算。"}, "sentence_index": null, "correct_answer": "不日"}, "level_3": {"options": [{"text": "从来", "is_correct": false, "explanation": "语义：“从来”指一向如此，与“就会上市”的将来不合。"}, {"text": "偶尔", "is_correct": false, "explanation": "语义：“偶尔”表示有时，不能表示不久之后就发生。"}, {"text": "不日", "is_correct": true, "explanation": "正确：“不日就会上市”表示过几天就会上市，符合句中新书的语境。"}, {"text": "曾经", "is_correct": false, "explanation": "体貌：“曾经”指过去的经历，与“就会”的将来不合。"}], "explanations": {"从来": "语义：“从来”指一向如此，与“就会上市”的将来不合。", "偶尔": "语义：“偶尔”表示有时，不能表示不久之后就发生。", "不日": "正确：“不日就会上市”表示过几天就会上市，符合句中新书的语境。", "曾经": "体貌：“曾经”指过去的经历，与“就会”的将来不合。"}, "sentence_index": 0, "correct_answer": "不日"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "门铃一响，他不日就开门。", "explanation": "这里应该用〈马上〉。不日指过几天才发生，不能用于门铃一响就立刻开门的动作。"}, {"text": "他昨天不日出院了。", "explanation": "这里应该用〈前几天〉。不日指不久之后，不能用于已经过去的“昨天”。"}, {"text": "我每天不日都跑步。", "explanation": "这里应该用〈经常〉。不日指不久之后的一次性事件，不能表示反复发生的跑步。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '05d51723-abb3-4319-a185-155b7c3c894e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87055, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "不日", "is_correct": true, "explanation": "正确答案：不日（bú rì），意思是过几天就要。"}, {"text": "不必", "is_correct": false, "explanation": "bì 与 rì 声母不同（b 与 r），意思是没有必要。"}, {"text": "不至", "is_correct": false, "explanation": "zhì 与 rì 声母不同（zh 与 r），意思是不至于。"}, {"text": "不易", "is_correct": false, "explanation": "yì 与 rì 声母不同（y 与 r），意思是不容易。"}], "explanations": {"不日": "正确答案：不日（bú rì），意思是过几天就要。", "不必": "bì 与 rì 声母不同（b 与 r），意思是没有必要。", "不至": "zhì 与 rì 声母不同（zh 与 r），意思是不至于。", "不易": "yì 与 rì 声母不同（y 与 r），意思是不容易。"}, "sentence_index": null, "correct_answer": "不日"}, "level_3": {"options": [{"text": "已经", "is_correct": false, "explanation": "体貌：“已经”表示已经完成，与“将公布”的将来矛盾。"}, {"text": "一向", "is_correct": false, "explanation": "语义：“一向”指长期习惯，不能用于一次性的公布计划。"}, {"text": "不日", "is_correct": true, "explanation": "正确：“不日将公布”表示过几天就会公布，符合句中公司的语境。"}, {"text": "从不", "is_correct": false, "explanation": "语义：“从不”表示从来没有，与“将公布新的计划”不合。"}], "explanations": {"已经": "体貌：“已经”表示已经完成，与“将公布”的将来矛盾。", "一向": "语义：“一向”指长期习惯，不能用于一次性的公布计划。", "不日": "正确：“不日将公布”表示过几天就会公布，符合句中公司的语境。", "从不": "语义：“从不”表示从来没有，与“将公布新的计划”不合。"}, "sentence_index": 6, "correct_answer": "不日"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈不日就做好饭。", "explanation": "这里应该用〈马上〉。不日指过几天才发生，做饭只需几十分钟，不能用于这种短时间的事。"}, {"text": "小猫一碰，不日就跳起来了。", "explanation": "这里应该用〈马上〉。不日指过几天才发生，不能用于碰到就立刻跳起来的反应。"}, {"text": "我每个月不日就去一次超市。", "explanation": "这里应该用〈定期〉。不日指不久之后的一次性事件，不能用于每月重复的行为。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '05d51723-abb3-4319-a185-155b7c3c894e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87055, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "新版软件不日把推出。", "corrected_sentence": "新版软件不日会推出。", "error_description": "错误形式“不日把推出”；正确形式“不日会推出”。“把”字句需要处置对象，此处“不日”之后应用能愿动词“会”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '05d51723-abb3-4319-a185-155b7c3c894e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87055, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这批货不日就把到港。", "corrected_sentence": "这批货不日就会到港。", "error_description": "错误形式“不日就把到港”；正确形式“不日就会到港”。“把”字句需要处置对象，此处应用能愿动词“会”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '05d51723-abb3-4319-a185-155b7c3c894e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
