INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87083, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "骂是对别人说很难听的话，让人听了不高兴。", "primary_collocate": null, "pronunciation": "mà", "ipa": "ma˥˩", "syllable_count": 1, "sentences": [{"text": "他骂我，我很不高兴。", "target_word": "骂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小孩子不能说脏话骂人。", "target_word": "骂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他说的话太难听，好像在骂我。", "target_word": "骂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸骂了哥哥几句，哥哥不说话了。", "target_word": "骂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "没有人喜欢听别人骂自己。", "target_word": "骂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，不要骂同学。", "target_word": "骂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他小声骂了一句，就走了。", "target_word": "骂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她听到有人骂她，心里很难过。", "target_word": "骂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛输了，他生气地骂了自己。", "target_word": "骂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她笑着说：“我不是在骂你。”", "target_word": "骂", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "骂了", "label": "体标"}, {"form": "骂过", "label": "体标"}, {"form": "骂人", "label": "复合"}, {"form": "罵", "label": "繁体"}], "register": "口语", "sense_fingerprint": "对别人说很难听的话，让人听了不高兴", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70e7459b-ce0f-48a0-8a3f-b3644c33e3f7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87083, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "骂", "is_correct": true, "explanation": "mà（第四声）指对别人说很难听的话，让人不高兴。"}, {"text": "妈", "is_correct": false, "explanation": "mā（第一声）与 mà（第四声）声调不同，意思是妈妈。"}, {"text": "麻", "is_correct": false, "explanation": "má（第二声）与 mà（第四声）声调不同，意思是麻。"}, {"text": "慢", "is_correct": false, "explanation": "màn 与 mà 韵母不同，多了鼻音 n，意思是慢。"}, {"text": "那", "is_correct": false, "explanation": "nà 与 mà 声母不同（n 与 m），意思是那。"}], "explanations": {"骂": "mà（第四声）指对别人说很难听的话，让人不高兴。", "妈": "mā（第一声）与 mà（第四声）声调不同，意思是妈妈。", "麻": "má（第二声）与 mà（第四声）声调不同，意思是麻。", "慢": "màn 与 mà 韵母不同，多了鼻音 n，意思是慢。", "那": "nà 与 mà 声母不同（n 与 m），意思是那。"}, "sentence_index": null, "correct_answer": "骂"}, "level_3": {"options": [{"text": "骂", "is_correct": true, "explanation": "正确。“骂我”表示对我说难听的话，与“我很不高兴”相符。"}, {"text": "夸", "is_correct": false, "explanation": "语义：“夸”是称赞，与句中“我很不高兴”的语境矛盾。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”的宾语应是食物，不能用于人，“吃我”不成立。"}, {"text": "哭", "is_correct": false, "explanation": "搭配：“哭”不能带人作宾语，“哭我”不成立。"}], "explanations": {"骂": "正确。“骂我”表示对我说难听的话，与“我很不高兴”相符。", "夸": "语义：“夸”是称赞，与句中“我很不高兴”的语境矛盾。", "吃": "搭配：“吃”的宾语应是食物，不能用于人，“吃我”不成立。", "哭": "搭配：“哭”不能带人作宾语，“哭我”不成立。"}, "sentence_index": 0, "correct_answer": "骂"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她在屋里骂了一壶水。", "explanation": "这里应该用〈烧〉。骂是对别人说很难听的话，不能用来表示加热。"}, {"text": "我在超市骂了一瓶牛奶。", "explanation": "这里应该用〈买〉。骂是对别人说很难听的话，不能用来表示购买东西。"}, {"text": "我骂她的心意，真的很感动。", "explanation": "这里应该用〈感谢〉。骂表示恶意责备，不能用来对别人的心意表示谢意。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '223ca4a0-75e9-44e0-8a77-bf4baaef43f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87083, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "骂", "is_correct": true, "explanation": "mà（第四声）指对别人说很难听的话，让人不高兴。"}, {"text": "爸", "is_correct": false, "explanation": "bà 与 mà 声母不同（b 与 m），意思是爸爸。"}, {"text": "怕", "is_correct": false, "explanation": "pà 与 mà 声母不同（p 与 m），意思是害怕。"}, {"text": "码", "is_correct": false, "explanation": "mǎ（第三声）与 mà（第四声）声调不同，意思是数码或号码。"}, {"text": "麦", "is_correct": false, "explanation": "mài 与 mà 韵母不同，多了 i，意思是小麦。"}], "explanations": {"骂": "mà（第四声）指对别人说很难听的话，让人不高兴。", "爸": "bà 与 mà 声母不同（b 与 m），意思是爸爸。", "怕": "pà 与 mà 声母不同（p 与 m），意思是害怕。", "码": "mǎ（第三声）与 mà（第四声）声调不同，意思是数码或号码。", "麦": "mài 与 mà 韵母不同，多了 i，意思是小麦。"}, "sentence_index": null, "correct_answer": "骂"}, "level_3": {"options": [{"text": "骂", "is_correct": true, "explanation": "正确。“骂了一句”表示小声说难听的话，与后面“就走了”相符。"}, {"text": "哭", "is_correct": false, "explanation": "搭配：“哭”是不及物动词，不带“一句”这样的言语宾语，“哭了一句”不成立。"}, {"text": "拍", "is_correct": false, "explanation": "搭配：“拍”不能用来指说话，“拍了一句”不成立。"}, {"text": "笑", "is_correct": false, "explanation": "搭配：“笑”不带“一句”这样的言语宾语，“笑了一句”不成立。"}], "explanations": {"骂": "正确。“骂了一句”表示小声说难听的话，与后面“就走了”相符。", "哭": "搭配：“哭”是不及物动词，不带“一句”这样的言语宾语，“哭了一句”不成立。", "拍": "搭配：“拍”不能用来指说话，“拍了一句”不成立。", "笑": "搭配：“笑”不带“一句”这样的言语宾语，“笑了一句”不成立。"}, "sentence_index": 6, "correct_answer": "骂"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "老师骂了这道题的解法，大家都听懂了。", "explanation": "这里应该用〈讲解〉。骂表示恶意责备，不能用来讲解题目的解法。"}, {"text": "大家骂他的到来，都很高兴。", "explanation": "这里应该用〈欢迎〉。骂是责备，不能用来热情迎接别人。"}, {"text": "她骂了一段舞蹈，观众很喜欢。", "explanation": "这里应该用〈表演〉。骂是责备，不能用来指表演舞蹈。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '223ca4a0-75e9-44e0-8a77-bf4baaef43f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87083, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他骂很难听。", "corrected_sentence": "他骂得很难听。", "error_description": "“骂很难听”应为“骂得很难听”。“骂”后面带程度补语时要用“得”连接，漏掉“得”是常见错误。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '223ca4a0-75e9-44e0-8a77-bf4baaef43f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87083, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妈妈骂我了一顿。", "corrected_sentence": "妈妈骂了我一顿。", "error_description": "“骂我了一顿”应为“骂了我一顿”。动态助词“了”应紧跟动词“骂”，放在宾语“我”后面是错误的语序。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '223ca4a0-75e9-44e0-8a77-bf4baaef43f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
