INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87084, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用粗野或恶意的话侮辱、责备别人。", "primary_collocate": null, "pronunciation": "mà", "ipa": "ma˥˩", "syllable_count": 1, "sentences": [{"text": "他生气了，大声骂了那个人。", "target_word": "骂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别骂孩子，他已经知道错了。", "target_word": "骂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板骂了他一个小时。", "target_word": "骂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们吵架时互相骂对方。", "target_word": "骂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈从来不骂我，只是慢慢说。", "target_word": "骂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个司机很生气，下车就开始骂。", "target_word": "骂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把弟弟骂哭了。", "target_word": "骂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在网上骂别人是不对的。", "target_word": "骂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你为什么骂他？他没做错什么。", "target_word": "骂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她很难过，因为同学骂过她。", "target_word": "骂", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "骂了", "label": "体标"}, {"form": "骂过", "label": "体标"}, {"form": "骂人", "label": "复合"}, {"form": "罵", "label": "繁体"}], "register": "口语", "sense_fingerprint": "用粗野或恶意的话侮辱、责备别人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70e7459b-ce0f-48a0-8a3f-b3644c33e3f7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87084, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "骂", "is_correct": true, "explanation": "mà（第四声）指用粗野或恶意的话责备别人。"}, {"text": "妈", "is_correct": false, "explanation": "mā（第一声）与 mà（第四声）声调不同，意思是妈妈。"}, {"text": "马", "is_correct": false, "explanation": "mǎ（第三声）与 mà（第四声）声调不同，意思是马。"}, {"text": "麻", "is_correct": false, "explanation": "má（第二声）与 mà（第四声）声调不同，意思是麻。"}, {"text": "慢", "is_correct": false, "explanation": "màn 与 mà 韵母不同，多了鼻音 n，意思是慢。"}, {"text": "爸", "is_correct": false, "explanation": "bà 与 mà 声母不同（b 与 m），意思是爸爸。"}], "explanations": {"骂": "mà（第四声）指用粗野或恶意的话责备别人。", "妈": "mā（第一声）与 mà（第四声）声调不同，意思是妈妈。", "马": "mǎ（第三声）与 mà（第四声）声调不同，意思是马。", "麻": "má（第二声）与 mà（第四声）声调不同，意思是麻。", "慢": "màn 与 mà 韵母不同，多了鼻音 n，意思是慢。", "爸": "bà 与 mà 声母不同（b 与 m），意思是爸爸。"}, "sentence_index": null, "correct_answer": "骂"}, "level_3": {"options": [{"text": "骂", "is_correct": true, "explanation": "正确。骂是用粗野的话责备别人，与“生气”和“大声”的语境相符。"}, {"text": "夸", "is_correct": false, "explanation": "语义：“夸”是称赞，与句中“生气”的语境矛盾。"}, {"text": "表扬", "is_correct": false, "explanation": "语义：“表扬”是称赞，与句中“生气”的语境矛盾。"}, {"text": "亲", "is_correct": false, "explanation": "搭配：“亲”是亲吻，不能与“大声”搭配，也不能用来责备别人。"}], "explanations": {"骂": "正确。骂是用粗野的话责备别人，与“生气”和“大声”的语境相符。", "夸": "语义：“夸”是称赞，与句中“生气”的语境矛盾。", "表扬": "语义：“表扬”是称赞，与句中“生气”的语境矛盾。", "亲": "搭配：“亲”是亲吻，不能与“大声”搭配，也不能用来责备别人。"}, "sentence_index": 0, "correct_answer": "骂"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "老师骂了他的努力，还说他进步很大。", "explanation": "这里应该用〈表扬〉。骂是用粗野或恶意的话责备，不能用来褒扬别人的努力。"}, {"text": "我骂大家的帮助，真的很感谢。", "explanation": "这里应该用〈感谢〉。骂表示恶意责备，不能用来对别人的帮助表示谢意。"}, {"text": "老师骂了她的字写得好。", "explanation": "这里应该用〈称赞〉。骂用于责备，不能用来称赞别人字写得好。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '223ca4a0-75e9-44e0-8a77-bf4baaef43f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87084, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "骂", "is_correct": true, "explanation": "mà（第四声）指用粗野或恶意的话责备别人。"}, {"text": "那", "is_correct": false, "explanation": "nà 与 mà 声母不同（n 与 m），意思是那。"}, {"text": "怕", "is_correct": false, "explanation": "pà 与 mà 声母不同（p 与 m），意思是害怕。"}, {"text": "码", "is_correct": false, "explanation": "mǎ（第三声）与 mà（第四声）声调不同，意思是数码或号码。"}, {"text": "麦", "is_correct": false, "explanation": "mài 与 mà 韵母不同，多了 i，意思是小麦。"}], "explanations": {"骂": "mà（第四声）指用粗野或恶意的话责备别人。", "那": "nà 与 mà 声母不同（n 与 m），意思是那。", "怕": "pà 与 mà 声母不同（p 与 m），意思是害怕。", "码": "mǎ（第三声）与 mà（第四声）声调不同，意思是数码或号码。", "麦": "mài 与 mà 韵母不同，多了 i，意思是小麦。"}, "sentence_index": null, "correct_answer": "骂"}, "level_3": {"options": [{"text": "骂", "is_correct": true, "explanation": "正确。“骂哭”表示责骂使弟弟哭，是常见的结果补语结构。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”不能使人哭，“吃哭”没有这种说法。"}, {"text": "借", "is_correct": false, "explanation": "语义：“借”指借入或借出，不会使人哭，“借哭”不成立。"}, {"text": "扶", "is_correct": false, "explanation": "搭配：“扶”不能与“哭”构成结果关系，“扶哭”不合理。"}], "explanations": {"骂": "正确。“骂哭”表示责骂使弟弟哭，是常见的结果补语结构。", "吃": "搭配：“吃”不能使人哭，“吃哭”没有这种说法。", "借": "语义：“借”指借入或借出，不会使人哭，“借哭”不成立。", "扶": "搭配：“扶”不能与“哭”构成结果关系，“扶哭”不合理。"}, "sentence_index": 6, "correct_answer": "骂"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我今天骂了一张火车票。", "explanation": "这里应该用〈订〉。骂是用粗野或恶意的话责备，不能用来表示预订车票。"}, {"text": "他每个月骂了一笔钱。", "explanation": "这里应该用〈存〉。骂是用粗野或恶意的话责备，不能用来表示把钱存起来。"}, {"text": "他在厨房骂了一锅饭。", "explanation": "这里应该用〈煮〉。骂是用粗野或恶意的话责备，不能用来表示加热做饭。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '223ca4a0-75e9-44e0-8a77-bf4baaef43f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87084, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他骂很厉害。", "corrected_sentence": "他骂得很厉害。", "error_description": "“骂很厉害”应为“骂得很厉害”。“骂”后面带程度补语时要用“得”连接，漏掉“得”是常见错误。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '223ca4a0-75e9-44e0-8a77-bf4baaef43f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87084, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他骂了我一个。", "corrected_sentence": "他骂了我一顿。", "error_description": "“骂了我一个”应为“骂了我一顿”。“骂”这一动作的数量要用“顿”来计算，不能用“个”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '223ca4a0-75e9-44e0-8a77-bf4baaef43f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87096, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'faf84b80-4df6-49a8-97a1-abfb129973e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87096, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'faf84b80-4df6-49a8-97a1-abfb129973e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87096, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "代表一定财产权利、可以买卖的有价凭证，如股票、债券等。", "primary_collocate": null, "pronunciation": "zhèng quàn", "ipa": "ʈʂɤŋ˥˩ tɕʰɥɛn˥˩", "syllable_count": 2, "sentences": [{"text": "股票和债券都是常见的证券。", "target_word": "证券", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把手里的证券卖掉了，换了一套房子。", "target_word": "证券", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸买了一些证券，希望以后能赚钱。", "target_word": "证券", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "证券的价格每天都在变化。", "target_word": "证券", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张证券可以在市场上自由买卖。", "target_word": "证券", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "投资者可以通过银行买到国债这种证券。", "target_word": "证券", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她打算把证券留着，等价格涨了再卖。", "target_word": "证券", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "证券上写着金额和发行日期。", "target_word": "证券", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "买证券以前，要先了解发行公司的情况。", "target_word": "证券", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司向社会发行证券，筹集了不少资金。", "target_word": "证券", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "證券", "label": "繁体"}, {"form": "证券公司", "label": "复合"}, {"form": "证券市场", "label": "复合"}], "register": "书面", "sense_fingerprint": "证券|有价凭证|股票债券|名词", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ae3816d5-8403-4a97-960f-1b509de16fef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87096, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "证券", "is_correct": true, "explanation": "正确答案。证券指代表财产权利、可以买卖的有价凭证，如股票、债券。"}, {"text": "政权", "is_correct": false, "explanation": "quán（第二声）与 quàn（第四声）声调不同，意思是国家政权。"}, {"text": "争权", "is_correct": false, "explanation": "zhēng（第一声）与 zhèng（第四声）、quán（第二声）与 quàn（第四声）声调都不同，意思是争夺权力。"}, {"text": "正拳", "is_correct": false, "explanation": "zhèng 相同，quán（第二声）与 quàn（第四声）声调不同，意思是拳击中的直拳。"}], "explanations": {"证券": "正确答案。证券指代表财产权利、可以买卖的有价凭证，如股票、债券。", "政权": "quán（第二声）与 quàn（第四声）声调不同，意思是国家政权。", "争权": "zhēng（第一声）与 zhèng（第四声）、quán（第二声）与 quàn（第四声）声调都不同，意思是争夺权力。", "正拳": "zhèng 相同，quán（第二声）与 quàn（第四声）声调不同，意思是拳击中的直拳。"}, "sentence_index": null, "correct_answer": "证券"}, "level_3": {"options": [{"text": "证券", "is_correct": true, "explanation": "正确。“股票和债券”都属于有价凭证，可以说“常见的证券”。"}, {"text": "饮料", "is_correct": false, "explanation": "语义：“饮料”与“股票和债券”属于不同类别，句子说的是金融凭证，不能说“常见的饮料”。"}, {"text": "蔬菜", "is_correct": false, "explanation": "语义：“蔬菜”是食物，与“股票和债券”不能并列为同类常见物品，句意不通。"}, {"text": "电脑", "is_correct": false, "explanation": "语义：「电脑」是电子产品，与「股票和债券」不同类，「都是常见的电脑」句意不通。"}], "explanations": {"证券": "正确。“股票和债券”都属于有价凭证，可以说“常见的证券”。", "饮料": "语义：“饮料”与“股票和债券”属于不同类别，句子说的是金融凭证，不能说“常见的饮料”。", "蔬菜": "语义：“蔬菜”是食物，与“股票和债券”不能并列为同类常见物品，句意不通。", "电脑": "语义：「电脑」是电子产品，与「股票和债券」不同类，「都是常见的电脑」句意不通。"}, "sentence_index": 0, "correct_answer": "证券"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我买了一只证券。", "explanation": "这里应该用〈张〉。证券是纸质凭证，计量时用“张”或“份”，“只”多用于动物或成对的东西。"}, {"text": "出国前要带好护照等证券。", "explanation": "这里应该用〈证件〉。证件指护照、身份证等证明身份的文件，证券指股票、债券等有价凭证。"}, {"text": "他终于拿到了毕业证券。", "explanation": "这里应该用〈证书〉。毕业证书是学校颁发的证明，证券指股票、债券，不能用来指毕业证。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'faf84b80-4df6-49a8-97a1-abfb129973e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87096, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "证券", "is_correct": true, "explanation": "正确。“留着，等价格涨了再卖”说的是可以买卖的有价凭证。"}, {"text": "作业", "is_correct": false, "explanation": "搭配：“作业”没有价格，不能说“等价格涨了再卖”。"}, {"text": "故事", "is_correct": false, "explanation": "语义：故事没有价格，也不能拿来买卖，与后半句矛盾。"}, {"text": "朋友", "is_correct": false, "explanation": "语义：朋友不能标价出售，与“等价格涨了再卖”的语境矛盾。"}], "explanations": {"证券": "正确。“留着，等价格涨了再卖”说的是可以买卖的有价凭证。", "作业": "搭配：“作业”没有价格，不能说“等价格涨了再卖”。", "故事": "语义：故事没有价格，也不能拿来买卖，与后半句矛盾。", "朋友": "语义：朋友不能标价出售，与“等价格涨了再卖”的语境矛盾。"}, "sentence_index": 6, "correct_answer": "证券"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "进门前要出示证券，门口的人才会放你进去。", "explanation": "这里应该用〈门票〉。门票是入场凭证，证券指股票、债券等有价凭证，不能用来入场。"}, {"text": "退货时要带上证券，商店才会给你退钱。", "explanation": "这里应该用〈收据〉。收据是付款凭证，证券指股票、债券，不能用来办理退货。"}, {"text": "买完东西要保存好证券，以后可能需要报销。", "explanation": "这里应该用〈发票〉。发票是购物凭证，证券指股票、债券，不能用来报销。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'faf84b80-4df6-49a8-97a1-abfb129973e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87096, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她把这证券卖了。", "corrected_sentence": "她把这张证券卖了。", "error_description": "量词漏用。“证券”前面用指示代词“这”时，中间要加量词“张”，应说“这张证券”，不能说“这证券”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'faf84b80-4df6-49a8-97a1-abfb129973e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87096, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他买了一只证券。", "corrected_sentence": "他买了一张证券。", "error_description": "量词用错。证券是纸质凭证，计量时应用“张”或“份”，不能用“只”，应说“一张证券”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'faf84b80-4df6-49a8-97a1-abfb129973e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
