INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87099, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "财政是国家怎么收钱、怎么花钱的事。", "primary_collocate": null, "pronunciation": "cái zhèng", "ipa": "tsʰai˧˥ ʈʂəŋ˥˩", "syllable_count": 2, "sentences": [{"text": "国家的财政要公开给大家看。", "target_word": "财政", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个县的财政比去年好多了。", "target_word": "财政", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "税收是政府财政的主要来源。", "target_word": "财政", "complexity_tier": "T3", "furigana": "shuìshōu shì zhèngfǔ cáizhèng de zhǔyào láiyuán.", "sentence_source": "generated"}, {"text": "财政出了问题，工资就发不了。", "target_word": "财政", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我哥哥在政府做财政工作。", "target_word": "财政", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校要学习国家的财政知识。", "target_word": "财政", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国家财政不能花得太多。", "target_word": "财政", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "财政好了，路和学校都能多修。", "target_word": "财政", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们正在讨论明年的财政。", "target_word": "财政", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这几年地方财政一直很稳。", "target_word": "财政", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "財政", "label": "繁体"}, {"form": "财政部", "label": "复合"}, {"form": "财政支出", "label": "复合"}], "register": "书面", "sense_fingerprint": "国家收钱和花钱的事务", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '043aa009-a719-4f20-b3b2-bdf490915713') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87099, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "财政", "is_correct": true, "explanation": "财政：国家怎么收钱、怎么花钱的事，「国家的财政要公开给大家看」符合句意。"}, {"text": "鞋子", "is_correct": false, "explanation": "语义：“鞋子”是穿在脚上的物品，不是需要公开给大家看的国家事务，句意不通。"}, {"text": "石头", "is_correct": false, "explanation": "语义：“石头”是自然物，与国家收支无关，“国家的石头要公开给大家看”说不通。"}, {"text": "被子", "is_correct": false, "explanation": "语义：“被子”是日常用品，不是需要公开的国家事务，句意不通。"}], "explanations": {"财政": "财政：国家怎么收钱、怎么花钱的事，「国家的财政要公开给大家看」符合句意。", "鞋子": "语义：“鞋子”是穿在脚上的物品，不是需要公开给大家看的国家事务，句意不通。", "石头": "语义：“石头”是自然物，与国家收支无关，“国家的石头要公开给大家看”说不通。", "被子": "语义：“被子”是日常用品，不是需要公开的国家事务，句意不通。"}, "sentence_index": 0, "correct_answer": "财政"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我每年都要交很多财政。", "explanation": "这里应该用〈学费〉。财政指国家收钱和花钱的事，个人交的钱要用〈学费〉。"}, {"text": "政府财政了贫困学生。", "explanation": "这里应该用〈资助〉。“财政”不作动词，表示给人经济帮助要用〈资助〉。"}, {"text": "他把钱财政进了银行。", "explanation": "这里应该用〈存〉。“财政”不能表示把钱存入银行，应说“存进银行”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4a01baeb-4c4d-4efc-b7c5-f345ae78b6b1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87099, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "财政", "is_correct": true, "explanation": "财政：国家怎么收钱、怎么花钱的事，「国家财政不能花得太多」符合句意。"}, {"text": "海洋", "is_correct": false, "explanation": "语义：“海洋”是自然地理概念，与花钱无关，“国家海洋不能花得太多”说不通。"}, {"text": "课文", "is_correct": false, "explanation": "语义：“课文”是课本里的文章，不是可以花的东西，句意不通。"}, {"text": "心情", "is_correct": false, "explanation": "搭配：“心情”不能用“花”来消费，“不能花得太多”与“心情”搭配不通。"}], "explanations": {"财政": "财政：国家怎么收钱、怎么花钱的事，「国家财政不能花得太多」符合句意。", "海洋": "语义：“海洋”是自然地理概念，与花钱无关，“国家海洋不能花得太多”说不通。", "课文": "语义：“课文”是课本里的文章，不是可以花的东西，句意不通。", "心情": "搭配：“心情”不能用“花”来消费，“不能花得太多”与“心情”搭配不通。"}, "sentence_index": 6, "correct_answer": "财政"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "房东退还了我的财政。", "explanation": "这里应该用〈押金〉。财政指国家收钱和花钱的事，房东退还的个人保证金要用〈押金〉。"}, {"text": "他持有公司的财政。", "explanation": "这里应该用〈股份〉。财政指国家收钱和花钱的事，公司的所有权份额要用〈股份〉。"}, {"text": "他的财政发下来了。", "explanation": "这里应该用〈工资〉。财政指国家收钱和花钱的事，个人的薪水要用〈工资〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4a01baeb-4c4d-4efc-b7c5-f345ae78b6b1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87099, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "政府每年都要公布财政得报告。", "corrected_sentence": "政府每年都要公布财政的报告。", "error_description": "结构助词误用：修饰「报告」的成分应用「的」，「得」用于补语，不能说「财政得报告」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4a01baeb-4c4d-4efc-b7c5-f345ae78b6b1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87099, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他在学习国家得财政制度。", "corrected_sentence": "他在学习国家的财政制度。", "error_description": "“财政制度”前的修饰成分要用结构助词“的”，“得”用于补语，不能说“国家得财政制度”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4a01baeb-4c4d-4efc-b7c5-f345ae78b6b1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
