INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87103, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "办理是把一件事做好，常常要去一个地方交表格。", "primary_collocate": null, "pronunciation": "bàn lǐ", "ipa": "pan˥˩ li˨˩˦", "syllable_count": 2, "sentences": [{"text": "去窗口办理时，要先填一张表。", "target_word": "办理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我带着护照去银行办理手续。", "target_word": "办理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他到社区中心办理了结婚登记。", "target_word": "办理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "办理签证要交照片和表格。", "target_word": "办理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请先在大厅办理，再交表格。", "target_word": "办理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我上午去办理过一次，今天又来了。", "target_word": "办理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "办理入住的时候，要出示身份证。", "target_word": "办理", "complexity_tier": "T3", "furigana": "bàn lǐ rù zhù de shí hou, yào chū shì shēn fèn zhèng.", "sentence_source": "generated"}, {"text": "她在医院办理出院，交了表格。", "target_word": "办理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "要办理这个证，必须本人去。", "target_word": "办理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你填好表，就可以去办理了。", "target_word": "办理", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "办理了", "label": "体标"}, {"form": "办理过", "label": "体标"}, {"form": "辦理", "label": "繁体"}], "register": "中性", "sense_fingerprint": "办理：到某处填表交材料，把手续办好", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '46f86a8e-c93b-4cfe-95df-f413bcbe6177') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87103, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "欣赏", "is_correct": false, "explanation": "语义：欣赏指品味美好的事物，不能用于“去窗口”的办事过程。"}, {"text": "办理", "is_correct": true, "explanation": "正确。“去窗口办理时”指到窗口办事，符合语境。"}, {"text": "游览", "is_correct": false, "explanation": "语义：游览指参观景点，不能用于到窗口办事的过程。"}, {"text": "生产", "is_correct": false, "explanation": "配价：“生产”需要带宾语，单独说“去窗口生产”不成立。"}], "explanations": {"欣赏": "语义：欣赏指品味美好的事物，不能用于“去窗口”的办事过程。", "办理": "正确。“去窗口办理时”指到窗口办事，符合语境。", "游览": "语义：游览指参观景点，不能用于到窗口办事的过程。", "生产": "配价：“生产”需要带宾语，单独说“去窗口生产”不成立。"}, "sentence_index": 0, "correct_answer": "办理"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她每天认真办理衣服。", "explanation": "这里应该用〈洗〉。洗用于衣服、物品，办理用于手续和业务，不能用于衣服。"}, {"text": "这份文件要办理成英文。", "explanation": "这里应该用〈翻译〉。翻译是把内容转换成另一种语言，办理用于手续和业务。"}, {"text": "服务员热情办理了客人。", "explanation": "这里应该用〈接待〉。接待是迎接并招待客人，办理用于手续和业务，不能用于人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '491bcf82-a5b3-404e-b5b2-c49d94b80e18') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87103, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "退房", "is_correct": false, "explanation": "语义：退房是离开时结算，与“入住”相反，不能用于入住的时候。"}, {"text": "办理", "is_correct": true, "explanation": "正确。“办理入住”指办好入住的手续，符合语境。"}, {"text": "打扫", "is_correct": false, "explanation": "搭配：“打扫”用于房间、场所，不说“打扫入住”。"}, {"text": "修理", "is_correct": false, "explanation": "搭配：“修理”用于机器、物品，不说“修理入住”。"}], "explanations": {"退房": "语义：退房是离开时结算，与“入住”相反，不能用于入住的时候。", "办理": "正确。“办理入住”指办好入住的手续，符合语境。", "打扫": "搭配：“打扫”用于房间、场所，不说“打扫入住”。", "修理": "搭配：“修理”用于机器、物品，不说“修理入住”。"}, "sentence_index": 6, "correct_answer": "办理"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "专家在办理数据。", "explanation": "这里应该用〈分析〉。分析是研究数据的过程，办理用于手续和业务。"}, {"text": "教练在办理队员。", "explanation": "这里应该用〈培训〉。培训是训练人员，办理用于手续和业务，不能用于队员。"}, {"text": "他在锅里办理饭。", "explanation": "这里应该用〈煮〉。煮是把食物放在水中加热，办理用于手续和业务。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '491bcf82-a5b3-404e-b5b2-c49d94b80e18') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87103, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我昨天在窗口办理完着手续。", "corrected_sentence": "我昨天在窗口办理完了手续。", "error_description": "体标错误：“办理完”表示动作已经完成，应用“了”，不能用“着”。错误形式：办理完着；正确形式：办理完了。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '491bcf82-a5b3-404e-b5b2-c49d94b80e18') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87103, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这份申请已经办理完毕着。", "corrected_sentence": "这份申请已经办理完毕了。", "error_description": "体标错误：“办理完毕”是已经完成的动作，应用“了”，不能用“着”。错误形式：办理完毕着；正确形式：办理完毕了。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '491bcf82-a5b3-404e-b5b2-c49d94b80e18') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
