INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87108, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "对批量生产的产品的外形、结构和功能进行构思与设计的工作。", "primary_collocate": null, "pronunciation": "gōng yè shè jì", "ipa": "kʊŋ˥ jɛ˥˩ ʂɤ˥˩ tɕi˥˩", "syllable_count": 4, "sentences": [{"text": "他大学学的是工业设计。", "target_word": "工业设计", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工业设计要考虑产品好不好用。", "target_word": "工业设计", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这把椅子是工业设计的好例子。", "target_word": "工业设计", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她毕业后做工业设计，每天画图。", "target_word": "工业设计", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好的工业设计让手机更好看，也更好用。", "target_word": "工业设计", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司的工业设计很有名。", "target_word": "工业设计", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工业设计要先想好产品的外形和功能。", "target_word": "工业设计", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我哥哥想学工业设计，以后设计汽车。", "target_word": "工业设计", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的工业设计作品得了大奖。", "target_word": "工业设计", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做工业设计，也要想工厂怎么生产。", "target_word": "工业设计", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "工业设计师", "label": "复合"}], "register": "中性", "sense_fingerprint": "对批量产品的外形、结构、功能做构思设计的工作或专业", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9312b6ee-2f6f-44ac-9f74-0846338cf1b7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87108, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "厨房", "is_correct": false, "explanation": "语义：厨房是地点，不是大学里学习的专业。"}, {"text": "工业设计", "is_correct": true, "explanation": "这里指学习的专业。“学的是”后接学科名称，符合语境。"}, {"text": "饭菜", "is_correct": false, "explanation": "搭配：“学的是”后接的应是学科或技能，“饭菜”不能这样搭配（可说“学做饭菜”）。"}, {"text": "感冒", "is_correct": false, "explanation": "语义：感冒是一种疾病，不是可以学习的内容。"}], "explanations": {"厨房": "语义：厨房是地点，不是大学里学习的专业。", "工业设计": "这里指学习的专业。“学的是”后接学科名称，符合语境。", "饭菜": "搭配：“学的是”后接的应是学科或技能，“饭菜”不能这样搭配（可说“学做饭菜”）。", "感冒": "语义：感冒是一种疾病，不是可以学习的内容。"}, "sentence_index": 0, "correct_answer": "工业设计"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这栋房子的工业设计很好。", "explanation": "这里应该用〈装修〉。工业设计指对批量生产的产品进行外形、结构和功能的设计，房子不是批量生产的产品，说房屋的室内布置要用〈装修〉。"}, {"text": "这位老人的工业设计很好。", "explanation": "这里应该用〈手艺〉。工业设计针对批量生产的产品，老人的手工技艺不属于此，要用〈手艺〉。"}, {"text": "她毕业后负责这次活动的工业设计，每天开会。", "explanation": "这里应该用〈策划〉。工业设计针对批量生产产品的外形、结构和功能，活动的安排和方案要用〈策划〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '137e41b7-345e-410f-abda-3834f0905653') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87108, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "天气", "is_correct": false, "explanation": "配价：“想好……”需要有意识的施事，“天气”不能充当这里的主语。"}, {"text": "水泥", "is_correct": false, "explanation": "语义：水泥是建筑材料，不能构思产品的外形和功能。"}, {"text": "工业设计", "is_correct": true, "explanation": "指对产品外形和功能进行构思的工作，作主语，符合语境。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头是自然物，无法构思产品的外形和功能。"}], "explanations": {"天气": "配价：“想好……”需要有意识的施事，“天气”不能充当这里的主语。", "水泥": "语义：水泥是建筑材料，不能构思产品的外形和功能。", "工业设计": "指对产品外形和功能进行构思的工作，作主语，符合语境。", "石头": "语义：石头是自然物，无法构思产品的外形和功能。"}, "sentence_index": 6, "correct_answer": "工业设计"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这件木雕的工业设计很精细。", "explanation": "这里应该用〈雕刻〉。工业设计是为批量生产的产品设计外形和功能，手工雕刻不属于此，要用〈雕刻〉。"}, {"text": "他的工业设计很动听。", "explanation": "这里应该用〈作曲〉。工业设计指对产品外形、结构和功能的设计，不能用来形容音乐作品，要用〈作曲〉。"}, {"text": "这场演出的工业设计很精彩。", "explanation": "这里应该用〈舞台设计〉。工业设计针对批量生产的产品，演出的舞台布置要用〈舞台设计〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '137e41b7-345e-410f-abda-3834f0905653') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87108, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他的毕业作品是一座工业设计。", "corrected_sentence": "他的毕业作品是一项工业设计。", "error_description": "量词错误：“座”用于山、楼等大型固定的物体，工业设计应用量词“项”，应说“一项工业设计”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '137e41b7-345e-410f-abda-3834f0905653') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87108, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这幅工业设计获得了金奖。", "corrected_sentence": "这项工业设计获得了金奖。", "error_description": "量词错误：“幅”用于画作，工业设计应用量词“项”，应说“这项工业设计”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '137e41b7-345e-410f-abda-3834f0905653') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
