INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87124, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'faf84b80-4df6-49a8-97a1-abfb129973e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87124, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "形容程度深、本领强，或者性格凶猛。", "primary_collocate": null, "pronunciation": "lì hai", "ipa": "li˥˩ xai", "syllable_count": 2, "sentences": [{"text": "这只狗很厉害，你别靠近它。", "target_word": "厉害", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的汉语说得真厉害。", "target_word": "厉害", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天冷得厉害，出门要多穿衣服。", "target_word": "厉害", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他头疼得厉害，今天没去上班。", "target_word": "厉害", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们的老师很厉害，什么问题都能回答。", "target_word": "厉害", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个老板脾气很厉害，大家都怕他。", "target_word": "厉害", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她弹钢琴弹得很厉害，得过很多奖。", "target_word": "厉害", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "外面的雨下得很厉害，你带伞了吗？", "target_word": "厉害", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位医生真厉害，一下就找到了病因。", "target_word": "厉害", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老虎很厉害，一口就能咬住小鹿。", "target_word": "厉害", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "厲害", "label": "繁体"}, {"form": "厉害得很", "label": "复合"}], "register": "口语", "sense_fingerprint": "厉害|程度深/本领强/凶猛|形容词", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ae3816d5-8403-4a97-960f-1b509de16fef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87124, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "厉害", "is_correct": true, "explanation": "正确。“厉害”形容狗凶猛，所以提醒“你别靠近它”。"}, {"text": "好吃", "is_correct": false, "explanation": "搭配：“好吃”只用于形容食物的味道，不能用来形容狗。"}, {"text": "清香", "is_correct": false, "explanation": "搭配：“清香”形容气味，不能说“这只狗很清香”。"}, {"text": "温顺", "is_correct": false, "explanation": "语义：“温顺”的狗让人放心，与后半句“你别靠近它”的警告矛盾。"}], "explanations": {"厉害": "正确。“厉害”形容狗凶猛，所以提醒“你别靠近它”。", "好吃": "搭配：“好吃”只用于形容食物的味道，不能用来形容狗。", "清香": "搭配：“清香”形容气味，不能说“这只狗很清香”。", "温顺": "语义：“温顺”的狗让人放心，与后半句“你别靠近它”的警告矛盾。"}, "sentence_index": 0, "correct_answer": "厉害"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这块蛋糕很厉害，我一口气吃了三块。", "explanation": "这里应该用〈好吃〉。厉害形容程度深或本领强，不能用来评价食物的味道。"}, {"text": "他很厉害地关上了门，声音很小。", "explanation": "这里应该用〈轻轻〉。厉害表示程度或本领，不能用来修饰“关门”这类动作的方式。"}, {"text": "妈妈看见我考了满分，厉害地笑了。", "explanation": "这里应该用〈开心〉。「厉害地笑」作状语不自然；厉害作补语时可说「笑得厉害」，此处应说「开心地笑」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'faf84b80-4df6-49a8-97a1-abfb129973e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87124, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "厉害", "is_correct": true, "explanation": "正确。“弹得很厉害，得过很多奖”说明她的钢琴水平很高。"}, {"text": "难听", "is_correct": false, "explanation": "语义：弹得难听就不会得奖，与后半句“得过很多奖”矛盾。"}, {"text": "烫", "is_correct": false, "explanation": "搭配：“烫”形容温度，不能用来形容弹钢琴的水平。"}, {"text": "吵", "is_correct": false, "explanation": "语义：弹得吵闹不容易得奖，与后半句“得过很多奖”矛盾。"}], "explanations": {"厉害": "正确。“弹得很厉害，得过很多奖”说明她的钢琴水平很高。", "难听": "语义：弹得难听就不会得奖，与后半句“得过很多奖”矛盾。", "烫": "搭配：“烫”形容温度，不能用来形容弹钢琴的水平。", "吵": "语义：弹得吵闹不容易得奖，与后半句“得过很多奖”矛盾。"}, "sentence_index": 6, "correct_answer": "厉害"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这碗汤很厉害，我喝了两碗。", "explanation": "这里应该用〈好喝〉。厉害形容程度深或本领强，不能用来评价汤的味道。"}, {"text": "妈妈很厉害地擦干了桌子。", "explanation": "这里应该用〈仔细〉。厉害不能用来修饰“擦桌子”这个动作的方式。"}, {"text": "小猫很厉害地睡着了。", "explanation": "这里应该用〈香〉。应说“睡得很香”，厉害不能用来描述睡觉的状态。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'faf84b80-4df6-49a8-97a1-abfb129973e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87124, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他的网球打很厉害。", "corrected_sentence": "他的网球打得很厉害。", "error_description": "补语标记“得”遗漏。动词“打”和补语“很厉害”之间要用“得”，应说“打得很厉害”，不能省略“得”。错误形式：打很厉害；正确形式：打得很厉害。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'faf84b80-4df6-49a8-97a1-abfb129973e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87124, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她跑的很厉害。", "corrected_sentence": "她跑得很厉害。", "error_description": "补语标记误用。动词后的程度补语要用“得”，不能用“的”，应说“跑得很厉害”。错误形式：跑的很厉害；正确形式：跑得很厉害。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'faf84b80-4df6-49a8-97a1-abfb129973e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87125, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "静", "is_correct": true, "explanation": "静与动相对，指不动、静止，是这一义项的反义词。"}, {"text": "吃", "is_correct": false, "explanation": "吃是进食动作，与“动”没有反义关系。"}, {"text": "唱", "is_correct": false, "explanation": "唱是发声动作，与“动”没有反义关系。"}, {"text": "写", "is_correct": false, "explanation": "写是书写动作，与“动”没有反义关系。"}], "correct_answer": "静", "explanations": {"静": "静与动相对，指不动、静止，是这一义项的反义词。", "吃": "吃是进食动作，与“动”没有反义关系。", "唱": "唱是发声动作，与“动”没有反义关系。", "写": "写是书写动作，与“动”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '415aa2a1-1bc1-4dae-858f-381cc84b3069') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87125, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "静", "is_correct": true, "explanation": "静与动相对，指不动、静止，是这一义项的反义词。"}, {"text": "跑", "is_correct": false, "explanation": "跑是快速移动的动作，本身是动态的，与“动”不构成反义。"}, {"text": "看", "is_correct": false, "explanation": "看是视觉动作，与“动”没有反义关系。"}, {"text": "喝", "is_correct": false, "explanation": "喝是进食动作，与“动”没有反义关系。"}], "correct_answer": "静", "explanations": {"静": "静与动相对，指不动、静止，是这一义项的反义词。", "跑": "跑是快速移动的动作，本身是动态的，与“动”不构成反义。", "看": "看是视觉动作，与“动”没有反义关系。", "喝": "喝是进食动作，与“动”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '415aa2a1-1bc1-4dae-858f-381cc84b3069') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87125, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "动是身体或东西换了地方，或者不是一直不动。", "primary_collocate": null, "pronunciation": "dòng", "ipa": "tʊŋ˥˩", "syllable_count": 1, "sentences": [{"text": "前面的车一直不动，我们到不了。", "target_word": "动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小狗坐在门口，一动也不动。", "target_word": "动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他太累了，躺在床上不想动。", "target_word": "动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张桌子太重，我一个人动不了。", "target_word": "动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请不要动，我给你拍张照片。", "target_word": "动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "风很大，树上的叶子都在动。", "target_word": "动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子睡着了，一点儿也没动。", "target_word": "动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的脚很疼，不能动了。", "target_word": "动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "前面的人动了，我们也走吧。", "target_word": "动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小鱼在水里动来动去。", "target_word": "动", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "動", "label": "繁体"}, {"form": "动了", "label": "体标"}, {"form": "动着", "label": "体标"}, {"form": "动过", "label": "体标"}, {"form": "动动", "label": "重叠"}], "register": "中性", "sense_fingerprint": "身体或物体移动位置，与不动相对", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8b2c5003-937d-4490-b759-8fcdbf134d37') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87125, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "动", "is_correct": true, "explanation": "正确：动（dòng）指身体或东西换了位置。"}, {"text": "冬", "is_correct": false, "explanation": "dōng（第一声）与 dòng（第四声）声调不同，意思是冬天。"}, {"text": "同", "is_correct": false, "explanation": "tóng（第二声）与 dòng（第四声）声调不同，意思是相同。"}, {"text": "痛", "is_correct": false, "explanation": "tòng 与 dòng 声母不同（t 与 d），意思是疼痛。"}, {"text": "懂", "is_correct": false, "explanation": "dǒng（第三声）与 dòng（第四声）声调不同，意思是明白。"}], "explanations": {"动": "正确：动（dòng）指身体或东西换了位置。", "冬": "dōng（第一声）与 dòng（第四声）声调不同，意思是冬天。", "同": "tóng（第二声）与 dòng（第四声）声调不同，意思是相同。", "痛": "tòng 与 dòng 声母不同（t 与 d），意思是疼痛。", "懂": "dǒng（第三声）与 dòng（第四声）声调不同，意思是明白。"}, "sentence_index": null, "correct_answer": "动"}, "level_3": {"options": [{"text": "动", "is_correct": true, "explanation": "正确：“一直不动”说车没有移动，所以“我们到不了”。"}, {"text": "吃", "is_correct": false, "explanation": "语义：车不会“吃”，句子说的是车停着不走，“吃”与句意无关。"}, {"text": "说", "is_correct": false, "explanation": "语义：车不会“说”，与“我们到不了”的前后语境不符。"}, {"text": "推", "is_correct": false, "explanation": "配价：“推”需要带受事宾语，“一直不推”后面缺少宾语，不成立。"}], "explanations": {"动": "正确：“一直不动”说车没有移动，所以“我们到不了”。", "吃": "语义：车不会“吃”，句子说的是车停着不走，“吃”与句意无关。", "说": "语义：车不会“说”，与“我们到不了”的前后语境不符。", "推": "配价：“推”需要带受事宾语，“一直不推”后面缺少宾语，不成立。"}, "sentence_index": 0, "correct_answer": "动"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他动了一个小时的数学题，终于做完了。", "explanation": "这里应该用〈做〉。动表示移动或变化，做数学题要用做，不能说动题。"}, {"text": "听了这个故事，我很动。", "explanation": "这里应该用〈感动〉。动在此表示移动，心里受触动要用感动，“很动”不成立。"}, {"text": "他一只手动着一杯水，另一只手开门。", "explanation": "这里应该用〈端〉。动强调换了位置，端指用手托着，不是移动。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '415aa2a1-1bc1-4dae-858f-381cc84b3069') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87125, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "动", "is_correct": true, "explanation": "正确：动（dòng）指身体或东西换了位置。"}, {"text": "东", "is_correct": false, "explanation": "dōng（第一声）与 dòng（第四声）声调不同，意思是东方。"}, {"text": "弄", "is_correct": false, "explanation": "nòng 与 dòng 声母不同（n 与 d），意思是摆弄、做。"}, {"text": "共", "is_correct": false, "explanation": "gòng 与 dòng 声母不同（g 与 d），意思是共同。"}, {"text": "空", "is_correct": false, "explanation": "kòng 与 dòng 声母不同（k 与 d），意思是空闲。"}], "explanations": {"动": "正确：动（dòng）指身体或东西换了位置。", "东": "dōng（第一声）与 dòng（第四声）声调不同，意思是东方。", "弄": "nòng 与 dòng 声母不同（n 与 d），意思是摆弄、做。", "共": "gòng 与 dòng 声母不同（g 与 d），意思是共同。", "空": "kòng 与 dòng 声母不同（k 与 d），意思是空闲。"}, "sentence_index": null, "correct_answer": "动"}, "level_3": {"options": [{"text": "动", "is_correct": true, "explanation": "正确：“一点儿也没动”指孩子睡着时一点儿没有活动。"}, {"text": "是", "is_correct": false, "explanation": "搭配：“是”不能用“没”否定，“一点儿也没是”不成立。"}, {"text": "喜欢", "is_correct": false, "explanation": "语义：孩子睡着时不会“没喜欢”什么，与句意不合。"}, {"text": "感到", "is_correct": false, "explanation": "配价：“感到”需要带成分（如“累”），单独“没感到”不完整。"}], "explanations": {"动": "正确：“一点儿也没动”指孩子睡着时一点儿没有活动。", "是": "搭配：“是”不能用“没”否定，“一点儿也没是”不成立。", "喜欢": "语义：孩子睡着时不会“没喜欢”什么，与句意不合。", "感到": "配价：“感到”需要带成分（如“累”），单独“没感到”不完整。"}, "sentence_index": 6, "correct_answer": "动"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他刚才动了一个电话，很快就接通了。", "explanation": "这里应该用〈打〉。动表示移动或变化，打电话要用打，不能说动电话。"}, {"text": "他动上了一件外套。", "explanation": "这里应该用〈穿〉。动表示位置变化，穿衣服要用穿。"}, {"text": "他一边唱歌，一边动手里的吉他。", "explanation": "这里应该用〈弹〉。动表示移动，弹吉他要用弹，不能说动吉他。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '415aa2a1-1bc1-4dae-858f-381cc84b3069') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87125, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "孩子动动了小手。", "corrected_sentence": "孩子动了动小手。", "error_description": "“了”位置错误。“动了动”是动词重叠中间加“了”，应为“动了动”；“动动了”不成立。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '415aa2a1-1bc1-4dae-858f-381cc84b3069') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87125, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "小鱼在水里动地很快。", "corrected_sentence": "小鱼在水里动得很快。", "error_description": "“得”误写为“地”。“动”后的程度补语要用“得”，应为“动得很快”；“地”是状语标记，不能放在动词后作补语。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '415aa2a1-1bc1-4dae-858f-381cc84b3069') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
