INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87126, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "静", "is_correct": true, "explanation": "静与动相对，指不动、静止，是这一义项的反义词。"}, {"text": "跑", "is_correct": false, "explanation": "跑是快速移动的动作，与“动”没有反义关系。"}, {"text": "看", "is_correct": false, "explanation": "看是视觉动作，与“动”没有反义关系。"}, {"text": "喝", "is_correct": false, "explanation": "喝是进食动作，与“动”没有反义关系。"}], "correct_answer": "静", "explanations": {"静": "静与动相对，指不动、静止，是这一义项的反义词。", "跑": "跑是快速移动的动作，与“动”没有反义关系。", "看": "看是视觉动作，与“动”没有反义关系。", "喝": "喝是进食动作，与“动”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '415aa2a1-1bc1-4dae-858f-381cc84b3069') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87126, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "物体的位置或状态发生变化；做动作。", "primary_collocate": null, "pronunciation": "dòng", "ipa": "tʊŋ˥˩", "syllable_count": 1, "sentences": [{"text": "他动了动手指，看看还疼不疼。", "target_word": "动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "坐了很久，我站起来动动腿。", "target_word": "动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下课后，大家动一动，做做操。", "target_word": "动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电脑里的图片动起来了。", "target_word": "动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "机器一开，轮子就动了。", "target_word": "动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子看见妈妈，高兴得手脚都动起来。", "target_word": "动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水面动了一下，可能有鱼。", "target_word": "动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的嘴动了动，却没有说话。", "target_word": "动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的手一动，杯子就倒了。", "target_word": "动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的手表坏了，现在又动起来了。", "target_word": "动", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "動", "label": "繁体"}, {"form": "动了", "label": "体标"}, {"form": "动着", "label": "体标"}, {"form": "动过", "label": "体标"}, {"form": "动动", "label": "重叠"}], "register": "中性", "sense_fingerprint": "物体状态变化或身体部位做动作", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8b2c5003-937d-4490-b759-8fcdbf134d37') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87126, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "动", "is_correct": true, "explanation": "正确：动（dòng）指物体的位置或状态发生变化。"}, {"text": "冬", "is_correct": false, "explanation": "dōng（第一声）与 dòng（第四声）声调不同，意思是冬天。"}, {"text": "同", "is_correct": false, "explanation": "tóng（第二声）与 dòng（第四声）声调不同，意思是相同。"}, {"text": "痛", "is_correct": false, "explanation": "tòng 与 dòng 声母不同（t 与 d），意思是疼痛。"}, {"text": "懂", "is_correct": false, "explanation": "dǒng（第三声）与 dòng（第四声）声调不同，意思是明白。"}], "explanations": {"动": "正确：动（dòng）指物体的位置或状态发生变化。", "冬": "dōng（第一声）与 dòng（第四声）声调不同，意思是冬天。", "同": "tóng（第二声）与 dòng（第四声）声调不同，意思是相同。", "痛": "tòng 与 dòng 声母不同（t 与 d），意思是疼痛。", "懂": "dǒng（第三声）与 dòng（第四声）声调不同，意思是明白。"}, "sentence_index": null, "correct_answer": "动"}, "level_3": {"options": [{"text": "动", "is_correct": true, "explanation": "正确：“动了动手指”表示手指活动一下，句意完整。"}, {"text": "吃", "is_correct": false, "explanation": "语义：手指不能被“吃”，句子说的是活动手指。"}, {"text": "写", "is_correct": false, "explanation": "语义：“写了手指”不成立，与看疼不疼的句意无关。"}, {"text": "抬", "is_correct": false, "explanation": "配价：“抬”需要带受事宾语，“抬了动手指”结构不成立。"}], "explanations": {"动": "正确：“动了动手指”表示手指活动一下，句意完整。", "吃": "语义：手指不能被“吃”，句子说的是活动手指。", "写": "语义：“写了手指”不成立，与看疼不疼的句意无关。", "抬": "配价：“抬”需要带受事宾语，“抬了动手指”结构不成立。"}, "sentence_index": 0, "correct_answer": "动"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这台电脑动好了。", "explanation": "这里应该用〈修〉。动表示位置或状态的改变，电脑修好要用修。"}, {"text": "天色动起来了，看样子要下雨。", "explanation": "这里应该用〈暗下来〉。“要下雨”指天色变暗，动起来指开始活动，不能形容天色的变化。"}, {"text": "他昨天动了一幅水墨，很漂亮。", "explanation": "这里应该用〈画〉。动表示位置或状态的改变，画一幅水墨要用画，不能说动。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '415aa2a1-1bc1-4dae-858f-381cc84b3069') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87126, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "动", "is_correct": true, "explanation": "正确：动（dòng）指物体的位置或状态发生变化。"}, {"text": "东", "is_correct": false, "explanation": "dōng（第一声）与 dòng（第四声）声调不同，意思是东方。"}, {"text": "弄", "is_correct": false, "explanation": "nòng 与 dòng 声母不同（n 与 d），意思是摆弄、做。"}, {"text": "共", "is_correct": false, "explanation": "gòng 与 dòng 声母不同（g 与 d），意思是共同。"}, {"text": "空", "is_correct": false, "explanation": "kòng 与 dòng 声母不同（k 与 d），意思是空闲。"}], "explanations": {"动": "正确：动（dòng）指物体的位置或状态发生变化。", "东": "dōng（第一声）与 dòng（第四声）声调不同，意思是东方。", "弄": "nòng 与 dòng 声母不同（n 与 d），意思是摆弄、做。", "共": "gòng 与 dòng 声母不同（g 与 d），意思是共同。", "空": "kòng 与 dòng 声母不同（k 与 d），意思是空闲。"}, "sentence_index": null, "correct_answer": "动"}, "level_3": {"options": [{"text": "动", "is_correct": true, "explanation": "正确：“水面动了一下”说水面有了变化，所以“可能有鱼”。"}, {"text": "唱", "is_correct": false, "explanation": "语义：水面不会“唱”，与“可能有鱼”的句意不合。"}, {"text": "踢", "is_correct": false, "explanation": "配价：“踢”需要带宾语，“水面踢了一下”结构不成立。"}, {"text": "骂", "is_correct": false, "explanation": "语义：水面不会“骂”，与句意无关。"}], "explanations": {"动": "正确：“水面动了一下”说水面有了变化，所以“可能有鱼”。", "唱": "语义：水面不会“唱”，与“可能有鱼”的句意不合。", "踢": "配价：“踢”需要带宾语，“水面踢了一下”结构不成立。", "骂": "语义：水面不会“骂”，与句意无关。"}, "sentence_index": 6, "correct_answer": "动"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他给墙动了一层漆，颜色很好看。", "explanation": "这里应该用〈涂〉。动表示位置或状态的改变，给墙涂漆要用涂，不能说动一层漆。"}, {"text": "门铃吃起来了。", "explanation": "这里应该用〈响起来〉。门铃发出的是声音，不能说吃起来。"}, {"text": "他拿起笔，一边想一边动字。", "explanation": "这里应该用〈写〉。动表示位置或状态的改变，写字要用写，不能说动字。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '415aa2a1-1bc1-4dae-858f-381cc84b3069') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87126, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "屏幕突然动出来了。", "corrected_sentence": "屏幕突然动起来了。", "error_description": "补语“出来”用错。表示动作开始并持续的补语是“起来”，应说“动起来”；“动出来”不成立。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '415aa2a1-1bc1-4dae-858f-381cc84b3069') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87126, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "车子动地很慢，我们都在等。", "corrected_sentence": "车子动得很慢，我们都在等。", "error_description": "“得”误写为“地”。“动”后的程度补语要用“得”，应为“动得很慢”；“动地很慢”中“地”是状语标记，不能放在动词后作补语。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '415aa2a1-1bc1-4dae-858f-381cc84b3069') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
