INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87139, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "字是我们写下来、用来看的东西，比如“大”“小”。", "primary_collocate": null, "pronunciation": "zì", "ipa": "tsɹ̩˥˩", "syllable_count": 1, "sentences": [{"text": "黑板上写着三个大字。", "target_word": "字", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个字我不认识。", "target_word": "字", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书上有一个字印错了。", "target_word": "字", "complexity_tier": "T3", "furigana": "shū shàng yǒu yí ge zì yìn cuò le", "sentence_source": "generated"}, {"text": "请把这个字写大一点。", "target_word": "字", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明在纸上写了一个“大”字。", "target_word": "字", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "墙上的字太小，我看不清。", "target_word": "字", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师把这个字写在黑板上了。", "target_word": "字", "complexity_tier": "T3", "furigana": "lǎo shī bǎ zhè ge zì xiě zài hēi bǎn shàng le", "sentence_source": "generated"}, {"text": "妈妈教我写字。", "target_word": "字", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书的字很大，爷爷也能看。", "target_word": "字", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "门上贴着一张红纸，纸上有四个字。", "target_word": "字", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "汉字", "label": "复合"}, {"form": "文字", "label": "复合"}], "register": "中性", "sense_fingerprint": "写在纸上、黑板上、墙上等处可以看到的字", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 9 above tier T1: 3 words above tier T1 (max 2): 门上 (Zipf 3.45), 贴着 (Zipf 3.34), 纸上 (Zipf 3.2)']::text[], '8b2c5003-937d-4490-b759-8fcdbf134d37') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87139, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "字", "is_correct": true, "explanation": "字（zì，第四声）指写在纸上、墙上等处可以看到的字符，是本题的正确答案。"}, {"text": "子", "is_correct": false, "explanation": "zǐ（第三声）与 zì（第四声）声调不同，意思是儿子、子女。"}, {"text": "次", "is_correct": false, "explanation": "cì 与 zì 声母不同（c 与 z），意思是次数、次序。"}, {"text": "四", "is_correct": false, "explanation": "sì 与 zì 声母不同（s 与 z），意思是数字四。"}, {"text": "志", "is_correct": false, "explanation": "zhì 与 zì 声母不同（zh 与 z），意思是志向、志气。"}], "explanations": {"字": "字（zì，第四声）指写在纸上、墙上等处可以看到的字符，是本题的正确答案。", "子": "zǐ（第三声）与 zì（第四声）声调不同，意思是儿子、子女。", "次": "cì 与 zì 声母不同（c 与 z），意思是次数、次序。", "四": "sì 与 zì 声母不同（s 与 z），意思是数字四。", "志": "zhì 与 zì 声母不同（zh 与 z），意思是志向、志气。"}, "sentence_index": null, "correct_answer": "字"}, "level_3": {"options": [{"text": "球", "is_correct": false, "explanation": "语义：球不是可以写上去的东西，与“写着”的意思不合。"}, {"text": "字", "is_correct": true, "explanation": "字：写在黑板上的字符，与“写着”搭配，是唯一能填入的词。"}, {"text": "房子", "is_correct": false, "explanation": "搭配：“写着”的对象是字、词、名字等，不说写着房子。"}, {"text": "盒子", "is_correct": false, "explanation": "语义：盒子不能用来写字，与“写着”的语境不合。"}], "explanations": {"球": "语义：球不是可以写上去的东西，与“写着”的意思不合。", "字": "字：写在黑板上的字符，与“写着”搭配，是唯一能填入的词。", "房子": "搭配：“写着”的对象是字、词、名字等，不说写着房子。", "盒子": "语义：盒子不能用来写字，与“写着”的语境不合。"}, "sentence_index": 0, "correct_answer": "字"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "英语有二十六个字。", "explanation": "这里应该用〈字母〉。字母指拉丁字母等拼音文字的符号，“字”一般指汉字，英语的符号要说字母。"}, {"text": "我认识这只字。", "explanation": "这里应该用〈个〉。“字”用量词“个”，“只”一般用于动物或小东西，不能用于字。"}, {"text": "这个电话号码有十一个字。", "explanation": "这里应该用〈数字〉。电话号码由数字组成，“字”指记录语言的符号，号码不能说字。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '415aa2a1-1bc1-4dae-858f-381cc84b3069') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87139, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "字", "is_correct": true, "explanation": "字（zì，第四声）指写在纸上、墙上等处可以看到的字符，是本题的正确答案。"}, {"text": "紫", "is_correct": false, "explanation": "zǐ（第三声）与 zì（第四声）声调不同，意思是紫色。"}, {"text": "刺", "is_correct": false, "explanation": "cì 与 zì 声母不同（c 与 z），意思是尖的东西、刺。"}, {"text": "寺", "is_correct": false, "explanation": "sì 与 zì 声母不同（s 与 z），意思是寺庙。"}, {"text": "质", "is_correct": false, "explanation": "zhì 与 zì 声母不同（zh 与 z），意思是质量、品质。"}], "explanations": {"字": "字（zì，第四声）指写在纸上、墙上等处可以看到的字符，是本题的正确答案。", "紫": "zǐ（第三声）与 zì（第四声）声调不同，意思是紫色。", "刺": "cì 与 zì 声母不同（c 与 z），意思是尖的东西、刺。", "寺": "sì 与 zì 声母不同（s 与 z），意思是寺庙。", "质": "zhì 与 zì 声母不同（zh 与 z），意思是质量、品质。"}, "sentence_index": null, "correct_answer": "字"}, "level_3": {"options": [{"text": "人", "is_correct": false, "explanation": "语义：人不能被写在黑板上，与“写在黑板上”的意思不合。"}, {"text": "字", "is_correct": true, "explanation": "字：写在黑板上的字符，是老师写下的对象，是唯一能填入的词。"}, {"text": "画", "is_correct": false, "explanation": "搭配：“写”的对象是字、词等文字，不说写画。"}, {"text": "窗户", "is_correct": false, "explanation": "语义：窗户不能写在黑板上，与句子的语境不合。"}], "explanations": {"人": "语义：人不能被写在黑板上，与“写在黑板上”的意思不合。", "字": "字：写在黑板上的字符，是老师写下的对象，是唯一能填入的词。", "画": "搭配：“写”的对象是字、词等文字，不说写画。", "窗户": "语义：窗户不能写在黑板上，与句子的语境不合。"}, "sentence_index": 6, "correct_answer": "字"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的银行卡密码由六个字组成。", "explanation": "这里应该用〈数字〉。密码一般由数字组成，“字”指记录语言的符号，不能用来说密码的位数。"}, {"text": "墙上有一粒字。", "explanation": "这里应该用〈个〉。“字”用量词“个”，“粒”用于米、沙等细小颗粒，不能配字。"}, {"text": "纸上有四张字。", "explanation": "这里应该用〈个〉。“字”用量词“个”，“张”用于纸、桌子等平面的东西，不能配字。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '415aa2a1-1bc1-4dae-858f-381cc84b3069') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87139, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他在纸上写了两只字。", "corrected_sentence": "他在纸上写了两个字。", "error_description": "错误：“两只字”。正确：“两个字”。字用量词“个”，“只”用于动物或小东西，不能用于字。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '415aa2a1-1bc1-4dae-858f-381cc84b3069') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87139, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "纸上写着一本字。", "corrected_sentence": "纸上写着一个字。", "error_description": "错误：“一本字”。正确：“一个字”。字用量词“个”，“本”用于书册，不能用于字。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '415aa2a1-1bc1-4dae-858f-381cc84b3069') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
