INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87140, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "记录语言的符号；文字。", "primary_collocate": null, "pronunciation": "zì", "ipa": "tsɹ̩˥˩", "syllable_count": 1, "sentences": [{"text": "字是用来记录语言的符号。", "target_word": "字", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "古时候的人先有话，后来才有字。", "target_word": "字", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个字有两个读音，你知道吗？", "target_word": "字", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每个字都有自己的意思。", "target_word": "字", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在字典里查这个字的意思。", "target_word": "字", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个字有八笔，写的时候要小心。", "target_word": "字", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "中国的字很早就有了。", "target_word": "字", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "不认识字的人，很难读书看报。", "target_word": "字", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他会说汉语，可是还不会写字。", "target_word": "字", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有了字，人们才能把话写下来。", "target_word": "字", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "汉字", "label": "复合"}, {"form": "文字", "label": "复合"}], "register": "中性", "sense_fingerprint": "记录语言的文字符号，有读音、意思和笔画", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8b2c5003-937d-4490-b759-8fcdbf134d37') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87140, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "字", "is_correct": true, "explanation": "字（zì，第四声）指记录语言的文字符号，是本题的正确答案。"}, {"text": "子", "is_correct": false, "explanation": "zǐ（第三声）与 zì（第四声）声调不同，意思是儿子、子女。"}, {"text": "次", "is_correct": false, "explanation": "cì 与 zì 声母不同（c 与 z），意思是次数、次序。"}, {"text": "四", "is_correct": false, "explanation": "sì 与 zì 声母不同（s 与 z），意思是数字四。"}, {"text": "志", "is_correct": false, "explanation": "zhì 与 zì 声母不同（zh 与 z），意思是志向、志气。"}], "explanations": {"字": "字（zì，第四声）指记录语言的文字符号，是本题的正确答案。", "子": "zǐ（第三声）与 zì（第四声）声调不同，意思是儿子、子女。", "次": "cì 与 zì 声母不同（c 与 z），意思是次数、次序。", "四": "sì 与 zì 声母不同（s 与 z），意思是数字四。", "志": "zhì 与 zì 声母不同（zh 与 z），意思是志向、志气。"}, "sentence_index": null, "correct_answer": "字"}, "level_3": {"options": [{"text": "笔", "is_correct": false, "explanation": "语义：笔是书写工具，不是用来记录语言的符号，与“符号”的语境不合。"}, {"text": "字", "is_correct": true, "explanation": "字：记录语言的文字符号，与“用来记录语言的符号”相合，是唯一能填入的词。"}, {"text": "图画", "is_correct": false, "explanation": "语义：图画表达的是形象，不是记录语言的符号，与句子语境不合。"}, {"text": "录音", "is_correct": false, "explanation": "搭配：“符号”一般指文字、图形等书面标记，不说录音是符号。"}], "explanations": {"笔": "语义：笔是书写工具，不是用来记录语言的符号，与“符号”的语境不合。", "字": "字：记录语言的文字符号，与“用来记录语言的符号”相合，是唯一能填入的词。", "图画": "语义：图画表达的是形象，不是记录语言的符号，与句子语境不合。", "录音": "搭配：“符号”一般指文字、图形等书面标记，不说录音是符号。"}, "sentence_index": 0, "correct_answer": "字"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个门牌号有四个字。", "explanation": "这里应该用〈数字〉。门牌号由数字组成，“字”指记录语言的符号，号码不能说字。"}, {"text": "这条字我不认识。", "explanation": "这里应该用〈个〉。“字”用量词“个”，“条”用于长条形的东西，不能配字。"}, {"text": "英语有二十六个字。", "explanation": "这里应该用〈字母〉。字母指拼音文字的符号，“字”一般指汉字，英语的符号要说字母。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '415aa2a1-1bc1-4dae-858f-381cc84b3069') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87140, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "字", "is_correct": true, "explanation": "字（zì，第四声）指记录语言的文字符号，是本题的正确答案。"}, {"text": "紫", "is_correct": false, "explanation": "zǐ（第三声）与 zì（第四声）声调不同，意思是紫色。"}, {"text": "刺", "is_correct": false, "explanation": "cì 与 zì 声母不同（c 与 z），意思是尖的东西、刺。"}, {"text": "寺", "is_correct": false, "explanation": "sì 与 zì 声母不同（s 与 z），意思是寺庙。"}, {"text": "质", "is_correct": false, "explanation": "zhì 与 zì 声母不同（zh 与 z），意思是质量、品质。"}], "explanations": {"字": "字（zì，第四声）指记录语言的文字符号，是本题的正确答案。", "紫": "zǐ（第三声）与 zì（第四声）声调不同，意思是紫色。", "刺": "cì 与 zì 声母不同（c 与 z），意思是尖的东西、刺。", "寺": "sì 与 zì 声母不同（s 与 z），意思是寺庙。", "质": "zhì 与 zì 声母不同（zh 与 z），意思是质量、品质。"}, "sentence_index": null, "correct_answer": "字"}, "level_3": {"options": [{"text": "高铁", "is_correct": false, "explanation": "语义：高铁是近几十年才出现的，与“很早就有了”的语境不合。"}, {"text": "字", "is_correct": true, "explanation": "字：记录语言的文字，有悠久历史，与“很早就有了”相合，是唯一能填入的词。"}, {"text": "智能手机", "is_correct": false, "explanation": "搭配：“很早就有了”多用于古老的事物，智能手机是近年出现的。"}, {"text": "量子计算机", "is_correct": false, "explanation": "语义：量子计算机是很新的技术，与“很早就有了”的语境不合。"}], "explanations": {"高铁": "语义：高铁是近几十年才出现的，与“很早就有了”的语境不合。", "字": "字：记录语言的文字，有悠久历史，与“很早就有了”相合，是唯一能填入的词。", "智能手机": "搭配：“很早就有了”多用于古老的事物，智能手机是近年出现的。", "量子计算机": "语义：量子计算机是很新的技术，与“很早就有了”的语境不合。"}, "sentence_index": 6, "correct_answer": "字"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "数学用字表示数量。", "explanation": "这里应该用〈符号〉。字指记录语言的文字，表示数量要用数字或符号，数学一般不说用字。"}, {"text": "这个密码有六个字。", "explanation": "这里应该用〈数字〉。密码一般由数字组成，“字”指记录语言的符号，不能用来说密码的位数。"}, {"text": "这块字我不认识。", "explanation": "这里应该用〈个〉。“字”用量词“个”，“块”用于块状的东西，不能配字。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '415aa2a1-1bc1-4dae-858f-381cc84b3069') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model