INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87143, 1, 'prompt1_core', '{"pos": "代词", "semantic_class": "function", "definition": "多久是问时间有多长。", "primary_collocate": null, "pronunciation": "duō jiǔ", "ipa": "tuɔ˥ tɕjoʊ˨˩˦", "syllable_count": 2, "sentences": [{"text": "你每天学习多久？", "target_word": "多久", "complexity_tier": "T3", "furigana": "nǐ měi tiān xué xí duō jiǔ？", "sentence_source": "generated"}, {"text": "这件衣服你穿了多久？", "target_word": "多久", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他睡了多久？", "target_word": "多久", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你们结婚多久了？", "target_word": "多久", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请问，坐火车去上海要多久？", "target_word": "多久", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你在这家公司工作多久了？", "target_word": "多久", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师讲课讲了多久？", "target_word": "多久", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们还要等多久？", "target_word": "多久", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你每天运动多久？", "target_word": "多久", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书你看了多久？", "target_word": "多久", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "疑问代词；问一段时间有多长；常放在动词或“要”之后", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'caabb7e0-2a3a-4f9f-b03d-4a7815969b51') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87143, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "多高", "is_correct": false, "explanation": "语义：“多高”问高度，与“学习”的时长无关。"}, {"text": "多久", "is_correct": true, "explanation": "正确：“每天学习多久”问每天学习的时间长短，符合句意。"}, {"text": "多大", "is_correct": false, "explanation": "搭配：“多大”一般修饰年龄或物体大小，不能修饰“学习”的时长。"}, {"text": "多重", "is_correct": false, "explanation": "搭配：“多重”问重量，不能与“学习”搭配。"}], "explanations": {"多高": "语义：“多高”问高度，与“学习”的时长无关。", "多久": "正确：“每天学习多久”问每天学习的时间长短，符合句意。", "多大": "搭配：“多大”一般修饰年龄或物体大小，不能修饰“学习”的时长。", "多重": "搭配：“多重”问重量，不能与“学习”搭配。"}, "sentence_index": 0, "correct_answer": "多久"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "你们公司的员工是多久？", "explanation": "这里应该用〈多少〉。多久问时间的长短，问员工人数要用“多少”，不能说“员工是多久”。"}, {"text": "今天是多久？", "explanation": "这里应该用〈几号〉。多久问时间的长短，问日期要用“几号”，“今天是多久”不成立。"}, {"text": "这台电脑的价格是多久？", "explanation": "这里应该用〈多少钱〉。多久问时间的长短，问价格要用“多少钱”，不能说“价格是多久”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b367b12a-8299-455f-a174-4891011d28c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87143, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "多宽", "is_correct": false, "explanation": "语义：“多宽”问宽度，与“讲课”的时长无关。"}, {"text": "多快", "is_correct": false, "explanation": "语义：“多快”问速度，不能用来问讲课的时长。"}, {"text": "多久", "is_correct": true, "explanation": "正确：“讲课讲了多久”问讲课的时间长短，符合句意。"}, {"text": "怎么", "is_correct": false, "explanation": "搭配：“怎么”不能作“讲了”的时长宾语，“讲了怎么”不成句。"}], "explanations": {"多宽": "语义：“多宽”问宽度，与“讲课”的时长无关。", "多快": "语义：“多快”问速度，不能用来问讲课的时长。", "多久": "正确：“讲课讲了多久”问讲课的时间长短，符合句意。", "怎么": "搭配：“怎么”不能作“讲了”的时长宾语，“讲了怎么”不成句。"}, "sentence_index": 6, "correct_answer": "多久"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这条河的宽度是多久？", "explanation": "这里应该用〈多宽〉。多久问时间的长短，问宽度要用“多宽”，不能说“宽度是多久”。"}, {"text": "这座楼的高度是多久？", "explanation": "这里应该用〈多高〉。多久问时间的长短，问高度要用“多高”，不能说“高度是多久”。"}, {"text": "这张桌子的长度是多久？", "explanation": "这里应该用〈多长〉。多久问时间的长短，问长度要用“多长”，不能说“长度是多久”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b367b12a-8299-455f-a174-4891011d28c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87143, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他每天看电视看的多久？", "corrected_sentence": "他每天看电视看多久？", "error_description": "助词错误：“多久”前不能加“的”。应说“看电视看多久”，不能说“看电视看的多久”，“的”不能插在动词和“多久”之间。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b367b12a-8299-455f-a174-4891011d28c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87143, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们结婚的多久了？", "corrected_sentence": "他们结婚多久了？", "error_description": "助词错误：“多久”前不能加“的”。“多久”应直接接在“结婚”之后，说“结婚多久了”，不能说“结婚的多久了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b367b12a-8299-455f-a174-4891011d28c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
