INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87149, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "平是不高也不低，摸上去没有凸起来的地方。", "primary_collocate": null, "pronunciation": "píng", "ipa": "pʰiŋ˧˥", "syllable_count": 1, "sentences": [{"text": "这张桌子很平。", "target_word": "平", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "墙面摸上去很平，没有洞。", "target_word": "平", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小路修得很平，走起来很舒服。", "target_word": "平", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的床不太平，睡觉不舒服。", "target_word": "平", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用手把衣服抹平了。", "target_word": "平", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把地毯拉平，上面有一个包。", "target_word": "平", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这块石头一面很平，可以坐着休息。", "target_word": "平", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "球场的地面平平的，没有小坑。", "target_word": "平", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把这张纸放平，再写名字。", "target_word": "平", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水倒进盘子里，水面很快就平了。", "target_word": "平", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "平平的", "label": "重叠"}, {"form": "平整", "label": "复合"}, {"form": "平地", "label": "复合"}], "register": "中性", "sense_fingerprint": "平|不高不低没有凸起|形容词", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ae3816d5-8403-4a97-960f-1b509de16fef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87149, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "平", "is_correct": true, "explanation": "平（第二声）是正确答案，指不高不低、没有凸起的地方。"}, {"text": "明", "is_correct": false, "explanation": "míng（第二声）与 píng 声母不同（m 与 p），意思是明亮。"}, {"text": "听", "is_correct": false, "explanation": "tīng（第一声）与 píng 声母不同（t 与 p），声调也不同，意思是听见。"}, {"text": "旁", "is_correct": false, "explanation": "páng 与 píng 韵母不同（ang 与 ing），意思是旁边。"}, {"text": "朋", "is_correct": false, "explanation": "péng 与 píng 韵母不同（eng 与 ing），意思是朋友。"}, {"text": "冰", "is_correct": false, "explanation": "bīng（第一声）与 píng 声母不同（b 与 p），声调也不同，意思是冰。"}], "explanations": {"平": "平（第二声）是正确答案，指不高不低、没有凸起的地方。", "明": "míng（第二声）与 píng 声母不同（m 与 p），意思是明亮。", "听": "tīng（第一声）与 píng 声母不同（t 与 p），声调也不同，意思是听见。", "旁": "páng 与 píng 韵母不同（ang 与 ing），意思是旁边。", "朋": "péng 与 píng 韵母不同（eng 与 ing），意思是朋友。", "冰": "bīng（第一声）与 píng 声母不同（b 与 p），声调也不同，意思是冰。"}, "sentence_index": null, "correct_answer": "平"}, "level_3": {"options": [{"text": "平", "is_correct": true, "explanation": "平指表面不高不低、没有凸起，符合“这张桌子很平”的说法。"}, {"text": "甜", "is_correct": false, "explanation": "搭配：“甜”形容味道，不用来形容桌子。"}, {"text": "聪明", "is_correct": false, "explanation": "语义：“聪明”形容人的智力，不能用来形容桌子。"}, {"text": "嫩", "is_correct": false, "explanation": "搭配：“嫩”多形容植物、食物或皮肤，不用来形容桌子。"}], "explanations": {"平": "平指表面不高不低、没有凸起，符合“这张桌子很平”的说法。", "甜": "搭配：“甜”形容味道，不用来形容桌子。", "聪明": "语义：“聪明”形容人的智力，不能用来形容桌子。", "嫩": "搭配：“嫩”多形容植物、食物或皮肤，不用来形容桌子。"}, "sentence_index": 0, "correct_answer": "平"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的字写得很平，一笔一画都很清楚。", "explanation": "这里的“平”被用成了“工整”的意思，但“平”不用于形容字迹，应该用〈工整〉。"}, {"text": "他平了那个问题，大家都很满意。", "explanation": "这里的“平”被用成了“解决”的意思，但“平”只用于平息争端或平定叛乱，不能用于问题，应该用〈解决〉。"}, {"text": "他把书平得很快，一下子就看完了。", "explanation": "这里的“平”被用成了“翻阅”的意思，但“平”指表面平整，不能形容读书快，应该用〈翻〉或〈读〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'faf84b80-4df6-49a8-97a1-abfb129973e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87149, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "平", "is_correct": true, "explanation": "平（第二声）是正确答案，指不高不低、没有凸起的地方。"}, {"text": "停", "is_correct": false, "explanation": "tíng（第二声）与 píng 声母不同（t 与 p），声调相同，意思是停止。"}, {"text": "零", "is_correct": false, "explanation": "líng（第二声）与 píng 声母不同（l 与 p），声调相同，意思是零。"}, {"text": "饼", "is_correct": false, "explanation": "bǐng（第三声）与 píng 声母不同（b 与 p），声调也不同，意思是饼。"}, {"text": "兵", "is_correct": false, "explanation": "bīng（第一声）与 píng 声母不同（b 与 p），声调也不同，意思是士兵。"}], "explanations": {"平": "平（第二声）是正确答案，指不高不低、没有凸起的地方。", "停": "tíng（第二声）与 píng 声母不同（t 与 p），声调相同，意思是停止。", "零": "líng（第二声）与 píng 声母不同（l 与 p），声调相同，意思是零。", "饼": "bǐng（第三声）与 píng 声母不同（b 与 p），声调也不同，意思是饼。", "兵": "bīng（第一声）与 píng 声母不同（b 与 p），声调也不同，意思是士兵。"}, "sentence_index": null, "correct_answer": "平"}, "level_3": {"options": [{"text": "平", "is_correct": true, "explanation": "平指一面不高不低、没有凸起，符合“可以坐着休息”的语境。"}, {"text": "陡", "is_correct": false, "explanation": "语义：“陡”指坡度很大，不适合坐着休息，与后半句矛盾。"}, {"text": "尖", "is_correct": false, "explanation": "语义：“尖”指末端锐利，坐上去会不舒服，与“可以坐着休息”矛盾。"}, {"text": "重", "is_correct": false, "explanation": "搭配：“重”说的是重量，不用来形容石头某一面的平不平。"}], "explanations": {"平": "平指一面不高不低、没有凸起，符合“可以坐着休息”的语境。", "陡": "语义：“陡”指坡度很大，不适合坐着休息，与后半句矛盾。", "尖": "语义：“尖”指末端锐利，坐上去会不舒服，与“可以坐着休息”矛盾。", "重": "搭配：“重”说的是重量，不用来形容石头某一面的平不平。"}, "sentence_index": 6, "correct_answer": "平"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把这件事平给了老板。", "explanation": "这里的“平”被用成了“汇报”的意思，但“平”不表示把事情交给别人，应该用〈汇报〉。"}, {"text": "他平着脸，一句话也不说。", "explanation": "这里的“平”被用成了“板着”的意思，但“平”不用于形容脸色，应该用〈板〉。"}, {"text": "他把那篇稿子平改了三遍，还是不满意。", "explanation": "这里的“平”被用成了“修改”的意思，但“平”不表示修改文字，应该用〈改〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'faf84b80-4df6-49a8-97a1-abfb129973e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87149, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他把地面平扫了。", "corrected_sentence": "他把地面扫平了。", "error_description": "结果补语“平”应放在动词“扫”的后面，写成“平扫了”是错误。正确：扫平了；错误：平扫了。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'faf84b80-4df6-49a8-97a1-abfb129973e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87149, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把菜地翻了平，准备种菜。", "corrected_sentence": "他把菜地翻平了，准备种菜。", "error_description": "“了”应放在补语“平”的后面，写成“翻了平”是错误。正确：翻平了；错误：翻了平。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'faf84b80-4df6-49a8-97a1-abfb129973e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87150, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'faf84b80-4df6-49a8-97a1-abfb129973e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
