INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87155, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "厅是房子里很大的一间屋子，大家可以在里面聚会。", "primary_collocate": null, "pronunciation": "tīng", "ipa": "tʰiŋ˥", "syllable_count": 1, "sentences": [{"text": "我家有两室一厅。", "target_word": "厅", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "厅里放着一张大桌子。", "target_word": "厅", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个厅很大，能坐二十个人。", "target_word": "厅", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们在厅里玩球。", "target_word": "厅", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新房子的厅朝南，很亮。", "target_word": "厅", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们把沙发放在厅里吧。", "target_word": "厅", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从房间走到厅里。", "target_word": "厅", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "厅里的灯一直开着。", "target_word": "厅", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这套房子一厅两室，价格不高。", "target_word": "厅", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "过年时，全家人都在厅里吃饭。", "target_word": "厅", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "廳", "label": "繁体"}, {"form": "客厅", "label": "复合"}, {"form": "大厅", "label": "复合"}], "register": "中性", "sense_fingerprint": "房子里供大家活动的大房间", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '043aa009-a719-4f20-b3b2-bdf490915713') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87155, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "厅", "is_correct": true, "explanation": "正确：「厅」tīng（第一声），指房子里供大家活动的大房间。"}, {"text": "停", "is_correct": false, "explanation": "「停」tíng（第二声）与 tīng（第一声）声调不同，意思是停止。"}, {"text": "挺", "is_correct": false, "explanation": "「挺」tǐng（第三声）与 tīng（第一声）声调不同，意思是挺直或很。"}, {"text": "丁", "is_correct": false, "explanation": "「丁」dīng 与 tīng 声母不同（t 与 d），意思是成年男子或人口。"}], "explanations": {"厅": "正确：「厅」tīng（第一声），指房子里供大家活动的大房间。", "停": "「停」tíng（第二声）与 tīng（第一声）声调不同，意思是停止。", "挺": "「挺」tǐng（第三声）与 tīng（第一声）声调不同，意思是挺直或很。", "丁": "「丁」dīng 与 tīng 声母不同（t 与 d），意思是成年男子或人口。"}, "sentence_index": null, "correct_answer": "厅"}, "level_3": {"options": [{"text": "厅", "is_correct": true, "explanation": "正确：「两室一厅」中的「厅」指客厅，符合房屋结构的说法。"}, {"text": "室", "is_correct": false, "explanation": "语义：「室」与前面的「两室」重复，不能构成「两室一室」的房屋结构。"}, {"text": "楼", "is_correct": false, "explanation": "搭配：房屋结构的说法用「厅」，「两室一楼」不说。"}, {"text": "桌", "is_correct": false, "explanation": "语义：「桌」是家具，不是房间，「我家有两室一桌」句子不通。"}], "explanations": {"厅": "正确：「两室一厅」中的「厅」指客厅，符合房屋结构的说法。", "室": "语义：「室」与前面的「两室」重复，不能构成「两室一室」的房屋结构。", "楼": "搭配：房屋结构的说法用「厅」，「两室一楼」不说。", "桌": "语义：「桌」是家具，不是房间，「我家有两室一桌」句子不通。"}, "sentence_index": 0, "correct_answer": "厅"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这只厅很大，能坐二十个人。", "explanation": "量词：「厅」用「个」，不用「只」（「只」多用于动物或成对之物中的一个）。"}, {"text": "我姐姐在教育厅工作，每天都很忙。", "explanation": "语义：这里的「厅」指政府的职能部门，与「房子里很大的一间屋子」这一义项不同，句意不符。"}, {"text": "这块厅真大，能摆两张大桌子。", "explanation": "量词：「厅」用「个」或「间」，不用「块」（「块」多用于面积或成片的东西）。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4a01baeb-4c4d-4efc-b7c5-f345ae78b6b1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87155, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "厅", "is_correct": true, "explanation": "正确：「走到厅里」表示进入大房间，符合句意。"}, {"text": "书", "is_correct": false, "explanation": "语义：「书」是书籍，不能作为走进的场所，「走到书里」不通。"}, {"text": "纸", "is_correct": false, "explanation": "语义：「纸」是纸张，人不能走进纸里，句子不通。"}, {"text": "台", "is_correct": false, "explanation": "搭配：「台里」不能表示进入的地方，「走到台里」不说。"}], "explanations": {"厅": "正确：「走到厅里」表示进入大房间，符合句意。", "书": "语义：「书」是书籍，不能作为走进的场所，「走到书里」不通。", "纸": "语义：「纸」是纸张，人不能走进纸里，句子不通。", "台": "搭配：「台里」不能表示进入的地方，「走到台里」不说。"}, "sentence_index": 6, "correct_answer": "厅"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我表哥在财政厅工作，经常加班。", "explanation": "语义：这里的「厅」指政府部门，与「大房间」这一义项不同，句意指机关而非房间。"}, {"text": "这台厅很宽，可以摆下三张桌子。", "explanation": "量词：「厅」用「个」或「间」，不用「台」（「台」多用于机器、设备）。"}, {"text": "这位厅很认真，每天工作十个小时。", "explanation": "语义：「厅」是房间，不能指人，这句话把房间当成了人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4a01baeb-4c4d-4efc-b7c5-f345ae78b6b1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87155, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我家有一只大厅。", "corrected_sentence": "我家有一个大厅。", "error_description": "错误：「厅」的量词用「个」，不用「只」。正确说法是「一个大厅」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4a01baeb-4c4d-4efc-b7c5-f345ae78b6b1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87155, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "孩子们厅里玩耍。", "corrected_sentence": "孩子们在厅里玩耍。", "error_description": "错误：表示地点的「厅里」前面要加介词「在」。正确说法是「在厅里玩耍」，漏掉「在」不成立。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4a01baeb-4c4d-4efc-b7c5-f345ae78b6b1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
