INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87156, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "大型的房间，多用来集会、招待客人或办事。", "primary_collocate": null, "pronunciation": "tīng", "ipa": "tʰiŋ˥", "syllable_count": 1, "sentences": [{"text": "客人来了，我们在厅里招待他们。", "target_word": "厅", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个厅是开会用的。", "target_word": "厅", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "市民们在厅里排队办事。", "target_word": "厅", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "厅里坐满了来开会的人。", "target_word": "厅", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在厅外等了很久。", "target_word": "厅", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个厅很大，常用来开大会。", "target_word": "厅", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工作人员请我们到厅里坐。", "target_word": "厅", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "办事的人先去右边那个厅。", "target_word": "厅", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "晚上有一场聚会，就在这个厅。", "target_word": "厅", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "厅里很热闹，大家都在说话。", "target_word": "厅", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "廳", "label": "繁体"}, {"form": "大厅", "label": "复合"}, {"form": "餐厅", "label": "复合"}], "register": "中性", "sense_fingerprint": "用于集会、招待或办事的大型房间", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '043aa009-a719-4f20-b3b2-bdf490915713') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87156, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "厅", "is_correct": true, "explanation": "正确：「厅」tīng（第一声），指用于集会、招待或办事的大型房间。"}, {"text": "停", "is_correct": false, "explanation": "「停」tíng（第二声）与 tīng（第一声）声调不同，意思是停止。"}, {"text": "挺", "is_correct": false, "explanation": "「挺」tǐng（第三声）与 tīng（第一声）声调不同，意思是挺直或很。"}, {"text": "丁", "is_correct": false, "explanation": "「丁」dīng 与 tīng 声母不同（t 与 d），意思是成年男子或人口。"}], "explanations": {"厅": "正确：「厅」tīng（第一声），指用于集会、招待或办事的大型房间。", "停": "「停」tíng（第二声）与 tīng（第一声）声调不同，意思是停止。", "挺": "「挺」tǐng（第三声）与 tīng（第一声）声调不同，意思是挺直或很。", "丁": "「丁」dīng 与 tīng 声母不同（t 与 d），意思是成年男子或人口。"}, "sentence_index": null, "correct_answer": "厅"}, "level_3": {"options": [{"text": "厅", "is_correct": true, "explanation": "正确：「在厅里招待客人」中的「厅」指用于招待的大房间，符合句意。"}, {"text": "桌", "is_correct": false, "explanation": "搭配：「桌」是家具，不是招待的场所，「在桌里招待」不说。"}, {"text": "柜", "is_correct": false, "explanation": "语义：「柜」是储物家具，不能用来招待客人。"}, {"text": "池", "is_correct": false, "explanation": "语义：「池」是水池，与招待客人的语境不符，句子不通。"}], "explanations": {"厅": "正确：「在厅里招待客人」中的「厅」指用于招待的大房间，符合句意。", "桌": "搭配：「桌」是家具，不是招待的场所，「在桌里招待」不说。", "柜": "语义：「柜」是储物家具，不能用来招待客人。", "池": "语义：「池」是水池，与招待客人的语境不符，句子不通。"}, "sentence_index": 0, "correct_answer": "厅"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这张厅很大，能开大会。", "explanation": "量词：「厅」用「个」，不用「张」（「张」多用于桌子、纸张等平面的东西）。"}, {"text": "我父亲在省厅工作，每天很忙。", "explanation": "语义：这里的「厅」指政府部门，与「供集会的大房间」这一义项不同，句意不符。"}, {"text": "这台厅可以容纳五百人。", "explanation": "量词：「厅」用「个」，不用「台」（「台」多用于机器、设备）。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4a01baeb-4c4d-4efc-b7c5-f345ae78b6b1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87156, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "厅", "is_correct": true, "explanation": "正确：「请我们到厅里坐」中的「厅」指接待客人的大房间，符合句意。"}, {"text": "座", "is_correct": false, "explanation": "语义：「座」是座位，不是场所，「到座里坐」句子不通。"}, {"text": "椅", "is_correct": false, "explanation": "搭配：「到椅里坐」不说，应该说「坐在椅子上」。"}, {"text": "台", "is_correct": false, "explanation": "搭配：「台里」不能表示接待客人的地方，「到台里坐」不说。"}], "explanations": {"厅": "正确：「请我们到厅里坐」中的「厅」指接待客人的大房间，符合句意。", "座": "语义：「座」是座位，不是场所，「到座里坐」句子不通。", "椅": "搭配：「到椅里坐」不说，应该说「坐在椅子上」。", "台": "搭配：「台里」不能表示接待客人的地方，「到台里坐」不说。"}, "sentence_index": 6, "correct_answer": "厅"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这位厅很和气，总是笑着招待客人。", "explanation": "语义：「厅」指房间或机关，不能用「这位」指人，这句话把它当成了人。"}, {"text": "这块厅很大，能坐二十个人。", "explanation": "量词：「厅」用「个」，不用「块」（「块」多用于成片或成块的东西）。"}, {"text": "我妈妈在文化厅工作。", "explanation": "语义：这里的「厅」指政府部门，与「大房间」这一义项不同，句意指机关而非房间。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4a01baeb-4c4d-4efc-b7c5-f345ae78b6b1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87156, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只厅可以容纳五百人。", "corrected_sentence": "这个厅可以容纳五百人。", "error_description": "错误：「厅」的量词用「个」，不用「只」。正确说法是「这个厅」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4a01baeb-4c4d-4efc-b7c5-f345ae78b6b1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87156, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "大家都坐在里厅。", "corrected_sentence": "大家都坐在厅里。", "error_description": "错误：方位词「里」要放在名词之后，「厅里」是正确说法；「里厅」颠倒了词序，不能说。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4a01baeb-4c4d-4efc-b7c5-f345ae78b6b1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
