INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87184, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "一种家养动物，嗅觉灵敏，善于看家或帮助人做事。", "primary_collocate": null, "pronunciation": "gǒu", "ipa": "kou̯˨˩˦", "syllable_count": 1, "sentences": [{"text": "这条狗很会看家。", "target_word": "狗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "狗的鼻子特别灵。", "target_word": "狗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察带着狗找到了小偷。", "target_word": "狗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷家养了一条看家的狗。", "target_word": "狗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "盲人的狗能带他过马路。", "target_word": "狗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这只狗会帮牧羊人赶羊。", "target_word": "狗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "晚上有陌生人来，狗就叫了。", "target_word": "狗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他训练过这只狗找东西。", "target_word": "狗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "狗闻了闻箱子，然后坐下了。", "target_word": "狗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条狗又聪明又听话。", "target_word": "狗", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "只", "label": "量词"}, {"form": "条", "label": "量词"}, {"form": "小狗", "label": "复合"}, {"form": "狗狗", "label": "重叠"}], "register": "中性", "sense_fingerprint": "嗅觉灵敏，看家或帮人做事的家养动物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '63f4d827-5213-4efb-b0e0-f6115791d1c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87184, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "狗", "is_correct": true, "explanation": "正确。gǒu，意思是狗，一种家养动物。"}, {"text": "够", "is_correct": false, "explanation": "gòu（第四声）与 gǒu（第三声）声调不同，意思是足够。"}, {"text": "口", "is_correct": false, "explanation": "kǒu 与 gǒu 声母不同（k 与 g），声调相同，意思是嘴。"}, {"text": "走", "is_correct": false, "explanation": "zǒu 与 gǒu 声母不同（z 与 g），声调相同，意思是走路。"}, {"text": "抖", "is_correct": false, "explanation": "dǒu 与 gǒu 声母不同（d 与 g），声调相同，意思是抖动。"}], "explanations": {"狗": "正确。gǒu，意思是狗，一种家养动物。", "够": "gòu（第四声）与 gǒu（第三声）声调不同，意思是足够。", "口": "kǒu 与 gǒu 声母不同（k 与 g），声调相同，意思是嘴。", "走": "zǒu 与 gǒu 声母不同（z 与 g），声调相同，意思是走路。", "抖": "dǒu 与 gǒu 声母不同（d 与 g），声调相同，意思是抖动。"}, "sentence_index": null, "correct_answer": "狗"}, "level_3": {"options": [{"text": "狗", "is_correct": true, "explanation": "正确。“这条狗”指一只会看家的动物，符合语境。"}, {"text": "鱼", "is_correct": false, "explanation": "语义：鱼不会看家，与“很会看家”矛盾。"}, {"text": "门", "is_correct": false, "explanation": "搭配：“条”一般不用于“门”，门应用“扇”或“道”。"}, {"text": "桌子", "is_correct": false, "explanation": "搭配：“条”不用于“桌子”，桌子应用“张”。"}], "explanations": {"狗": "正确。“这条狗”指一只会看家的动物，符合语境。", "鱼": "语义：鱼不会看家，与“很会看家”矛盾。", "门": "搭配：“条”一般不用于“门”，门应用“扇”或“道”。", "桌子": "搭配：“条”不用于“桌子”，桌子应用“张”。"}, "sentence_index": 0, "correct_answer": "狗"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "爷爷用狗耕地，一天能耕好几亩。", "explanation": "这里应该用〈牛〉。狗是看家、帮人做事的动物，耕地要用牛，不用狗。"}, {"text": "爷爷家的狗每天早上打鸣，把全家人都叫醒了。", "explanation": "这里应该用〈公鸡〉。“打鸣”是公鸡的叫声，狗会叫，不会打鸣。"}, {"text": "草丛里有一条狗，它吐着信子，慢慢爬行。", "explanation": "这里应该用〈蛇〉。“吐信子”和爬行是蛇的特点，狗不这样。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c645df3b-621c-4776-bd13-68de8b7dea98') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87184, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "狗", "is_correct": true, "explanation": "正确。gǒu，意思是狗，一种家养动物。"}, {"text": "购", "is_correct": false, "explanation": "gòu（第四声）与 gǒu（第三声）声调不同，意思是购买。"}, {"text": "鼓", "is_correct": false, "explanation": "gǔ 与 gǒu 韵母不同（u 与 ou），声调相同，意思是鼓。"}, {"text": "沟", "is_correct": false, "explanation": "gōu（第一声）与 gǒu（第三声）声调不同，意思是沟渠。"}, {"text": "藕", "is_correct": false, "explanation": "ǒu 比 gǒu 少了声母 g，声调相同，意思是莲藕。"}], "explanations": {"狗": "正确。gǒu，意思是狗，一种家养动物。", "购": "gòu（第四声）与 gǒu（第三声）声调不同，意思是购买。", "鼓": "gǔ 与 gǒu 韵母不同（u 与 ou），声调相同，意思是鼓。", "沟": "gōu（第一声）与 gǒu（第三声）声调不同，意思是沟渠。", "藕": "ǒu 比 gǒu 少了声母 g，声调相同，意思是莲藕。"}, "sentence_index": null, "correct_answer": "狗"}, "level_3": {"options": [{"text": "狗", "is_correct": true, "explanation": "正确。陌生人来时会叫的是狗，符合语境。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子不会叫，与“就叫了”不搭。"}, {"text": "石头", "is_correct": false, "explanation": "配价：“叫”要求能发声的主语，“石头”不能作“叫”的主语。"}, {"text": "大树", "is_correct": false, "explanation": "语义：大树不会发出叫声，与语境不符。"}], "explanations": {"狗": "正确。陌生人来时会叫的是狗，符合语境。", "桌子": "语义：桌子不会叫，与“就叫了”不搭。", "石头": "配价：“叫”要求能发声的主语，“石头”不能作“叫”的主语。", "大树": "语义：大树不会发出叫声，与语境不符。"}, "sentence_index": 6, "correct_answer": "狗"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这条狗在花园里采蜜，还会酿成蜂蜜。", "explanation": "这里应该用〈蜜蜂〉。狗不采蜜、不酿蜜，这是蜜蜂的工作。"}, {"text": "这条狗每天早上挤奶，挤得很多。", "explanation": "这里应该用〈奶牛〉。挤奶说的是奶牛、奶羊的事，不指狗。"}, {"text": "这条狗趴在窝里孵蛋，等小鸡出来。", "explanation": "这里应该用〈母鸡〉。孵蛋是鸟类的习性，狗不孵蛋。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c645df3b-621c-4776-bd13-68de8b7dea98') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87184, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "邻居养了一块看家的狗。", "corrected_sentence": "邻居养了一只看家的狗。", "error_description": "“狗”应用量词“只”或“条”，“块”用于块状的东西，不能说“一块狗”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c645df3b-621c-4776-bd13-68de8b7dea98') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87184, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他以前养过这块狗。", "corrected_sentence": "他以前养过这条狗。", "error_description": "量词错误：“狗”应用量词“条”或“只”，“块”用于块状的东西，不能说“这块狗”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c645df3b-621c-4776-bd13-68de8b7dea98') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
