INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87189, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "看见是用眼睛看到了。", "primary_collocate": null, "pronunciation": "kàn jiàn", "ipa": "kʰan⁵¹ tɕiɛn⁵¹", "syllable_count": 2, "sentences": [{"text": "我在路上看见了一只小狗。", "target_word": "看见", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你看见我的手机了吗？", "target_word": "看见", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "昨天我在车站看见了老同学。", "target_word": "看见", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天太黑，我什么也没看见。", "target_word": "看见", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他看见妈妈走进了厨房。", "target_word": "看见", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子看见雪，高兴得跳了起来。", "target_word": "看见", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我没看见那本书放在哪儿。", "target_word": "看见", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我从来没看见过这么大的鱼。", "target_word": "看见", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她看见门开着，就走了进去。", "target_word": "看见", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在山上能看见很远的海。", "target_word": "看见", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "看见了", "label": "完成体"}, {"form": "看见过", "label": "经历体"}, {"form": "没看见", "label": "否定"}], "register": "中性", "sense_fingerprint": "用眼睛看到某人或某物，强调看的结果", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dabb8dab-b90b-4c44-8fec-11f552bb446a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87189, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "看见", "is_correct": true, "explanation": "正确：“我在路上看见了一只小狗”，“看见”表示用眼睛看到，与“在路上”搭配自然。"}, {"text": "梦见", "is_correct": false, "explanation": "语义：“梦见”发生在睡梦中，与“在路上”的清醒场景冲突。"}, {"text": "看懂", "is_correct": false, "explanation": "搭配：“看懂”的对象是文字或意思，不能接“一只小狗”。"}, {"text": "看完", "is_correct": false, "explanation": "搭配：“看完”要求对象可以被看完，“一只小狗”不能这样搭配。"}], "explanations": {"看见": "正确：“我在路上看见了一只小狗”，“看见”表示用眼睛看到，与“在路上”搭配自然。", "梦见": "语义：“梦见”发生在睡梦中，与“在路上”的清醒场景冲突。", "看懂": "搭配：“看懂”的对象是文字或意思，不能接“一只小狗”。", "看完": "搭配：“看完”要求对象可以被看完，“一只小狗”不能这样搭配。"}, "sentence_index": 0, "correct_answer": "看见"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我看见了铁块的重量。", "explanation": "这里应该用〈掂出〉。重量要用手掂才能知道，“看见”只用于眼睛看到的事物。"}, {"text": "我看见了一阵寒意。", "explanation": "这里应该用〈感觉到〉。“寒意”是身体的感受，不能用眼睛看见，应说“感觉到”。"}, {"text": "我看见了饭菜的香味。", "explanation": "这里应该用〈闻到〉。香味要用鼻子感知，“看见”只用于眼睛看到的事物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c3bb0a1a-67c0-4958-ba6c-f5cef83a1758') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87189, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "看见", "is_correct": true, "explanation": "正确：“我没看见那本书放在哪儿”，“没看见”表示视线没有接触到，与语境相符。"}, {"text": "碰见", "is_correct": false, "explanation": "语义：“碰见”指偶然遇到人或事，不能接“那本书放在哪儿”这种位置信息，句子不通。"}, {"text": "看透", "is_correct": false, "explanation": "搭配：“看透”多接本质或心思，不接“书放在哪儿”这类位置。"}, {"text": "闻见", "is_correct": false, "explanation": "语义：“闻见”感知的是气味，无法得知书放在哪儿。"}], "explanations": {"看见": "正确：“我没看见那本书放在哪儿”，“没看见”表示视线没有接触到，与语境相符。", "碰见": "语义：“碰见”指偶然遇到人或事，不能接“那本书放在哪儿”这种位置信息，句子不通。", "看透": "搭配：“看透”多接本质或心思，不接“书放在哪儿”这类位置。", "闻见": "语义：“闻见”感知的是气味，无法得知书放在哪儿。"}, "sentence_index": 6, "correct_answer": "看见"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "在山上能看见很远的海浪声。", "explanation": "这里应该用〈听到〉。海浪声要用耳朵听，“看见”只用于眼睛看到的事物。"}, {"text": "我看见了蛋糕的甜味。", "explanation": "这里应该用〈尝到〉。甜味要用舌头尝，“看见”不能用于味道。"}, {"text": "我看见了夏天的热。", "explanation": "这里应该用〈感受到〉。热是身体的感受，不能用眼睛看见。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c3bb0a1a-67c0-4958-ba6c-f5cef83a1758') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87189, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我在街上正在看见了朋友。", "corrected_sentence": "我在街上看见了朋友。", "error_description": "“看见”是瞬间获得视觉结果的动词，不能与表示进行中的“正在”连用；应去掉“正在”，说“我在街上看见了朋友”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c3bb0a1a-67c0-4958-ba6c-f5cef83a1758') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87189, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我昨天没看见了那个人。", "corrected_sentence": "我昨天没看见那个人。", "error_description": "“没”否定动作时不能再带“了”，“没看见了”是错误的，应说“没看见”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c3bb0a1a-67c0-4958-ba6c-f5cef83a1758') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
