INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87190, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "眼睛看到；视线接触到。", "primary_collocate": null, "pronunciation": "kàn jiàn", "ipa": "kʰan⁵¹ tɕiɛn⁵¹", "syllable_count": 2, "sentences": [{"text": "站在窗前，他看见了远处的山。", "target_word": "看见", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我看见一个人把包放在桌上。", "target_word": "看见", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "晚上我们看见天上有很多星星。", "target_word": "看见", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你看见那辆红色的车了吗？", "target_word": "看见", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雨停后，我们看见了彩虹。", "target_word": "看见", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一进门就看见桌上的蛋糕。", "target_word": "看见", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我坐在后面，没看见黑板上的字。", "target_word": "看见", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她看见镜子里的自己笑了。", "target_word": "看见", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我看见他在门口等着。", "target_word": "看见", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明看见老师来了，马上坐好。", "target_word": "看见", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "看见了", "label": "完成体"}, {"form": "看见过", "label": "经历体"}, {"form": "没看见", "label": "否定"}], "register": "中性", "sense_fingerprint": "视线接触到某物，眼睛感知到眼前的人或景象", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dabb8dab-b90b-4c44-8fec-11f552bb446a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87190, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "看见", "is_correct": true, "explanation": "正确：“站在窗前，他看见了远处的山”，“看见”表示视线接触到远处的景象，搭配自然。"}, {"text": "听见", "is_correct": false, "explanation": "语义：“听见”感知的是声音，山不能被听见。"}, {"text": "闻见", "is_correct": false, "explanation": "语义：“闻见”感知的是气味，“远处的山”无法靠闻来感知。"}, {"text": "看透", "is_correct": false, "explanation": "搭配：“看透”多接本质或心思，不接具体的景物。"}], "explanations": {"看见": "正确：“站在窗前，他看见了远处的山”，“看见”表示视线接触到远处的景象，搭配自然。", "听见": "语义：“听见”感知的是声音，山不能被听见。", "闻见": "语义：“闻见”感知的是气味，“远处的山”无法靠闻来感知。", "看透": "搭配：“看透”多接本质或心思，不接具体的景物。"}, "sentence_index": 0, "correct_answer": "看见"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他看见一阵疼痛。", "explanation": "这里应该用〈感到〉。疼痛是身体的感觉，不能用眼睛看见。"}, {"text": "我看见了远处的钟声。", "explanation": "这里应该用〈听到〉。钟声要用耳朵听，“看见”只用于视线接触到的事物。"}, {"text": "我看见了一股烟味。", "explanation": "这里应该用〈闻到〉。烟味要用鼻子闻，不能用眼睛看见。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c3bb0a1a-67c0-4958-ba6c-f5cef83a1758') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87190, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "看见", "is_correct": true, "explanation": "正确：“我坐在后面，没看见黑板上的字”，“没看见”与“坐在后面”的视线距离相符。"}, {"text": "擦", "is_correct": false, "explanation": "语义：“擦”需要贴近黑板动手，与“坐在后面”的语境冲突。"}, {"text": "摸", "is_correct": false, "explanation": "语义：“摸”需要触碰，坐在后面无法摸到黑板上的字。"}, {"text": "听", "is_correct": false, "explanation": "搭配：“听”的对象是声音，不能接“黑板上的字”。"}], "explanations": {"看见": "正确：“我坐在后面，没看见黑板上的字”，“没看见”与“坐在后面”的视线距离相符。", "擦": "语义：“擦”需要贴近黑板动手，与“坐在后面”的语境冲突。", "摸": "语义：“摸”需要触碰，坐在后面无法摸到黑板上的字。", "听": "搭配：“听”的对象是声音，不能接“黑板上的字”。"}, "sentence_index": 6, "correct_answer": "看见"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我看见了汤的咸味。", "explanation": "这里应该用〈尝到〉。咸味要用舌头尝，“看见”不能用于味道。"}, {"text": "我看见了风的凉意。", "explanation": "这里应该用〈感受到〉。凉意是身体的感受，不能用眼睛看见。"}, {"text": "我看见了他的声音。", "explanation": "这里应该用〈听出〉。声音要用耳朵听出，不能用眼睛看见。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c3bb0a1a-67c0-4958-ba6c-f5cef83a1758') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87190, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他站在阳台上，看见着远处的船。", "corrected_sentence": "他站在阳台上，看见了远处的船。", "error_description": "“看见”后面不能接“着”，“看见着”不成立；表示视线接触到的结果要用“看见了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c3bb0a1a-67c0-4958-ba6c-f5cef83a1758') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87190, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "孩子们在院子里正在看见了一只鸟。", "corrected_sentence": "孩子们在院子里看见了一只鸟。", "error_description": "“看见”不能与表示进行中的“正在”连用，应去掉“正在”，说“孩子们在院子里看见了一只鸟”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c3bb0a1a-67c0-4958-ba6c-f5cef83a1758') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
