INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87198, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "可以配上曲调演唱的文词；歌曲。", "primary_collocate": null, "pronunciation": "gē", "ipa": "kɤ˥", "syllable_count": 1, "sentences": [{"text": "这首歌是一位年轻人写的。", "target_word": "歌", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的新歌今天在网上发布了。", "target_word": "歌", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这首歌在中国很流行。", "target_word": "歌", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "她写过很多关于家乡的歌。", "target_word": "歌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这首歌的旋律很轻柔，很适合睡前听。", "target_word": "歌", "complexity_tier": "T3", "furigana": "zhè shǒu gē de xuánlǜ hěn qīngróu hěn shìhé shuìqián tīng", "sentence_source": "generated"}, {"text": "演出的最后一首歌是大家一起唱的。", "target_word": "歌", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这首歌比那首歌更受年轻人欢迎。", "target_word": "歌", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这首歌有中文版，也有英文版。", "target_word": "歌", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他把自己的歌放在网上，很多人都听到了。", "target_word": "歌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这首老歌，爸爸年轻时常常听。", "target_word": "歌", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "一首歌", "label": "量词"}, {"form": "歌曲", "label": "复合词"}, {"form": "儿歌", "label": "复合词"}], "register": "中性", "sense_fingerprint": "配上曲调演唱的作品，即歌曲", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ae3816d5-8403-4a97-960f-1b509de16fef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87198, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "歌", "is_correct": true, "explanation": "正确答案：歌（gē，第一声），指配上曲调演唱的作品，即歌曲。"}, {"text": "隔", "is_correct": false, "explanation": "隔（gé，第二声）与歌（gē，第一声）声调不同，意思是隔壁。"}, {"text": "科", "is_correct": false, "explanation": "科（kē）与歌（gē）声母不同，k 与 g 不同，意思是科学。"}, {"text": "根", "is_correct": false, "explanation": "根（gēn）比歌（gē）多一个韵尾 n，意思是树根。"}, {"text": "喝", "is_correct": false, "explanation": "喝（hē）与歌（gē）声母不同，h 与 g 不同，意思是喝水。"}], "explanations": {"歌": "正确答案：歌（gē，第一声），指配上曲调演唱的作品，即歌曲。", "隔": "隔（gé，第二声）与歌（gē，第一声）声调不同，意思是隔壁。", "科": "科（kē）与歌（gē）声母不同，k 与 g 不同，意思是科学。", "根": "根（gēn）比歌（gē）多一个韵尾 n，意思是树根。", "喝": "喝（hē）与歌（gē）声母不同，h 与 g 不同，意思是喝水。"}, "sentence_index": null, "correct_answer": "歌"}, "level_3": {"options": [{"text": "歌", "is_correct": true, "explanation": "正确答案：这里是一首歌，由一位年轻人写成，“写的”与作品相搭配。"}, {"text": "桥", "is_correct": false, "explanation": "语义：桥是建筑物，不是人写出来的作品，不能说“写的桥”。"}, {"text": "汤", "is_correct": false, "explanation": "语义：汤是食物，不能由人“写”出来。"}, {"text": "桌子", "is_correct": false, "explanation": "搭配：量词“首”只用于诗、歌、曲等作品，不能修饰桌子。"}], "explanations": {"歌": "正确答案：这里是一首歌，由一位年轻人写成，“写的”与作品相搭配。", "桥": "语义：桥是建筑物，不是人写出来的作品，不能说“写的桥”。", "汤": "语义：汤是食物，不能由人“写”出来。", "桌子": "搭配：量词“首”只用于诗、歌、曲等作品，不能修饰桌子。"}, "sentence_index": 0, "correct_answer": "歌"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她讲过很多关于家乡的歌。", "explanation": "这里应该用〈故事〉。讲用于故事、笑话；歌是写出来或唱出来的，不能说讲歌。"}, {"text": "她写过很多张关于家乡的歌。", "explanation": "量词错误：这里应该用〈首〉。张用于纸张、桌子等平面的东西，歌曲用量词“首”。"}, {"text": "她吃过很多关于家乡的歌。", "explanation": "这里应该用〈唱〉。吃用于食物，歌不能吃。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'faf84b80-4df6-49a8-97a1-abfb129973e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87198, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "歌", "is_correct": true, "explanation": "正确答案：歌（gē，第一声），指配上曲调演唱的作品，即歌曲。"}, {"text": "革", "is_correct": false, "explanation": "革（gé，第二声）与歌（gē，第一声）声调不同，意思是革命、皮革。"}, {"text": "各", "is_correct": false, "explanation": "各（gè，第四声）与歌（gē，第一声）声调不同，意思是各自。"}, {"text": "颗", "is_correct": false, "explanation": "颗（kē）与歌（gē）声母不同，k 与 g 不同，意思是量词“一颗”。"}, {"text": "跟", "is_correct": false, "explanation": "跟（gēn）比歌（gē）多一个韵尾 n，意思是跟随、和。"}, {"text": "更", "is_correct": false, "explanation": "更（gēng）比歌（gē）多一个韵尾 ng，意思是更新。"}], "explanations": {"歌": "正确答案：歌（gē，第一声），指配上曲调演唱的作品，即歌曲。", "革": "革（gé，第二声）与歌（gē，第一声）声调不同，意思是革命、皮革。", "各": "各（gè，第四声）与歌（gē，第一声）声调不同，意思是各自。", "颗": "颗（kē）与歌（gē）声母不同，k 与 g 不同，意思是量词“一颗”。", "跟": "跟（gēn）比歌（gē）多一个韵尾 n，意思是跟随、和。", "更": "更（gēng）比歌（gē）多一个韵尾 ng，意思是更新。"}, "sentence_index": null, "correct_answer": "歌"}, "level_3": {"options": [{"text": "歌", "is_correct": true, "explanation": "正确答案：这里是一首歌，“比那首歌更受欢迎”说的是歌曲。"}, {"text": "楼", "is_correct": false, "explanation": "搭配：量词“首”只用于诗、歌、曲等作品，楼要用“座”，不能说“这首楼”。"}, {"text": "雨", "is_correct": false, "explanation": "搭配：量词“首”不修饰雨，雨一般用“场”，不能说“这首雨”。"}, {"text": "饭", "is_correct": false, "explanation": "语义：“首”用于诗、歌、曲等作品，饭不属于这一类，不能说“这首饭”。"}], "explanations": {"歌": "正确答案：这里是一首歌，“比那首歌更受欢迎”说的是歌曲。", "楼": "搭配：量词“首”只用于诗、歌、曲等作品，楼要用“座”，不能说“这首楼”。", "雨": "搭配：量词“首”不修饰雨，雨一般用“场”，不能说“这首雨”。", "饭": "语义：“首”用于诗、歌、曲等作品，饭不属于这一类，不能说“这首饭”。"}, "sentence_index": 6, "correct_answer": "歌"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "爸爸年轻时常常放映这首老歌。", "explanation": "这里应该用〈电影〉。放映用于电影、录像；歌是唱或听的，不能放映。"}, {"text": "爸爸年轻时常常画这首老歌。", "explanation": "这里应该用〈地图〉。画用于图画、地图；歌是唱或听的，不能说画歌。"}, {"text": "这幅老歌，爸爸年轻时常常听。", "explanation": "量词错误：这里应该用〈首〉。幅用于字画，歌曲用量词“首”，不能用“幅”来数。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'faf84b80-4df6-49a8-97a1-abfb129973e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87198, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这部歌是我们班的同学一起写的。", "corrected_sentence": "这首歌是我们班的同学一起写的。", "error_description": "量词错误：歌曲应用量词“首”，“部”用于电影、小说等作品，不能修饰歌。错误形式：这部歌；正确形式：这首歌。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'faf84b80-4df6-49a8-97a1-abfb129973e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87198, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他新出的一个歌在网上很受欢迎。", "corrected_sentence": "他新出的一首歌在网上很受欢迎。", "error_description": "量词错误：歌曲应用量词“首”，“个”是通用量词，不能用来数歌曲。错误形式：一个歌；正确形式：一首歌。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'faf84b80-4df6-49a8-97a1-abfb129973e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
