INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87205, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "猜是不知道对不对，先说出自己想的答案。", "primary_collocate": null, "pronunciation": "cāi", "ipa": "tsʰai˥", "syllable_count": 1, "sentences": [{"text": "我不知道答案，先猜一个吧。", "target_word": "猜", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这道题我不会，只能乱猜。", "target_word": "猜", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "老师问我答案，我猜是B。", "target_word": "猜", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "你猜我手里有什么？猜对了就送你。", "target_word": "猜", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我不确定，随便猜了一个答案。", "target_word": "猜", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他闭着眼睛，猜桌上放的是什么。", "target_word": "猜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个游戏要猜一个词，猜对的人得一分。", "target_word": "猜", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "不用想得太久，你先猜一下，错了也没关系。", "target_word": "猜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不看书就猜答案，所以常常猜错。", "target_word": "猜", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小明猜了三次，才猜对我的生日。", "target_word": "猜", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "猜了", "label": "体标"}, {"form": "猜过", "label": "体标"}, {"form": "猜猜", "label": "重叠"}, {"form": "猜拳", "label": "复合词"}], "register": "中性", "sense_fingerprint": "不确定对错，先说出自己想的答案", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ae3816d5-8403-4a97-960f-1b509de16fef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87205, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "猜", "is_correct": true, "explanation": "猜（第一声）是正确答案，指不确定对错时先说出自己想的答案。"}, {"text": "才", "is_correct": false, "explanation": "cái（第二声）与 cāi 声调不同，意思是才能、刚刚。"}, {"text": "拆", "is_correct": false, "explanation": "chāi 与 cāi 声母不同（ch 与 c），意思是拆开。"}, {"text": "腮", "is_correct": false, "explanation": "sāi 与 cāi 声母不同（s 与 c），意思是脸颊。"}, {"text": "彩", "is_correct": false, "explanation": "cǎi（第三声）与 cāi 声调不同，意思是彩色。"}, {"text": "灾", "is_correct": false, "explanation": "zāi 与 cāi 声母不同（z 与 c），意思是灾害。"}], "explanations": {"猜": "猜（第一声）是正确答案，指不确定对错时先说出自己想的答案。", "才": "cái（第二声）与 cāi 声调不同，意思是才能、刚刚。", "拆": "chāi 与 cāi 声母不同（ch 与 c），意思是拆开。", "腮": "sāi 与 cāi 声母不同（s 与 c），意思是脸颊。", "彩": "cǎi（第三声）与 cāi 声调不同，意思是彩色。", "灾": "zāi 与 cāi 声母不同（z 与 c），意思是灾害。"}, "sentence_index": null, "correct_answer": "猜"}, "level_3": {"options": [{"text": "猜", "is_correct": true, "explanation": "猜表示不知道答案时先说出一个，符合“我不知道答案，先猜一个吧”的语境。"}, {"text": "数", "is_correct": false, "explanation": "搭配：“数”指计数，用于能计数的事物，不能说“数一个答案”。"}, {"text": "摸", "is_correct": false, "explanation": "语义：“摸”是用手接触实物，与“答案”不搭，也与“不知道答案”的语境矛盾。"}, {"text": "拿", "is_correct": false, "explanation": "搭配：“拿”要求拿取具体的实物，不能用于“答案”。"}], "explanations": {"猜": "猜表示不知道答案时先说出一个，符合“我不知道答案，先猜一个吧”的语境。", "数": "搭配：“数”指计数，用于能计数的事物，不能说“数一个答案”。", "摸": "语义：“摸”是用手接触实物，与“答案”不搭，也与“不知道答案”的语境矛盾。", "拿": "搭配：“拿”要求拿取具体的实物，不能用于“答案”。"}, "sentence_index": 0, "correct_answer": "猜"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他猜了一封信，写得很长。", "explanation": "这里应该用〈写〉。猜表示不确定地说出答案，不能用来表示书写信件。"}, {"text": "我猜你的话，所以照着做了。", "explanation": "这里应该用〈相信〉。猜表示不确定地推测，不能用来表示对别人话语的信任。"}, {"text": "我用公式猜出了结果。", "explanation": "这里应该用〈计算〉。用公式得出的结果是确定的，猜表示没有把握地说出答案，不能用于此。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'faf84b80-4df6-49a8-97a1-abfb129973e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87205, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "猜", "is_correct": true, "explanation": "猜（第一声）是正确答案，指不确定对错时先说出自己想的答案。"}, {"text": "财", "is_correct": false, "explanation": "cái（第二声）与 cāi 声调不同，意思是财富。"}, {"text": "开", "is_correct": false, "explanation": "kāi 与 cāi 声母不同（k 与 c），意思是打开。"}, {"text": "菜", "is_correct": false, "explanation": "cài（第四声）与 cāi 声调不同，意思是蔬菜。"}, {"text": "赛", "is_correct": false, "explanation": "sài（第四声）与 cāi 声母不同（s 与 c），声调也不同，意思是比赛。"}, {"text": "采", "is_correct": false, "explanation": "cǎi（第三声）与 cāi 声调不同，意思是采集。"}], "explanations": {"猜": "猜（第一声）是正确答案，指不确定对错时先说出自己想的答案。", "财": "cái（第二声）与 cāi 声调不同，意思是财富。", "开": "kāi 与 cāi 声母不同（k 与 c），意思是打开。", "菜": "cài（第四声）与 cāi 声调不同，意思是蔬菜。", "赛": "sài（第四声）与 cāi 声母不同（s 与 c），声调也不同，意思是比赛。", "采": "cǎi（第三声）与 cāi 声调不同，意思是采集。"}, "sentence_index": null, "correct_answer": "猜"}, "level_3": {"options": [{"text": "猜", "is_correct": true, "explanation": "猜表示不确定地说出答案，符合“这个游戏要猜一个词”的语境。"}, {"text": "背", "is_correct": false, "explanation": "语义：“背”是记住已有的内容，与“猜对的人得一分”的游戏规则矛盾。"}, {"text": "扔", "is_correct": false, "explanation": "搭配：“扔”的宾语是具体的物品，不能接“一个词”。"}, {"text": "读", "is_correct": false, "explanation": "语义：“读”是把已有的词念出来，若直接读出就不用猜，与游戏规则矛盾。"}], "explanations": {"猜": "猜表示不确定地说出答案，符合“这个游戏要猜一个词”的语境。", "背": "语义：“背”是记住已有的内容，与“猜对的人得一分”的游戏规则矛盾。", "扔": "搭配：“扔”的宾语是具体的物品，不能接“一个词”。", "读": "语义：“读”是把已有的词念出来，若直接读出就不用猜，与游戏规则矛盾。"}, "sentence_index": 6, "correct_answer": "猜"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他在电脑上猜了我的生日。", "explanation": "这里应该用〈查询〉。猜是没有把握地说出答案，查询是在系统里找出确定的信息。"}, {"text": "他一个一个地猜了学生。", "explanation": "这里应该用〈数〉。猜不能用于逐个计数，数是确定地一个一个计算。"}, {"text": "他把课文猜得很熟。", "explanation": "这里应该用〈背〉。猜指没有把握地说出答案，不能用来形容对课文的熟记。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'faf84b80-4df6-49a8-97a1-abfb129973e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87205, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我猜了一个答案，但不猜对。", "corrected_sentence": "我猜了一个答案，但没猜对。", "error_description": "“猜对”表示已经发生的结果，否定要用“没”，写成“不”是错误。正确：没猜对；错误：不猜对。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'faf84b80-4df6-49a8-97a1-abfb129973e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87205, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他猜了错我的生日，我告诉了他。", "corrected_sentence": "他猜错了我的生日，我告诉了他。", "error_description": "“了”应放在补语“错”的后面，写成“猜了错”是错误。正确：猜错了；错误：猜了错。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'faf84b80-4df6-49a8-97a1-abfb129973e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
