INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87211, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "规模是一件事或一个东西有多大。", "primary_collocate": null, "pronunciation": "guī mó", "ipa": "kuei̯˥ muo˧˥", "syllable_count": 2, "sentences": [{"text": "这家工厂的规模很大。", "target_word": "规模", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公园的规模比我想的小。", "target_word": "规模", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们公司规模不大，只有十个人。", "target_word": "规模", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次比赛的规模是全国最大的。", "target_word": "规模", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新学校的规模已经扩大了。", "target_word": "规模", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个城市的规模一年比一年大。", "target_word": "规模", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想开一家小规模的饭馆。", "target_word": "规模", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家超市的规模太小，东西不多。", "target_word": "规模", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板打算扩大店的规模。", "target_word": "规模", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座桥的规模让游客很吃惊。", "target_word": "规模", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "小规模", "label": "复合"}, {"form": "大规模", "label": "复合"}], "register": "中性", "sense_fingerprint": "事情或东西的大小", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '63f4d827-5213-4efb-b0e0-f6115791d1c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87211, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "规模", "is_correct": true, "explanation": "正确。“规模”指事物的大小，可以用“很大”来形容。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：工厂的颜色不能用“很大”来形容，与语境不符。"}, {"text": "价格", "is_correct": false, "explanation": "搭配：“价格”一般说“高”或“低”，不说“很大”。"}, {"text": "性格", "is_correct": false, "explanation": "语义：工厂没有性格，不能说“性格很大”。"}], "explanations": {"规模": "正确。“规模”指事物的大小，可以用“很大”来形容。", "颜色": "语义：工厂的颜色不能用“很大”来形容，与语境不符。", "价格": "搭配：“价格”一般说“高”或“低”，不说“很大”。", "性格": "语义：工厂没有性格，不能说“性格很大”。"}, "sentence_index": 0, "correct_answer": "规模"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的规模很聪明，老师常常表扬他。", "explanation": "这里应该用〈头脑〉。“规模”指事物的范围大小，不指人的聪明程度，说聪明要用“头脑”。"}, {"text": "这篇文章的规模很感人，我读哭了。", "explanation": "这里应该用〈内容〉。“规模”指事物的范围大小，不指作品的感染力；“内容很感人”要用“内容”。"}, {"text": "这条河的规模很清澈，鱼虾都看得见。", "explanation": "这里应该用〈水〉。“规模”指范围大小，不指水的清浊；“水很清澈”要用“水”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c645df3b-621c-4776-bd13-68de8b7dea98') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87211, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "规模", "is_correct": true, "explanation": "正确。“小规模”指规模不大，可以修饰饭馆。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：饭馆没有年龄，“小年龄的饭馆”不成立。"}, {"text": "体重", "is_correct": false, "explanation": "搭配：“体重”只用于人或动物，不能修饰饭馆。"}, {"text": "性别", "is_correct": false, "explanation": "语义：饭馆没有性别，“小性别的饭馆”不成立。"}], "explanations": {"规模": "正确。“小规模”指规模不大，可以修饰饭馆。", "年龄": "语义：饭馆没有年龄，“小年龄的饭馆”不成立。", "体重": "搭配：“体重”只用于人或动物，不能修饰饭馆。", "性别": "语义：饭馆没有性别，“小性别的饭馆”不成立。"}, "sentence_index": 6, "correct_answer": "规模"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这台电脑的规模很高，打游戏非常流畅。", "explanation": "这里应该用〈规格〉。“规格”指产品的性能标准，电脑的性能要说“规格”；“规模”只指事物的范围、大小或数量。"}, {"text": "这家餐厅的规模很严格，不许大声说话。", "explanation": "这里应该用〈规定〉。“规模”指事物的范围大小，不指规矩严不严，说规定严格要用“规定”。"}, {"text": "他的规模很帅，走到哪里都有人看他。", "explanation": "这里应该用〈模样〉。“规模”指事物的大小范围，不用来形容人的外貌，说外貌要用“模样”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c645df3b-621c-4776-bd13-68de8b7dea98') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87211, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这座医院的规模很多。", "corrected_sentence": "这座医院的规模很大。", "error_description": "“规模”应用“大”来形容，不能用“多”。“多”用于说数量，如“人很多”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c645df3b-621c-4776-bd13-68de8b7dea98') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87211, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "医院地规模扩大了三倍。", "corrected_sentence": "医院的规模扩大了三倍。", "error_description": "结构错误：“规模”前面的修饰语要用“的”，不能用“地”；“地”用于修饰动词、形容词。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c645df3b-621c-4776-bd13-68de8b7dea98') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
