INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87212, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "事物所包含的范围、大小或数量。", "primary_collocate": null, "pronunciation": "guī mó", "ipa": "kuei̯˥ muo˧˥", "syllable_count": 2, "sentences": [{"text": "这次活动的规模有上千人。", "target_word": "规模", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司的生产规模扩大了一倍。", "target_word": "规模", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大规模的旅游让这个小镇变富了。", "target_word": "规模", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医院正在扩大规模，要请更多医生。", "target_word": "规模", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个展览的规模在全国排第一。", "target_word": "规模", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们的合作规模不太大。", "target_word": "规模", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "网上购物的规模每年都在变大。", "target_word": "规模", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个村子的养鱼规模已经很大了。", "target_word": "规模", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司没有那么大的规模，接不了这么多工作。", "target_word": "规模", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校办得有规模，学生有五千多人。", "target_word": "规模", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "小规模", "label": "复合"}, {"form": "大规模", "label": "复合"}], "register": "中性", "sense_fingerprint": "事物的范围、大小或数量", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '63f4d827-5213-4efb-b0e0-f6115791d1c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87212, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "规模", "is_correct": true, "explanation": "正确。“规模”指活动的范围大小，“有上千人”说明规模大。"}, {"text": "心情", "is_correct": false, "explanation": "语义：活动不会有“心情”，与“有上千人”不搭。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：活动没有颜色，与语境不符。"}, {"text": "价格", "is_correct": false, "explanation": "搭配：“价格”一般不用人数来说明，说“价格有上千”也不自然。"}], "explanations": {"规模": "正确。“规模”指活动的范围大小，“有上千人”说明规模大。", "心情": "语义：活动不会有“心情”，与“有上千人”不搭。", "颜色": "语义：活动没有颜色，与语境不符。", "价格": "搭配：“价格”一般不用人数来说明，说“价格有上千”也不自然。"}, "sentence_index": 0, "correct_answer": "规模"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这件事的规模已经过去三年了。", "explanation": "这里应该用〈时间〉。“规模”指范围、大小或数量，说过了多久要用“时间”。"}, {"text": "这道菜的规模很辣，我吃了一口就流眼泪。", "explanation": "这里应该用〈味道〉。“规模”指事物的范围、大小或数量，说菜的味道要用“味道”。"}, {"text": "今天的规模很冷，大家都穿厚衣服。", "explanation": "这里应该用〈温度〉。“规模”不指冷热，说天气冷热要用“温度”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c645df3b-621c-4776-bd13-68de8b7dea98') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87212, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "规模", "is_correct": true, "explanation": "正确。“规模每年都在变大”符合语境。"}, {"text": "体重", "is_correct": false, "explanation": "语义：购物没有体重，“体重每年都在变大”不成立。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：购物没有颜色，“颜色每年都在变大”不成立。"}, {"text": "身高", "is_correct": false, "explanation": "语义：购物没有身高，与语境不符。"}], "explanations": {"规模": "正确。“规模每年都在变大”符合语境。", "体重": "语义：购物没有体重，“体重每年都在变大”不成立。", "颜色": "语义：购物没有颜色，“颜色每年都在变大”不成立。", "身高": "语义：购物没有身高，与语境不符。"}, "sentence_index": 6, "correct_answer": "规模"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这件衣服的规模很好，穿了三年都没坏。", "explanation": "这里应该用〈质量〉。“规模”指范围、大小或数量，不指东西的好坏，说质量要用“质量”。"}, {"text": "这所学校的规模很严格，学生不能迟到。", "explanation": "这里应该用〈管理〉。“规模”不指管得严不严，说管理要用“管理”。"}, {"text": "这个小孩的规模很可爱，大家都喜欢他。", "explanation": "这里应该用〈样子〉。“规模”指事物的范围大小，不用来形容孩子的样子，说样子可爱要用“样子”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c645df3b-621c-4776-bd13-68de8b7dea98') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87212, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个园区的一只规模很大。", "corrected_sentence": "这个园区的规模很大。", "error_description": "“规模”前不能用“一只”，“只”用于动物。这里不需要量词，应直接说“这个园区的规模很大”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c645df3b-621c-4776-bd13-68de8b7dea98') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87212, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "学校的规模扩了大一倍。", "corrected_sentence": "学校的规模扩大了一倍。", "error_description": "“扩大”是动补结构，“了”应放在“扩大”之后，不能插在“扩”和“大”之间。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c645df3b-621c-4776-bd13-68de8b7dea98') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
