INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87213, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "当月是说话的这个月，或者是一件事发生的那个月。", "primary_collocate": null, "pronunciation": "dāng yuè", "ipa": "taŋ˥ ɥe˥˩", "syllable_count": 2, "sentences": [{"text": "当月的电费已经交了。", "target_word": "当月", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司当月就把钱发给了我。", "target_word": "当月", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "当月的天气很冷，常常下雪。", "target_word": "当月", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他三月来北京，当月就找到了工作。", "target_word": "当月", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "当月的书费要在月底前交。", "target_word": "当月", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们当月的任务是卖一百台电脑。", "target_word": "当月", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她十月结婚，当月就搬了新家。", "target_word": "当月", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "当月的会议在十五号开。", "target_word": "当月", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店当月的客人比上月多。", "target_word": "当月", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把当月的表格交给老师。", "target_word": "当月", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "當月", "label": "繁体"}], "register": "书面", "sense_fingerprint": "当月：说话的这个月，或事情发生的那个月", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '46f86a8e-c93b-4cfe-95df-f413bcbe6177') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87213, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "当月", "is_correct": true, "explanation": "当月指这个月，与「已经交了」的完成义相符。"}, {"text": "明天", "is_correct": false, "explanation": "语义：明天还没到，电费不可能已经交了。"}, {"text": "下个月", "is_correct": false, "explanation": "体貌：「已经……了」表示动作已完成，下个月尚未到来，不能与之搭配。"}, {"text": "下周", "is_correct": false, "explanation": "语义：下周还没到，电费不可能已经交了。"}], "explanations": {"当月": "当月指这个月，与「已经交了」的完成义相符。", "明天": "语义：明天还没到，电费不可能已经交了。", "下个月": "体貌：「已经……了」表示动作已完成，下个月尚未到来，不能与之搭配。", "下周": "语义：下周还没到，电费不可能已经交了。"}, "sentence_index": 0, "correct_answer": "当月"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "当月，我正在吃饭。", "explanation": "这里应该用〈当时〉。当月指一个月份，不能表示一个时间点；说正在进行的动作要用当时。"}, {"text": "她当月下午就出发了。", "explanation": "这里应该用〈当天〉。当月指整个月份，不能与下午这样一天之内的时段连用。"}, {"text": "当月七点我要出门。", "explanation": "这里应该用〈今天〉。当月指一个月，不能直接与几点这样的钟点连用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '491bcf82-a5b3-404e-b5b2-c49d94b80e18') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87213, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "当月", "is_correct": true, "explanation": "当月指事情发生的那个月，与结婚后很快搬家的时间相符。"}, {"text": "明年", "is_correct": false, "explanation": "语义：明年还没到，不能与「就搬了」的已完成动作同时出现。"}, {"text": "后天", "is_correct": false, "explanation": "体貌：「就搬了」表示已完成，后天尚未到来，不能与「了」搭配。"}, {"text": "去年", "is_correct": false, "explanation": "语义：去年早于十月结婚，与「结婚后很快搬家」的先后顺序相反。"}], "explanations": {"当月": "当月指事情发生的那个月，与结婚后很快搬家的时间相符。", "明年": "语义：明年还没到，不能与「就搬了」的已完成动作同时出现。", "后天": "体貌：「就搬了」表示已完成，后天尚未到来，不能与「了」搭配。", "去年": "语义：去年早于十月结婚，与「结婚后很快搬家」的先后顺序相反。"}, "sentence_index": 6, "correct_answer": "当月"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他当月在北京工作了五年。", "explanation": "这里应该用〈当年〉。当月指一个月，不能与五年这样的时长连用；说那一年要用当年。"}, {"text": "这顿晚饭当月就做好了。", "explanation": "这里应该用〈当晚〉。当月指整个月，不能修饰一顿晚饭这样的单次活动；说当天晚上做好要用当晚。"}, {"text": "他当月的眼睛是蓝色的。", "explanation": "这里应该用〈一直〉。当月指一个月份，不能描述眼睛颜色这样长期不变的特征。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '491bcf82-a5b3-404e-b5b2-c49d94b80e18') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87213, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "一个当月的水费还没交。", "corrected_sentence": "当月的水费还没交。", "error_description": "错误形式是「一个当月」，正确形式是「当月」。「当月」是时间词，前面不能加「一个」这样的数量短语，应直接说「当月的水费」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '491bcf82-a5b3-404e-b5b2-c49d94b80e18') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87213, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他三月毕业，当月了就结婚了。", "corrected_sentence": "他三月毕业，当月就结婚了。", "error_description": "错误形式是「当月了就结婚了」，正确形式是「当月就结婚了」。「当月」是时间词，后面不能直接加「了」，「了」只能放在动词「结婚」之后。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '491bcf82-a5b3-404e-b5b2-c49d94b80e18') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
