INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87219, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "船是在水上走的东西，人和东西可以坐在上面。", "primary_collocate": null, "pronunciation": "chuán", "ipa": "ʈʂʰwan˧˥", "syllable_count": 1, "sentences": [{"text": "河里有一条船，船上有两个人。", "target_word": "船", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们坐船去对面的小岛。", "target_word": "船", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "船在水上慢慢地走。", "target_word": "船", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "孩子们都想坐在船上玩。", "target_word": "船", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "爸爸在河边等船，天已经黑了。", "target_word": "船", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这条船很小，只能坐四个人。", "target_word": "船", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "船上有很多水果，也有一些大箱子。", "target_word": "船", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他坐在船里，看着河水慢慢流过。", "target_word": "船", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "风很大，船走得很慢。", "target_word": "船", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我把行李放在船上，然后自己也上了船。", "target_word": "船", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一条船", "label": "量词"}, {"form": "一艘船", "label": "量词"}, {"form": "帆船", "label": "复合词"}, {"form": "渔船", "label": "复合词"}], "register": "中性", "sense_fingerprint": "在水上走、可以载人和东西的东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ae3816d5-8403-4a97-960f-1b509de16fef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87219, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "船", "is_correct": true, "explanation": "正确答案：船（chuán，第二声），指在水上走、可以载人和东西的东西。"}, {"text": "穿", "is_correct": false, "explanation": "穿（chuān，第一声）与船（chuán，第二声）声调不同，意思是穿衣服。"}, {"text": "串", "is_correct": false, "explanation": "串（chuàn，第四声）与船（chuán，第二声）声调不同，意思是串起来。"}, {"text": "喘", "is_correct": false, "explanation": "喘（chuǎn，第三声）与船（chuán，第二声）声调不同，意思是喘气。"}, {"text": "床", "is_correct": false, "explanation": "床（chuáng）的韵尾是 ng，与船（chuán）的韵尾 n 不同，意思是床。"}], "explanations": {"船": "正确答案：船（chuán，第二声），指在水上走、可以载人和东西的东西。", "穿": "穿（chuān，第一声）与船（chuán，第二声）声调不同，意思是穿衣服。", "串": "串（chuàn，第四声）与船（chuán，第二声）声调不同，意思是串起来。", "喘": "喘（chuǎn，第三声）与船（chuán，第二声）声调不同，意思是喘气。", "床": "床（chuáng）的韵尾是 ng，与船（chuán）的韵尾 n 不同，意思是床。"}, "sentence_index": null, "correct_answer": "船"}, "level_3": {"options": [{"text": "船", "is_correct": true, "explanation": "正确答案：河里有一条船，后句“船上有两个人”也指船。"}, {"text": "路", "is_correct": false, "explanation": "语义：路是建在陆地上的，不能说“河里有一条路”。"}, {"text": "街", "is_correct": false, "explanation": "语义：街是陆地上的道路，河里不可能有一条街，与“河里”矛盾。"}, {"text": "房子", "is_correct": false, "explanation": "搭配：量词“条”不用于房子，房子要说“座”或“栋”。"}], "explanations": {"船": "正确答案：河里有一条船，后句“船上有两个人”也指船。", "路": "语义：路是建在陆地上的，不能说“河里有一条路”。", "街": "语义：街是陆地上的道路，河里不可能有一条街，与“河里”矛盾。", "房子": "搭配：量词“条”不用于房子，房子要说“座”或“栋”。"}, "sentence_index": 0, "correct_answer": "船"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "孩子们都想骑船去公园玩。", "explanation": "这里应该用〈车〉。骑用于自行车、摩托车等，船要坐或开，不能说骑船。"}, {"text": "我们家门口的河边停着一棵船。", "explanation": "量词错误：这里应该用〈艘〉。棵用于树木，船不能用棵来数。"}, {"text": "爸爸买了一座船放在院子里。", "explanation": "量词错误：这里应该用〈艘〉。座用于山、桥、楼房等大型固定的东西，船不能用座来数。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'faf84b80-4df6-49a8-97a1-abfb129973e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87219, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "船", "is_correct": true, "explanation": "正确答案：船上可以放很多水果和大箱子，“船上”指船的甲板和船舱。"}, {"text": "眼睛", "is_correct": false, "explanation": "语义：眼睛上不能放很多水果和大箱子。"}, {"text": "天空", "is_correct": false, "explanation": "语义：天空上不会堆着水果和大箱子。"}, {"text": "墙", "is_correct": false, "explanation": "搭配：“墙上”一般不堆放水果和大箱子，这里说不通。"}], "explanations": {"船": "正确答案：船上可以放很多水果和大箱子，“船上”指船的甲板和船舱。", "眼睛": "语义：眼睛上不能放很多水果和大箱子。", "天空": "语义：天空上不会堆着水果和大箱子。", "墙": "搭配：“墙上”一般不堆放水果和大箱子，这里说不通。"}, "sentence_index": 6, "correct_answer": "船"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "牧童骑船放羊。", "explanation": "这里应该用〈马〉。骑用于马、自行车等，船要坐或开，不能说骑船。"}, {"text": "他买了一张船，打算去钓鱼。", "explanation": "量词错误：这里应该用〈艘〉。张用于纸、桌子等平面的东西，船不能用张来数。"}, {"text": "码头上停着一块船。", "explanation": "量词错误：这里应该用〈艘〉。块用于块状的东西，船不能用块来数。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'faf84b80-4df6-49a8-97a1-abfb129973e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87219, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "爸爸带我们坐一辆船去看日出。", "corrected_sentence": "爸爸带我们坐一条船去看日出。", "error_description": "量词错误：船用量词“条”或“艘”，“辆”用于车辆，不能用来数船。错误形式：一辆船；正确形式：一条船。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'faf84b80-4df6-49a8-97a1-abfb129973e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87219, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那座渔船在河边停了三天。", "corrected_sentence": "那艘渔船在河边停了三天。", "error_description": "量词错误：船用量词“艘”或“条”，“座”用于山、桥、楼房等大型固定物，不能用来数渔船。错误形式：那座渔船；正确形式：那艘渔船。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'faf84b80-4df6-49a8-97a1-abfb129973e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
