INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87226, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "设法弄到钱财。", "primary_collocate": null, "pronunciation": "gǎo qián", "ipa": "kaʊ˨˩˦ tɕʰjɛn˧˥", "syllable_count": 2, "sentences": [{"text": "公司没钱了，老板正在想办法搞钱。", "target_word": "搞钱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了给妈妈治病，他到处搞钱。", "target_word": "搞钱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他没有工作，不知道怎么搞钱。", "target_word": "搞钱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要搞钱买新电脑，只能多打工。", "target_word": "搞钱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不怕累，只要能搞钱，什么活都做。", "target_word": "搞钱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校需要搞钱修教室，请大家帮忙。", "target_word": "搞钱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟想搞钱去旅行，就开始卖旧书。", "target_word": "搞钱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他卖了旧车，终于搞钱还了债。", "target_word": "搞钱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那家小店为了搞钱，夜里也开门。", "target_word": "搞钱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "搞钱不容易，花钱也要小心。", "target_word": "搞钱", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "设法弄到钱财", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9312b6ee-2f6f-44ac-9f74-0846338cf1b7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87226, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "搞钱", "is_correct": true, "explanation": "正确：“搞钱”是设法弄到钱财，与“公司没钱了，老板正在想办法”相符。"}, {"text": "数钱", "is_correct": false, "explanation": "语义：“数钱”是点数现金，与“公司没钱了”矛盾，不能表示设法弄钱。"}, {"text": "旅游", "is_correct": false, "explanation": "语义：“旅游”与“公司没钱了”的语境矛盾，老板在公司缺钱时不会去“想办法”旅游。"}, {"text": "散步", "is_correct": false, "explanation": "搭配：“想办法”后不接“散步”，句子意思不通。"}], "explanations": {"搞钱": "正确：“搞钱”是设法弄到钱财，与“公司没钱了，老板正在想办法”相符。", "数钱": "语义：“数钱”是点数现金，与“公司没钱了”矛盾，不能表示设法弄钱。", "旅游": "语义：“旅游”与“公司没钱了”的语境矛盾，老板在公司缺钱时不会去“想办法”旅游。", "散步": "搭配：“想办法”后不接“散步”，句子意思不通。"}, "sentence_index": 0, "correct_answer": "搞钱"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他每天早上搞钱洗脸。", "explanation": "这里的“搞”作“做、弄”讲，但“搞钱”只表示设法弄到钱财，不能用来指洗脸这类日常动作。"}, {"text": "他每天晚上搞钱睡觉。", "explanation": "这里的“搞”作“做、弄”讲，但“搞钱”只表示设法弄到钱财，不能用来指睡觉这类休息。"}, {"text": "爸爸在院子里搞钱浇花。", "explanation": "这里的“搞”作“做、弄”讲，但“搞钱”只表示设法弄到钱财，不能用来指浇花这类家务。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '137e41b7-345e-410f-abda-3834f0905653') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87226, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "搞钱", "is_correct": true, "explanation": "正确：“搞钱”是设法弄到钱，与“去旅行，就开始卖旧书”的目的相符。"}, {"text": "退钱", "is_correct": false, "explanation": "语义：“退钱”是把钱还给别人，与“卖旧书”获得钱的做法方向相反。"}, {"text": "赔钱", "is_correct": false, "explanation": "搭配：“想”后一般不接“赔钱”，与“去旅行”的目的也矛盾。"}, {"text": "吃饭", "is_correct": false, "explanation": "语义：“吃饭”与“去旅行，就开始卖旧书”无关，不能表示目的。"}], "explanations": {"搞钱": "正确：“搞钱”是设法弄到钱，与“去旅行，就开始卖旧书”的目的相符。", "退钱": "语义：“退钱”是把钱还给别人，与“卖旧书”获得钱的做法方向相反。", "赔钱": "搭配：“想”后一般不接“赔钱”，与“去旅行”的目的也矛盾。", "吃饭": "语义：“吃饭”与“去旅行，就开始卖旧书”无关，不能表示目的。"}, "sentence_index": 6, "correct_answer": "搞钱"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈在厨房搞钱炖了一锅汤。", "explanation": "这里应该用〈做〉。炖汤是烹饪动作，“搞钱”只表示设法弄到钱财，不能用来指烹饪。"}, {"text": "弟弟在操场上搞钱踢了一场球。", "explanation": "这里应该用〈踢〉。踢球是体育动作，“搞钱”只表示设法弄到钱财，不能用来指体育活动。"}, {"text": "工人在车间搞钱焊了一根管子。", "explanation": "这里应该用〈焊〉。焊管子是金属加工动作，“搞钱”只表示设法弄到钱财，不能用来指焊接。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '137e41b7-345e-410f-abda-3834f0905653') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87226, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他没钱了，只好想办法搞钱的。", "corrected_sentence": "他没钱了，只好想办法搞钱。", "error_description": "句末单独的“的”不能收尾此句（不同于“搞钱的人”这样的名词短语）；应去掉“的”，说“他没钱了，只好想办法搞钱。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '137e41b7-345e-410f-abda-3834f0905653') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87226, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他正在去外地搞过钱，还没回来。", "corrected_sentence": "他正在去外地搞钱，还没回来。", "error_description": "错误：“正在”表示动作进行，与表示经历的“过”矛盾；“搞钱”中间不能插入“过”。应去掉“过”，说“他正在去外地搞钱，还没回来。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '137e41b7-345e-410f-abda-3834f0905653') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
