INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87228, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "向有关的人或机构询问，以便得到意见或解答。", "primary_collocate": null, "pronunciation": "zī xún", "ipa": "tsɨ˥ ɕyn˧˥", "syllable_count": 2, "sentences": [{"text": "我打电话咨询了银行的工作人员。", "target_word": "咨询", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "想出国留学，可以去留学中心咨询。", "target_word": "咨询", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他去医院咨询了关于体检的事。", "target_word": "咨询", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你可以拨打这个电话咨询。", "target_word": "咨询", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "办签证以前，我先咨询了大使馆。", "target_word": "咨询", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "家长到学校咨询报名的时间。", "target_word": "咨询", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想买保险，就去公司咨询了价格。", "target_word": "咨询", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请问去哪儿咨询租房的事情？", "target_word": "咨询", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在网上咨询了一家旅行社。", "target_word": "咨询", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她给图书馆打电话，咨询开门时间。", "target_word": "咨询", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "咨询了", "label": "体标"}, {"form": "咨询过", "label": "体标"}, {"form": "咨询咨询", "label": "重叠"}, {"form": "咨询电话", "label": "复合"}, {"form": "諮詢", "label": "繁体"}], "register": "中性", "sense_fingerprint": "向有关机构或人员询问情况，以得到意见或解答", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7777e7df-230e-4f7a-be5d-05cc2cb71220') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87228, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "拜访", "is_correct": false, "explanation": "语义：拜访要当面去，与“打电话”的方式矛盾。"}, {"text": "咨询", "is_correct": true, "explanation": "咨询：通过电话向银行人员询问，与“打电话”相符。"}, {"text": "接待", "is_correct": false, "explanation": "语义：接待是主人一方的行为，我打电话去问，不能说接待了工作人员。"}, {"text": "招待", "is_correct": false, "explanation": "搭配：“招待”指当面款待客人，与“打电话”不搭配。"}], "explanations": {"拜访": "语义：拜访要当面去，与“打电话”的方式矛盾。", "咨询": "咨询：通过电话向银行人员询问，与“打电话”相符。", "接待": "语义：接待是主人一方的行为，我打电话去问，不能说接待了工作人员。", "招待": "搭配：“招待”指当面款待客人，与“打电话”不搭配。"}, "sentence_index": 0, "correct_answer": "咨询"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他向朋友咨询了一封信。", "explanation": "这里应该用〈寄〉。咨询是向人询问以得到解答，邮寄信件要用寄。"}, {"text": "我帮老师咨询了黑板。", "explanation": "这里应该用〈擦〉。咨询是向人询问以得到解答，擦拭黑板要用擦。"}, {"text": "她在音乐会上咨询了一首曲子。", "explanation": "这里应该用〈演奏〉。咨询是向人询问以得到解答，演奏曲子要用演奏。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '15864d4b-d276-4b70-a8ee-d59a3a4261a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87228, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "咨询", "is_correct": true, "explanation": "咨询：向公司询问价格，符合想买保险的语境。"}, {"text": "收取", "is_correct": false, "explanation": "语义：我去公司是为了买保险，收取价格的应是公司，不能用于我。"}, {"text": "修改", "is_correct": false, "explanation": "语义：价格由公司制定，我作为顾客去公司，不能说修改了价格。"}, {"text": "发布", "is_correct": false, "explanation": "语义：价格由公司发布，我作为买家去公司不能说发布了价格。"}], "explanations": {"咨询": "咨询：向公司询问价格，符合想买保险的语境。", "收取": "语义：我去公司是为了买保险，收取价格的应是公司，不能用于我。", "修改": "语义：价格由公司制定，我作为顾客去公司，不能说修改了价格。", "发布": "语义：价格由公司发布，我作为买家去公司不能说发布了价格。"}, "sentence_index": 6, "correct_answer": "咨询"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "学校咨询了全体家长放假的消息。", "explanation": "这里应该用〈通知〉。咨询是向人询问以得到解答，告知家长放假消息应用通知。"}, {"text": "工人咨询了空调。", "explanation": "这里应该用〈修理〉。咨询是向人询问以得到解答，修理坏了的空调要用修理。"}, {"text": "厨师咨询了一条鱼。", "explanation": "这里应该用〈烧〉。咨询是向人询问以得到解答，烹饪菜肴要用烧。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '15864d4b-d276-4b70-a8ee-d59a3a4261a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87228, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "你可以打电话把快递客服咨询。", "corrected_sentence": "你可以打电话向快递客服咨询。", "error_description": "错误在介词：咨询的对象应由“向”引出，不能用“把”把对象直接提到动词前。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '15864d4b-d276-4b70-a8ee-d59a3a4261a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87228, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她咨询了过图书馆的老师。", "corrected_sentence": "她咨询过图书馆的老师。", "error_description": "错误在“了”和“过”同时出现：“咨询过”表示曾经发生过，不能再加“了”，应去掉“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '15864d4b-d276-4b70-a8ee-d59a3a4261a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
