INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87239, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "第八个届篮球赛下周开始。", "corrected_sentence": "第八届篮球赛下周开始。", "error_description": "错误：“第八个届”；正确：“第八届”。“届”本身就是量词，前面不能再加量词“个”，正确应说“第八届篮球赛”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '137e41b7-345e-410f-abda-3834f0905653') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87239, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "第三位足球赛下个月举行。", "corrected_sentence": "第三届足球赛下个月举行。", "error_description": "量词错误：“位”只用于人，不能计数比赛；应改用计数定期比赛届次的“届”，说“第三届足球赛下个月举行。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '137e41b7-345e-410f-abda-3834f0905653') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
