INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87262, 1, 'prompt1_core', '{"pos": "连词", "semantic_class": "function", "definition": "连词，表示在上面所说的以外，还有其他。", "primary_collocate": null, "pronunciation": "cǐ wài", "ipa": "tsʰɨ˨˩ wai˥˩", "syllable_count": 2, "sentences": [{"text": "我会说汉语，此外还会说一点儿日语。", "target_word": "此外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司给我们午饭，此外每月还有奖金。", "target_word": "此外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他喜欢踢球，此外也喜欢游泳。", "target_word": "此外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个周末我要洗衣服，此外还要打扫房间。", "target_word": "此外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "桌上有一本书和一支笔，此外还有一把尺子。", "target_word": "此外", "complexity_tier": "T3", "furigana": "zhuō shàng yǒu yì běn shū hé yì zhī bǐ, cǐ wài hái yǒu yì bǎ chǐzi.", "sentence_source": "generated"}, {"text": "学校有图书馆和体育馆，此外还有一个花园。", "target_word": "此外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每天工作八个小时，此外还要照顾孩子。", "target_word": "此外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我只带了手机和钱包，此外还带了一把伞。", "target_word": "此外", "complexity_tier": "T3", "furigana": "wǒ zhǐ dài le shǒujī hé qiánbāo, cǐ wài hái dài le yì bǎ sǎn.", "sentence_source": "generated"}, {"text": "这家饭店有中餐，此外也有西餐。", "target_word": "此外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师教我们说话，此外还教我们写字。", "target_word": "此外", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "连词：列举之后补充，除上述之外还有", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8b2c5003-937d-4490-b759-8fcdbf134d37') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87262, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "此外", "is_correct": true, "explanation": "正确：“此外”表示在“会说汉语”之外还有补充，与后半句“还会说一点儿日语”相呼应。"}, {"text": "所以", "is_correct": false, "explanation": "语义：“所以”表示因果，但会说汉语和会说日语之间并无因果关系。"}, {"text": "然而", "is_correct": false, "explanation": "语域：“然而”偏书面，且前后并无转折关系，与口语化的并列补充不符。"}, {"text": "不过", "is_correct": false, "explanation": "语义：“不过”表示转折，而这句前后是并列补充，并没有对比。"}], "explanations": {"此外": "正确：“此外”表示在“会说汉语”之外还有补充，与后半句“还会说一点儿日语”相呼应。", "所以": "语义：“所以”表示因果，但会说汉语和会说日语之间并无因果关系。", "然而": "语域：“然而”偏书面，且前后并无转折关系，与口语化的并列补充不符。", "不过": "语义：“不过”表示转折，而这句前后是并列补充，并没有对比。"}, "sentence_index": 0, "correct_answer": "此外"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我先写作业，此外看电视。", "explanation": "这里应该用〈然后〉。此外表示在所说之外另有补充，不表示动作的先后顺序。"}, {"text": "我很想去，此外没有时间。", "explanation": "这里应该用〈但是〉。此外只用于补充同类内容，不表示转折。"}, {"text": "他生病了，此外没来上课。", "explanation": "这里应该用〈因此〉。此外不表示因果关系，“生病”与“没来上课”之间的因果要用〈因此〉来连接。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '415aa2a1-1bc1-4dae-858f-381cc84b3069') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87262, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "此外", "is_correct": true, "explanation": "正确：“此外”表示在工作之外还要照顾孩子，是补充的意思，与“还要”相呼应。"}, {"text": "而是", "is_correct": false, "explanation": "搭配：“而是”需要与前文的“不是”呼应，此处前文没有否定，搭配不成立。"}, {"text": "故而", "is_correct": false, "explanation": "语域：“故而”偏文言，且“工作八个小时”与“照顾孩子”之间并非因果关系。"}, {"text": "否则", "is_correct": false, "explanation": "语义：“否则”表示另一种选择的后果，与“工作之外还要照顾孩子”的补充意思不符。"}], "explanations": {"此外": "正确：“此外”表示在工作之外还要照顾孩子，是补充的意思，与“还要”相呼应。", "而是": "搭配：“而是”需要与前文的“不是”呼应，此处前文没有否定，搭配不成立。", "故而": "语域：“故而”偏文言，且“工作八个小时”与“照顾孩子”之间并非因果关系。", "否则": "语义：“否则”表示另一种选择的后果，与“工作之外还要照顾孩子”的补充意思不符。"}, "sentence_index": 6, "correct_answer": "此外"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他听到消息，此外马上出发了。", "explanation": "这里应该用〈于是〉。此外只表示补充，不表示承接前面的事件、引出结果。"}, {"text": "他没带伞，此外淋湿了。", "explanation": "这里应该用〈所以〉。此外只表示补充，不表示因果；“没带伞”与“淋湿了”之间的因果要用〈所以〉连接。"}, {"text": "他很努力，此外没有成功。", "explanation": "这里应该用〈却〉。此外不表示转折，“努力”与“没有成功”之间的对立要用〈却〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '415aa2a1-1bc1-4dae-858f-381cc84b3069') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87262, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "周末我去看了电影，此外却去逛了书店。", "corrected_sentence": "周末我去看了电影，此外还去逛了书店。", "error_description": "错误：“此外却去逛了书店”。正确：“此外还去逛了书店”。“却”表示转折，与“此外”表示补充相矛盾，补充要用“还”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '415aa2a1-1bc1-4dae-858f-381cc84b3069') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87262, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他每天骑车上班，在此外还锻炼身体。", "corrected_sentence": "他每天骑车上班，此外还锻炼身体。", "error_description": "错误在于多加了介词“在”：“此外”是连词，前面不能加“在”，应说“此外还……”。“在此外”是把“在……之外”的说法套用到了连词上。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '415aa2a1-1bc1-4dae-858f-381cc84b3069') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
