INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87267, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "绝对是一点儿也不会错，一定是这样。", "primary_collocate": null, "pronunciation": "jué duì", "ipa": "tɕɥe˧˥ tuei˥˩", "syllable_count": 2, "sentences": [{"text": "这个答案绝对是对的。", "target_word": "绝对", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看他的样子，绝对是生病了。", "target_word": "绝对", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个声音绝对是我妈妈的。", "target_word": "绝对", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天绝对会下雨，你带伞吧。", "target_word": "绝对", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家的菜绝对好吃，我吃过很多次。", "target_word": "绝对", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她绝对是最好的人选。", "target_word": "绝对", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这绝对是真的，我亲眼看见了。", "target_word": "绝对", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "明天他绝对会来，他已经答应了。", "target_word": "绝对", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个办法绝对有用。", "target_word": "绝对", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听这个口音，他绝对是北京人。", "target_word": "绝对", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "絕對", "label": "繁体"}], "register": "中性", "sense_fingerprint": "副词：十分肯定，判断一定不会错", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8b2c5003-937d-4490-b759-8fcdbf134d37') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87267, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "绝对", "is_correct": true, "explanation": "正确：“绝对”表示十分肯定、一定不会错，修饰判断词“是”，与“是对的”相符。"}, {"text": "立刻", "is_correct": false, "explanation": "语义：“立刻”表示马上发生，与对答案正误的判断无关，句意不通。"}, {"text": "比较", "is_correct": false, "explanation": "搭配：“比较”表示相对程度，不能用在判断句“是……的”前。"}, {"text": "太", "is_correct": false, "explanation": "搭配：“太”修饰形容词或动词，不修饰判断词“是”。"}], "explanations": {"绝对": "正确：“绝对”表示十分肯定、一定不会错，修饰判断词“是”，与“是对的”相符。", "立刻": "语义：“立刻”表示马上发生，与对答案正误的判断无关，句意不通。", "比较": "搭配：“比较”表示相对程度，不能用在判断句“是……的”前。", "太": "搭配：“太”修饰形容词或动词，不修饰判断词“是”。"}, "sentence_index": 0, "correct_answer": "绝对"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他绝对或许会来，你们先等等。", "explanation": "这里应该用〈可能〉。〈绝对〉表示十分肯定，不能与表示推测的副词同用；表示推测时要用〈可能〉。"}, {"text": "这个答案绝对不一定是对的。", "explanation": "这里应该用〈未必〉。〈绝对〉表示完全肯定，与“不一定”的不确定相矛盾；表示不确定时要用〈未必〉。"}, {"text": "我绝对不太清楚这件事，你问问别人吧。", "explanation": "这里应该用〈大概〉。〈绝对〉表示十分肯定，与“不太清楚”所表示的不确定相矛盾；表示不确定时要用〈大概〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '415aa2a1-1bc1-4dae-858f-381cc84b3069') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87267, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "绝对", "is_correct": true, "explanation": "正确：“绝对”表示一点儿也不会错，与“我亲眼看见了”的依据相呼应。"}, {"text": "不见得", "is_correct": false, "explanation": "语义：“不见得”表示不一定，与“我亲眼看见了”的确定语气相矛盾。"}, {"text": "非常", "is_correct": false, "explanation": "搭配：“非常”是程度副词，不能修饰判断词“是”。"}, {"text": "特意", "is_correct": false, "explanation": "语义：“特意”表示有意为之，与对事实的判断不搭。"}], "explanations": {"绝对": "正确：“绝对”表示一点儿也不会错，与“我亲眼看见了”的依据相呼应。", "不见得": "语义：“不见得”表示不一定，与“我亲眼看见了”的确定语气相矛盾。", "非常": "搭配：“非常”是程度副词，不能修饰判断词“是”。", "特意": "语义：“特意”表示有意为之，与对事实的判断不搭。"}, "sentence_index": 6, "correct_answer": "绝对"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个班的纪律绝对不能违反，但是可以偶尔违反。", "explanation": "这里应该用〈通常〉。〈绝对〉表示毫无例外，与“可以偶尔违反”的例外相矛盾；表示大多数情况要用〈通常〉。"}, {"text": "这只猫绝对有时很乖，有时很调皮。", "explanation": "这里应该用〈可能〉。〈绝对〉表示十分肯定，不能用于“有时……有时……”这种不确定的描述；描述不确定时要用〈可能〉。"}, {"text": "他绝对大概是北京人，我不太确定。", "explanation": "这里应该用〈或许〉。〈绝对〉表示十分肯定，与“大概”的推测相矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '415aa2a1-1bc1-4dae-858f-381cc84b3069') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87267, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "今天晚上很绝对会有雨。", "corrected_sentence": "今天晚上绝对会有雨。", "error_description": "错误：“很绝对”。正确：“绝对”。“绝对”是副词，表示十分肯定，不能再被程度副词“很”修饰；应说“今天晚上绝对会有雨”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '415aa2a1-1bc1-4dae-858f-381cc84b3069') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87267, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这件事绝对的是假的，别信。", "corrected_sentence": "这件事绝对是假的，别信。", "error_description": "错误在于多加了“的”：“绝对”是副词，修饰判断词“是”，不能加“的”变成“绝对的”。应说“绝对是假的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '415aa2a1-1bc1-4dae-858f-381cc84b3069') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87268, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '415aa2a1-1bc1-4dae-858f-381cc84b3069') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87268, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '415aa2a1-1bc1-4dae-858f-381cc84b3069') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87268, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "副词，表示完全，一定；毫无例外。", "primary_collocate": null, "pronunciation": "jué duì", "ipa": "tɕɥe˧˥ tuei˥˩", "syllable_count": 2, "sentences": [{"text": "这件事绝对不能告诉别人。", "target_word": "绝对", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他说的话绝对可靠。", "target_word": "绝对", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这样做绝对没有问题。", "target_word": "绝对", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我绝对不会忘记你。", "target_word": "绝对", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这里的水绝对干净，你可以放心喝。", "target_word": "绝对", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子绝对不能一个人过马路。", "target_word": "绝对", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "考试时绝对不可以看手机。", "target_word": "绝对", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这是绝对安全的办法。", "target_word": "绝对", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你绝对不要骑车太快。", "target_word": "绝对", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个人绝对值得相信。", "target_word": "绝对", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "絕對", "label": "繁体"}], "register": "中性", "sense_fingerprint": "副词：完全，毫无例外，常用于否定或强调", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8b2c5003-937d-4490-b759-8fcdbf134d37') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87268, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "绝对", "is_correct": true, "explanation": "正确：“绝对”表示毫无例外，与否定词“不能”搭配，强调禁止。"}, {"text": "偶尔", "is_correct": false, "explanation": "语义：“偶尔”表示有时，与“毫无例外”的“绝对不能”相矛盾。"}, {"text": "比较", "is_correct": false, "explanation": "搭配：“比较”表示相对程度，不能修饰“不能”这类绝对的否定。"}, {"text": "刚刚", "is_correct": false, "explanation": "语义：“刚刚”表示时间上刚发生，与“一律不能告诉别人”的意思不符。"}], "explanations": {"绝对": "正确：“绝对”表示毫无例外，与否定词“不能”搭配，强调禁止。", "偶尔": "语义：“偶尔”表示有时，与“毫无例外”的“绝对不能”相矛盾。", "比较": "搭配：“比较”表示相对程度，不能修饰“不能”这类绝对的否定。", "刚刚": "语义：“刚刚”表示时间上刚发生，与“一律不能告诉别人”的意思不符。"}, "sentence_index": 0, "correct_answer": "绝对"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这件事绝对不一定能成功。", "explanation": "这里应该用〈未必〉。〈绝对〉表示完全肯定，不能与“不一定”的不确定相矛盾；表示不确定时要用〈未必〉。"}, {"text": "我每天绝对早起，只有生病的时候例外。", "explanation": "这里应该用〈通常〉。〈绝对〉表示毫无例外，与“只有生病的时候例外”矛盾；表示大多数情况时要用〈通常〉。"}, {"text": "我绝对不太确定他会不会来，你再问问别人吧。", "explanation": "这里应该用〈大概〉。〈绝对〉表示十分肯定，与“不太确定”的不肯定相矛盾；表示不确定时要用〈大概〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '415aa2a1-1bc1-4dae-858f-381cc84b3069') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87268, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "绝对", "is_correct": true, "explanation": "正确：“绝对”表示毫无例外，与“不可以”搭配，强调考试期间一律禁止看手机。"}, {"text": "差点儿", "is_correct": false, "explanation": "语义：“差点儿”表示几乎要发生，与“绝对不可以”的禁令语气不符。"}, {"text": "太", "is_correct": false, "explanation": "搭配：“太”表示程度过高，不能修饰“不可以”这类禁止性的能愿词。"}, {"text": "恰好", "is_correct": false, "explanation": "语义：“恰好”表示碰巧，与“考试时一律禁止看手机”的规定无关。"}], "explanations": {"绝对": "正确：“绝对”表示毫无例外，与“不可以”搭配，强调考试期间一律禁止看手机。", "差点儿": "语义：“差点儿”表示几乎要发生，与“绝对不可以”的禁令语气不符。", "太": "搭配：“太”表示程度过高，不能修饰“不可以”这类禁止性的能愿词。", "恰好": "语义：“恰好”表示碰巧，与“考试时一律禁止看手机”的规定无关。"}, "sentence_index": 6, "correct_answer": "绝对"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这件事我绝对不确定，或许对，或许不对。", "explanation": "这里应该用〈大概〉。〈绝对〉表示十分肯定，与“不确定，或许对，或许不对”相矛盾；表示不确定时要用〈大概〉。"}, {"text": "我绝对也许会来参加聚会。", "explanation": "这里应该用〈或许〉。〈绝对〉表示确定无疑，不能与表示不确定的副词同用；表示不确定时要用〈或许〉。"}, {"text": "他绝对有时会迟到。", "explanation": "这里应该用〈经常〉。〈绝对〉表示毫无例外或十分肯定，不能描述“有时”这样偶尔的情况；表示经常要用〈经常〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '415aa2a1-1bc1-4dae-858f-381cc84b3069') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87268, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这份报告绝对的不能外传。", "corrected_sentence": "这份报告绝对不能外传。", "error_description": "错误在于多加了“的”：“绝对”是副词，修饰“不能”，不能加“的”变成“绝对的”，那是形容词，不能修饰动词性短语。应说“绝对不能外传”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '415aa2a1-1bc1-4dae-858f-381cc84b3069') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87268, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这件事我们绝对的不会放弃。", "corrected_sentence": "这件事我们绝对不会放弃。", "error_description": "错误在于多加了“的”：“绝对”是副词，直接修饰“不会放弃”，不能加“的”变成形容词，形容词不能修饰动词性短语。应说“绝对不会放弃”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '415aa2a1-1bc1-4dae-858f-381cc84b3069') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
