INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87280, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f7eb847-1aab-4ef5-b74e-82cc2264e120') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87280, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "向某人表示感谢，后常带受谢者作宾语。", "primary_collocate": null, "pronunciation": "xiè xie", "ipa": "ɕje˥˩ ɕje", "syllable_count": 2, "sentences": [{"text": "我想谢谢你的帮助。", "target_word": "谢谢", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "谢谢你送我的花。", "target_word": "谢谢", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我要好好谢谢那位医生。", "target_word": "谢谢", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他帮了我很多，我想谢谢他。", "target_word": "谢谢", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "谢谢大家今天来参加我的生日会。", "target_word": "谢谢", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我打电话谢谢她，因为她借给我伞。", "target_word": "谢谢", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "谢谢你一直照顾着我的小狗。", "target_word": "谢谢", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "要不是你，我早就迟到了，谢谢你！", "target_word": "谢谢", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请替我谢谢你的妈妈，饭很好吃。", "target_word": "谢谢", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他向每一位客人鞠躬，谢谢他们。", "target_word": "谢谢", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "謝謝", "label": "繁体"}], "register": "口语", "sense_fingerprint": "向某人表示感谢，后面常带对象", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '965e8b9c-2139-44a0-a62f-27461e03fcbe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87280, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "谢谢", "is_correct": true, "explanation": "正确：“谢谢”向人表示感谢，与“你的帮助”搭配。"}, {"text": "收拾", "is_correct": false, "explanation": "搭配：“收拾”用于房间、东西，不接“帮助”。"}, {"text": "打扫", "is_correct": false, "explanation": "搭配：“打扫”是清理场所，不能打扫“帮助”。"}, {"text": "讨厌", "is_correct": false, "explanation": "语义：“讨厌”表示反感，与“我想”表达的感激心情不符。"}], "explanations": {"谢谢": "正确：“谢谢”向人表示感谢，与“你的帮助”搭配。", "收拾": "搭配：“收拾”用于房间、东西，不接“帮助”。", "打扫": "搭配：“打扫”是清理场所，不能打扫“帮助”。", "讨厌": "语义：“讨厌”表示反感，与“我想”表达的感激心情不符。"}, "sentence_index": 0, "correct_answer": "谢谢"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我不小心弄坏了他的书，我想谢谢他。", "explanation": "这里应该用〈道歉〉。弄坏别人的东西要向人道歉，“谢谢”表示感激，不能用来表示歉意。"}, {"text": "我一进门就吵醒了他，我连声说谢谢。", "explanation": "这里应该用〈抱歉〉。吵醒别人要表示歉意，“谢谢”表示感激，不能用来道歉。"}, {"text": "孩子考试没考好，妈妈却谢谢他。", "explanation": "这里应该用〈鼓励〉。孩子考试失利要鼓励，“谢谢”表示感激，不能替代鼓励。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f7eb847-1aab-4ef5-b74e-82cc2264e120') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87280, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "谢谢", "is_correct": true, "explanation": "正确：“谢谢”向人表示感谢，与“一直照顾”的语境吻合。"}, {"text": "责怪", "is_correct": false, "explanation": "语义：“责怪”是怪罪，与感激的语境相反。"}, {"text": "嫌弃", "is_correct": false, "explanation": "语义：“嫌弃”表示厌烦，与“一直照顾”的感激语境相反。"}, {"text": "驱赶", "is_correct": false, "explanation": "搭配：“驱赶”是赶走，与“一直照顾”这类动作不搭配。"}], "explanations": {"谢谢": "正确：“谢谢”向人表示感谢，与“一直照顾”的语境吻合。", "责怪": "语义：“责怪”是怪罪，与感激的语境相反。", "嫌弃": "语义：“嫌弃”表示厌烦，与“一直照顾”的感激语境相反。", "驱赶": "搭配：“驱赶”是赶走，与“一直照顾”这类动作不搭配。"}, "sentence_index": 6, "correct_answer": "谢谢"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的女儿刚考上名校，我想谢谢他。", "explanation": "这里应该用〈恭喜〉。对方家人取得好成绩要道贺，“谢谢”是感谢用语，不能替代道贺。"}, {"text": "他把我的饭洒了一地，我却对他说了声谢谢。", "explanation": "这里应该用〈埋怨〉。对别人的过失要说“埋怨”，“谢谢”表示感激，不能用来抱怨。"}, {"text": "他谢谢我们一路平安。", "explanation": "这里应该用〈祝福〉。祝对方平安要用“祝福”，“谢谢”不能表示祝愿。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f7eb847-1aab-4ef5-b74e-82cc2264e120') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87280, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我想谢谢了你的礼物。", "corrected_sentence": "我想谢谢你的礼物。", "error_description": "“谢谢”是重叠式动词，其间不能插“了”再带宾语：应说“想谢谢你的礼物”，不说“想谢谢了你的礼物”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f7eb847-1aab-4ef5-b74e-82cc2264e120') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87280, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们连声谢谢了他。", "corrected_sentence": "我们连声谢谢他。", "error_description": "“谢谢”是重叠式动词，其间不能插“了”再带宾语：应说“连声谢谢他”，不说“连声谢谢了他”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f7eb847-1aab-4ef5-b74e-82cc2264e120') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
