INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87291, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "党员是参加了某一个党的人。", "primary_collocate": null, "pronunciation": "dǎng yuán", "ipa": "taŋ˨˩˦ ɥɛn˧˥", "syllable_count": 2, "sentences": [{"text": "爷爷当了四十年党员。", "target_word": "党员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你是不是党员？", "target_word": "党员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们班有三位党员。", "target_word": "党员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "开会时，党员先发言。", "target_word": "党员", "complexity_tier": "T3", "furigana": "kāi huì shí, dǎng yuán xiān fā yán。", "sentence_source": "generated"}, {"text": "他是党员，也是我的老师。", "target_word": "党员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她入党以后，就是党员了。", "target_word": "党员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医院里的党员都来帮忙了。", "target_word": "党员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "明天下午，所有党员都要开会。", "target_word": "党员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小王刚成为党员，很高兴。", "target_word": "党员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "村里的党员带着大家种树。", "target_word": "党员", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "名", "label": "量词"}, {"form": "位", "label": "量词"}, {"form": "共产党员", "label": "复合"}, {"form": "预备党员", "label": "复合"}, {"form": "黨員", "label": "繁体"}], "register": "中性", "sense_fingerprint": "名词；参加了某个党的人；可作“是”的宾语或“当”的宾语", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'caabb7e0-2a3a-4f9f-b03d-4a7815969b51') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87291, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "孩子", "is_correct": false, "explanation": "语义：爷爷是老人，不能“当了四十年”孩子，与句意矛盾。"}, {"text": "党费", "is_correct": false, "explanation": "搭配：“当”后接身份名词，“党费”不是身份，不能说“当了四十年党费”。"}, {"text": "党员", "is_correct": true, "explanation": "正确：“当了四十年”后接身份名词“党员”，符合句意。"}, {"text": "党校", "is_correct": false, "explanation": "语义：“党校”是机构，不能“当了四十年”，与人的身份不符。"}], "explanations": {"孩子": "语义：爷爷是老人，不能“当了四十年”孩子，与句意矛盾。", "党费": "搭配：“当”后接身份名词，“党费”不是身份，不能说“当了四十年党费”。", "党员": "正确：“当了四十年”后接身份名词“党员”，符合句意。", "党校": "语义：“党校”是机构，不能“当了四十年”，与人的身份不符。"}, "sentence_index": 0, "correct_answer": "党员"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他是这所驾校的党员。", "explanation": "这里应该用〈学员〉。党员指加入政党的人，驾校的受训人员应说学员。"}, {"text": "他十五岁就成了党员。", "explanation": "这里应该用〈团员〉。党员指加入政党的人；十五岁入的是共青团，应说团员。"}, {"text": "他是那帮骗子的党员。", "explanation": "这里应该用〈同伙〉或〈同党〉。党员指加入政党的人；一帮骗子里的同伙不能说党员。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b367b12a-8299-455f-a174-4891011d28c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87291, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "病房", "is_correct": false, "explanation": "语义：病房是场所，不能“来帮忙”，句意不通。"}, {"text": "救护车", "is_correct": false, "explanation": "搭配：“来帮忙”的主语须是人，不能说车“来帮忙”。"}, {"text": "党员", "is_correct": true, "explanation": "正确：“都来帮忙”的主语是人，“医院里的党员”符合句意。"}, {"text": "窗户", "is_correct": false, "explanation": "语义：窗户是物件，不会“来帮忙”，与句意矛盾。"}], "explanations": {"病房": "语义：病房是场所，不能“来帮忙”，句意不通。", "救护车": "搭配：“来帮忙”的主语须是人，不能说车“来帮忙”。", "党员": "正确：“都来帮忙”的主语是人，“医院里的党员”符合句意。", "窗户": "语义：窗户是物件，不会“来帮忙”，与句意矛盾。"}, "sentence_index": 6, "correct_answer": "党员"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他是篮球队的党员。", "explanation": "这里应该用〈队员〉。党员指加入政党的人，篮球队的成员应说队员。"}, {"text": "他是这个乐队的党员，每场演出都去。", "explanation": "这里应该用〈乐迷〉。党员指加入政党的人，每场演出都去捧场的人应说乐迷。"}, {"text": "他是这家书店的党员，每天都去看书。", "explanation": "这里应该用〈读者〉。党员指加入政党的人；每天来书店看书的人应说读者。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b367b12a-8299-455f-a174-4891011d28c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87291, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他们工厂有两只党员。", "corrected_sentence": "他们工厂有两位党员。", "error_description": "量词错误：“只”不用于指人，指人的党员应说“两位党员”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b367b12a-8299-455f-a174-4891011d28c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87291, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她党员，也是我的邻居。", "corrected_sentence": "她是党员，也是我的邻居。", "error_description": "判断句遗漏“是”：“她是党员”中“是”不能省略，不能说“她党员”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b367b12a-8299-455f-a174-4891011d28c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
