INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87293, 1, 'prompt1_core', '{"pos": "量词", "semantic_class": "function", "definition": "部是数书、电影这些东西的词。", "primary_collocate": null, "pronunciation": "bù", "ipa": "pu˥˩", "syllable_count": 1, "sentences": [{"text": "我昨天看了一部电影。", "target_word": "部", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这部电影很好看。", "target_word": "部", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他写了一部很长的小说。", "target_word": "部", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "桌子上放着一部词典。", "target_word": "部", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妹妹最喜欢这部动画片。", "target_word": "部", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这部电影我看过三次。", "target_word": "部", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这部小说讲的是一个小男孩的故事。", "target_word": "部", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你看过那部电影吗？", "target_word": "部", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他拍了一部关于家乡的电影。", "target_word": "部", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷有一部老字典，用了很多年。", "target_word": "部", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "用来数书、电影的量词", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '63f4d827-5213-4efb-b0e0-f6115791d1c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generati