INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87293, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "部", "is_correct": true, "explanation": "部 bù（第四声），用于书、电影等作品的量词。"}, {"text": "补", "is_correct": false, "explanation": "bǔ（第三声）与 bù（第四声）声调不同，意思是补充。"}, {"text": "铺", "is_correct": false, "explanation": "pù 与 bù 声母不同（p 与 b），意思是店铺。"}, {"text": "木", "is_correct": false, "explanation": "mù 与 bù 声母不同（m 与 b），意思是木头。"}], "explanations": {"部": "部 bù（第四声），用于书、电影等作品的量词。", "补": "bǔ（第三声）与 bù（第四声）声调不同，意思是补充。", "铺": "pù 与 bù 声母不同（p 与 b），意思是店铺。", "木": "mù 与 bù 声母不同（m 与 b），意思是木头。"}, "sentence_index": null, "correct_answer": "部"}, "level_3": {"options": [{"text": "部", "is_correct": true, "explanation": "部用于书、电影这类作品，「我昨天看了一部电影」正确。"}, {"text": "台", "is_correct": false, "explanation": "语义：台用于机器、设备，电影不是机器或设备。"}, {"text": "篇", "is_correct": false, "explanation": "语义：篇用于文章等文字作品，电影不是文字作品。"}, {"text": "张", "is_correct": false, "explanation": "搭配：张多用于平面、纸张类的东西，不说「一张电影」。"}], "explanations": {"部": "部用于书、电影这类作品，「我昨天看了一部电影」正确。", "台": "语义：台用于机器、设备，电影不是机器或设备。", "篇": "语义：篇用于文章等文字作品，电影不是文字作品。", "张": "搭配：张多用于平面、纸张类的东西，不说「一张电影」。"}, "sentence_index": 0, "correct_answer": "部"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他买了一部伞。", "explanation": "这里应该用〈把〉。部用于书、电影这类作品，伞是有柄的东西，要用〈把〉。"}, {"text": "我买了一部苹果。", "explanation": "这里应该用〈个〉。部不用于水果，苹果要用〈个〉。"}, {"text": "客厅里放着一部沙发。", "explanation": "这里应该用〈张〉。部不用于家具，沙发要用〈张〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c645df3b-621c-4776-bd13-68de8b7dea98') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
