INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87294, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "部", "is_correct": true, "explanation": "部 bù（第四声），用于手机、电视剧、机器等的量词。"}, {"text": "补", "is_correct": false, "explanation": "bǔ（第三声）与 bù（第四声）声调不同，意思是补充。"}, {"text": "铺", "is_correct": false, "explanation": "pù 与 bù 声母不同（p 与 b），意思是店铺。"}, {"text": "木", "is_correct": false, "explanation": "mù 与 bù 声母不同（m 与 b），意思是木头。"}], "explanations": {"部": "部 bù（第四声），用于手机、电视剧、机器等的量词。", "补": "bǔ（第三声）与 bù（第四声）声调不同，意思是补充。", "铺": "pù 与 bù 声母不同（p 与 b），意思是店铺。", "木": "mù 与 bù 声母不同（m 与 b），意思是木头。"}, "sentence_index": null, "correct_answer": "部"}, "level_3": {"options": [{"text": "部", "is_correct": true, "explanation": "部用于手机、机器等，「我新买了一部手机」正确。"}, {"text": "篇", "is_correct": false, "explanation": "语义：篇用于文章等文字作品，手机不是文字作品。"}, {"text": "张", "is_correct": false, "explanation": "搭配：张多用于纸张、平面的东西，不说「一张手机」。"}, {"text": "首", "is_correct": false, "explanation": "语义：首用于诗歌、歌曲，手机不是诗歌或歌曲。"}], "explanations": {"部": "部用于手机、机器等，「我新买了一部手机」正确。", "篇": "语义：篇用于文章等文字作品，手机不是文字作品。", "张": "搭配：张多用于纸张、平面的东西，不说「一张手机」。", "首": "语义：首用于诗歌、歌曲，手机不是诗歌或歌曲。"}, "sentence_index": 0, "correct_answer": "部"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他送给我一部花。", "explanation": "这里应该用〈朵〉。部用于机器、电视剧等，花要用〈朵〉。"}, {"text": "书包里有一部笔。", "explanation": "这里应该用〈支〉。部不用于文具，笔要用〈支〉。"}, {"text": "我们住在一部房子里。", "explanation": "这里应该用〈座〉。部不用于房屋，房子要用〈座〉或〈套〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c645df3b-621c-4776-bd13-68de8b7dea98') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
