INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87299, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "一半是把一样东西分成两份，其中的一份。", "primary_collocate": null, "pronunciation": "yī bàn", "ipa": "i˥ pan˥˩", "syllable_count": 2, "sentences": [{"text": "这个苹果太大，我只吃一半。", "target_word": "一半", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把蛋糕切开，一半给了我。", "target_word": "一半", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这瓶水我喝了一半。", "target_word": "一半", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "桌子的一半放着书。", "target_word": "一半", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "面包太多了，你拿一半回家吧。", "target_word": "一半", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书我才看了一半。", "target_word": "一半", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把钱分成两份，一半寄给妈妈。", "target_word": "一半", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一半给你，一半留给弟弟。", "target_word": "一半", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "饭盒的一半是米饭，一半是菜。", "target_word": "一半", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把这张纸剪成两块，我只要一半。", "target_word": "一半", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一半儿", "label": "儿化"}, {"form": "一大半", "label": "复合"}], "register": "中性", "sense_fingerprint": "一样东西分成两份后的其中一份", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7777e7df-230e-4f7a-be5d-05cc2cb71220') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87299, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "一半", "is_correct": true, "explanation": "一半：两份中的一份，正是听到的 yī bàn。"}, {"text": "一般", "is_correct": false, "explanation": "“一般”（yì bān）与“一半”的声调不同，意思是普通、大体上。"}, {"text": "一班", "is_correct": false, "explanation": "“一班”（yī bān）与“一半”末尾声调不同，意思是第一个班。"}, {"text": "一版", "is_correct": false, "explanation": "“一版”（yī bǎn）与“一半”末尾声调不同，意思是第一版。"}], "explanations": {"一半": "一半：两份中的一份，正是听到的 yī bàn。", "一般": "“一般”（yì bān）与“一半”的声调不同，意思是普通、大体上。", "一班": "“一班”（yī bān）与“一半”末尾声调不同，意思是第一个班。", "一版": "“一版”（yī bǎn）与“一半”末尾声调不同，意思是第一版。"}, "sentence_index": null, "correct_answer": "一半"}, "level_3": {"options": [{"text": "全部", "is_correct": false, "explanation": "语义：“只吃”与“全部”矛盾，只吃一部分不能说吃全部。"}, {"text": "一半", "is_correct": true, "explanation": "一半：苹果太大，只吃其中的一份，与句意相符。"}, {"text": "整箱", "is_correct": false, "explanation": "语义：说的是一个苹果，不能说吃整箱。"}, {"text": "一桶", "is_correct": false, "explanation": "搭配：吃苹果不用“桶”作量词，与苹果不搭配。"}], "explanations": {"全部": "语义：“只吃”与“全部”矛盾，只吃一部分不能说吃全部。", "一半": "一半：苹果太大，只吃其中的一份，与句意相符。", "整箱": "语义：说的是一个苹果，不能说吃整箱。", "一桶": "搭配：吃苹果不用“桶”作量词，与苹果不搭配。"}, "sentence_index": 0, "correct_answer": "一半"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这块饼干，我们四个人每人一半。", "explanation": "这里应该用〈四分之一〉。“一半”指两等份中的一份，四个人分一块饼干，每人只能得四分之一。"}, {"text": "他把蛋糕分成三份，一半给了我。", "explanation": "这里应该用〈一份〉。“一半”指两等份中的一份，分成三份时不能说一半。"}, {"text": "这个蛋糕，我们三个人每人一半。", "explanation": "这里应该用〈三分之一〉。“一半”只指两等份中的一份，三个人分一个蛋糕，每人只能得三分之一。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '15864d4b-d276-4b70-a8ee-d59a3a4261a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87299, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "一半", "is_correct": true, "explanation": "一半：钱分成两份后，其中一份寄给妈妈，符合句意。"}, {"text": "全部", "is_correct": false, "explanation": "语义：既然分成两份，就不会全部寄出，与“分成两份”矛盾。"}, {"text": "整笔", "is_correct": false, "explanation": "搭配：“整笔”指一次性全部的一大笔钱，与“分成两份”冲突。"}, {"text": "三分之一", "is_correct": false, "explanation": "语义：分成两份后，不会只寄其中的三分之一，句意不通。"}], "explanations": {"一半": "一半：钱分成两份后，其中一份寄给妈妈，符合句意。", "全部": "语义：既然分成两份，就不会全部寄出，与“分成两份”矛盾。", "整笔": "搭配：“整笔”指一次性全部的一大笔钱，与“分成两份”冲突。", "三分之一": "语义：分成两份后，不会只寄其中的三分之一，句意不通。"}, "sentence_index": 6, "correct_answer": "一半"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这块蛋糕我吃了一半，他吃了一半，还剩一半。", "explanation": "这里应该用〈其余〉。两个一半已经是整块，不能再剩下一半。"}, {"text": "我们五个人，每人一半饼干。", "explanation": "这里应该用〈五分之一〉。“一半”只指两等份中的一份，五个人分一块饼干，每人只能得五分之一。"}, {"text": "我买了一半的猫，养在家里。", "explanation": "这里应该用〈一只〉。“一半”指可以分成两份的东西中的一份，猫是整体，只能说买了一只猫。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '15864d4b-d276-4b70-a8ee-d59a3a4261a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87299, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我吃了一半个苹果。", "corrected_sentence": "我吃了一半的苹果。", "error_description": "错误在“一半”后的量词“个”：“一半”修饰名词时要用“的”，应说“一半的苹果”，不能直接接量词“个”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '15864d4b-d276-4b70-a8ee-d59a3a4261a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87299, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把一半个饼干吃了。", "corrected_sentence": "他把一半饼干吃了。", "error_description": "错误在“一半”后多出量词“个”：“一半”直接接名词，不能再接“个”，应去掉“个”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '15864d4b-d276-4b70-a8ee-d59a3a4261a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
