INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87300, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "二分之一；整体分成两个相等部分中的一部分。", "primary_collocate": null, "pronunciation": "yī bàn", "ipa": "i˥ pan˥˩", "syllable_count": 2, "sentences": [{"text": "全班一半的学生是女生，男女人数一样多。", "target_word": "一半", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的工资，一半用来交房租。", "target_word": "一半", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个城市一半的人都骑自行车。", "target_word": "一半", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学生中有一半来自外国。", "target_word": "一半", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他说的话，一半是真的，一半是假的。", "target_word": "一半", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们公司一半的员工会说英语。", "target_word": "一半", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次考试，全班四十人，一半的人没有及格，二十人及格了。", "target_word": "一半", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一年中，他有一半时间在国外。", "target_word": "一半", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛的观众里，一半是小孩子。", "target_word": "一半", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一半的同学今天没有来上课。", "target_word": "一半", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一半儿", "label": "儿化"}, {"form": "一大半", "label": "复合"}], "register": "中性", "sense_fingerprint": "整体的二分之一，表示数量或比例", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7777e7df-230e-4f7a-be5d-05cc2cb71220') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87300, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "一半", "is_correct": true, "explanation": "一半：整体的二分之一，正是听到的 yī bàn。"}, {"text": "一般", "is_correct": false, "explanation": "“一般”（yì bān）与“一半”的声调不同，意思是普通、大体上。"}, {"text": "一班", "is_correct": false, "explanation": "“一班”（yī bān）与“一半”末尾声调不同，意思是第一个班。"}, {"text": "一版", "is_correct": false, "explanation": "“一版”（yī bǎn）与“一半”末尾声调不同，意思是第一版。"}], "explanations": {"一半": "一半：整体的二分之一，正是听到的 yī bàn。", "一般": "“一般”（yì bān）与“一半”的声调不同，意思是普通、大体上。", "一班": "“一班”（yī bān）与“一半”末尾声调不同，意思是第一个班。", "一版": "“一版”（yī bǎn）与“一半”末尾声调不同，意思是第一版。"}, "sentence_index": null, "correct_answer": "一半"}, "level_3": {"options": [{"text": "全部", "is_correct": false, "explanation": "语义：“全部”指全体，句子强调的是其中一部分学生。"}, {"text": "一半", "is_correct": true, "explanation": "一半：全班学生中的二分之一，与句意相符。"}, {"text": "所有", "is_correct": false, "explanation": "语义：“所有”指全体，与“男女人数一样多”的句意矛盾。"}, {"text": "三分之一", "is_correct": false, "explanation": "语义：句子表示的是整体的二分之一，不能说三分之一。"}], "explanations": {"全部": "语义：“全部”指全体，句子强调的是其中一部分学生。", "一半": "一半：全班学生中的二分之一，与句意相符。", "所有": "语义：“所有”指全体，与“男女人数一样多”的句意矛盾。", "三分之一": "语义：句子表示的是整体的二分之一，不能说三分之一。"}, "sentence_index": 0, "correct_answer": "一半"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "学生中有一半来自外国，一半来自国内，还有一半来自亚洲。", "explanation": "这里应该用〈其余〉。两个一半已经是全部学生，不能再有第三个一半。"}, {"text": "学生中有一半是男生，另一半是女生，还有一半是老师。", "explanation": "这里应该用〈一部分〉。两个一半已是全部，再说一个一半就超出了整体。"}, {"text": "学生中有一半的时间来自外国。", "explanation": "这里应该用〈人〉。“来自外国”的主语应是人，时间不能来自外国。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '15864d4b-d276-4b70-a8ee-d59a3a4261a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87300, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "一半", "is_correct": true, "explanation": "一半：这次考试中有一半的人没及格，符合句意。"}, {"text": "全部", "is_correct": false, "explanation": "语义：全班四十人都没及格，与“二十人及格了”的句意矛盾。"}, {"text": "少数", "is_correct": false, "explanation": "语义：二十人及格，没及格的也是二十人，不能说“少数”。"}, {"text": "大部分", "is_correct": false, "explanation": "语义：“大部分”表示绝大多数，与“一半”的数量不符。"}], "explanations": {"一半": "一半：这次考试中有一半的人没及格，符合句意。", "全部": "语义：全班四十人都没及格，与“二十人及格了”的句意矛盾。", "少数": "语义：二十人及格，没及格的也是二十人，不能说“少数”。", "大部分": "语义：“大部分”表示绝大多数，与“一半”的数量不符。"}, "sentence_index": 6, "correct_answer": "一半"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个班分成三组，我在一半的那一组。", "explanation": "这里应该用〈三分之一〉。“一半”只指两等份中的一份，三组中的一组只占三分之一。"}, {"text": "一半的同学是女生，一半的同学是男生，还有一半的同学是老师。", "explanation": "这里应该用〈其余〉。两个一半已是全部同学，不能再有第三个一半。"}, {"text": "这个班一半的人是一个人。", "explanation": "这里应该用〈少数〉。“一半”指整体的二分之一，单独一个人远不到一半，应用少数来表示。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '15864d4b-d276-4b70-a8ee-d59a3a4261a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87300, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这次比赛，一半个人没有晋级。", "corrected_sentence": "这次比赛，一半的人没有晋级。", "error_description": "错误在“一半”后接量词“个”：“一半”后应接“的”再接名词，说“一半的人”，不能说“一半个人”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '15864d4b-d276-4b70-a8ee-d59a3a4261a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87300, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "一半地学生今天没来上课。", "corrected_sentence": "一半的学生今天没来上课。", "error_description": "错误在“地”：“一半”修饰名词时要用“的”，应说“一半的学生”，不能用“地”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '15864d4b-d276-4b70-a8ee-d59a3a4261a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87325, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '137e41b7-345e-410f-abda-3834f0905653') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87325, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '137e41b7-345e-410f-abda-3834f0905653') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87325, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "了事是很快做完一件事，做得不太认真，只求不再有事。", "primary_collocate": null, "pronunciation": "liǎo shì", "ipa": "ljɑʊ˨˩˦ ʂɻ̩˥˩", "syllable_count": 2, "sentences": [{"text": "他随便擦了擦桌子就了事。", "target_word": "了事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "作业太多，她写几个字就了事。", "target_word": "了事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板让他重做，不能随便了事。", "target_word": "了事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "打扫房间不要草草了事。", "target_word": "了事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他洗了洗脸就了事，没有洗澡。", "target_word": "了事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做事要认真，不能只想快点了事。", "target_word": "了事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他说了几句对不起，想就这样了事。", "target_word": "了事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事太重要，不能马马虎虎了事。", "target_word": "了事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟收拾玩具，把它们放进箱子里就了事。", "target_word": "了事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她画画很认真，从来不会随便了事。", "target_word": "了事", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "草草了事", "label": "复合"}, {"form": "敷衍了事", "label": "复合"}], "register": "中性", "sense_fingerprint": "动词：随便很快做完，只求没事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9312b6ee-2f6f-44ac-9f74-0846338cf1b7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87325, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "了事", "is_correct": true, "explanation": "正确：了事（liǎo shì）指随便做完、只求了结，是本题的目标词。"}, {"text": "小事", "is_correct": false, "explanation": "xiǎo（第三声）与 liǎo 声母不同（x 与 l），意思是小的事情，不是了事。"}, {"text": "料事", "is_correct": false, "explanation": "liào（第四声）与 liǎo（第三声）声调不同，意思是预先估计事情。"}, {"text": "老是", "is_correct": false, "explanation": "lǎo 与 liǎo 只差中间的 i 音，意思是总是、一直，听感接近但意思不同。"}, {"text": "巧事", "is_correct": false, "explanation": "qiǎo（第三声）与 liǎo 声母不同（q 与 l），意思是巧合的事。"}], "explanations": {"了事": "正确：了事（liǎo shì）指随便做完、只求了结，是本题的目标词。", "小事": "xiǎo（第三声）与 liǎo 声母不同（x 与 l），意思是小的事情，不是了事。", "料事": "liào（第四声）与 liǎo（第三声）声调不同，意思是预先估计事情。", "老是": "lǎo 与 liǎo 只差中间的 i 音，意思是总是、一直，听感接近但意思不同。", "巧事": "qiǎo（第三声）与 liǎo 声母不同（q 与 l），意思是巧合的事。"}, "sentence_index": null, "correct_answer": "了事"}, "level_3": {"options": [{"text": "了事", "is_correct": true, "explanation": "正确：了事指随便做完、不求好，与“随便擦了擦桌子”的语境一致。"}, {"text": "生病", "is_correct": false, "explanation": "语义：擦桌子与生病没有因果关系，句意不通。"}, {"text": "结婚", "is_correct": false, "explanation": "语义：擦完桌子就结婚，与句中“随便擦了擦”的语境毫无关联。"}, {"text": "唱歌", "is_correct": false, "explanation": "语义：句子讲的是草草收尾，唱歌与这一语境无关。"}], "explanations": {"了事": "正确：了事指随便做完、不求好，与“随便擦了擦桌子”的语境一致。", "生病": "语义：擦桌子与生病没有因果关系，句意不通。", "结婚": "语义：擦完桌子就结婚，与句中“随便擦了擦”的语境毫无关联。", "唱歌": "语义：句子讲的是草草收尾，唱歌与这一语境无关。"}, "sentence_index": 0, "correct_answer": "了事"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他对每个细节都反复检查，一丝不苟地了事。", "explanation": "这里应该用〈完成〉。了事指草草做完、只求不再有事，与“一丝不苟”的态度相矛盾。"}, {"text": "他对这份工作尽心尽力，认真地了事，不肯有半点马虎。", "explanation": "这里应该用〈完成〉。了事指草草做完、只求不再有事，与“尽心尽力”的态度相矛盾。"}, {"text": "他把每一个细节都反复推敲，精益求精地了事。", "explanation": "这里应该用〈完成〉。了事指草草做完，与“精益求精”的要求正相反。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '137e41b7-345e-410f-abda-3834f0905653') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87325, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "了事", "is_correct": true, "explanation": "正确：了事指草草了结，与“想就这样”的意图相符。"}, {"text": "出发", "is_correct": false, "explanation": "语义：出发是离开某地，与“想就这样了事”的意思不符。"}, {"text": "睡觉", "is_correct": false, "explanation": "语义：说了几句对不起就去睡觉，与句中的意图不通。"}, {"text": "冷战", "is_correct": false, "explanation": "语义：冷战指互不理睬，与“想就这样了事”的结局不一致。"}], "explanations": {"了事": "正确：了事指草草了结，与“想就这样”的意图相符。", "出发": "语义：出发是离开某地，与“想就这样了事”的意思不符。", "睡觉": "语义：说了几句对不起就去睡觉，与句中的意图不通。", "冷战": "语义：冷战指互不理睬，与“想就这样了事”的结局不一致。"}, "sentence_index": 6, "correct_answer": "了事"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这台机器的零件已经全部了事。", "explanation": "这里应该用〈装好〉。了事指事情草草结束，不能用于机器零件。"}, {"text": "他对每位顾客都很认真，每次服务都全心全意地了事。", "explanation": "这里应该用〈完成〉。了事指草草做完，与“全心全意”的态度相矛盾。"}, {"text": "他对这份工作非常热爱，每天都精心打磨，每一处细节都力求完美地了事。", "explanation": "这里应该用〈完成〉。了事指草草做完，与“力求完美”的要求相矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '137e41b7-345e-410f-abda-3834f0905653') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87325, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他随便整理了一下就了事了事。", "corrected_sentence": "他随便整理了一下就了事。", "error_description": "错误：“了事”重复出现了两次；正确：只说“就了事”。“了事”本身已是完整的动词，不能再接一个“了事”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '137e41b7-345e-410f-abda-3834f0905653') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87325, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这篇作业他做得很认真，从来不草草了事了。", "corrected_sentence": "这篇作业他做得很认真，从来不草草了事。", "error_description": "错误：句末多加了“了”；正确：去掉句末“了”，说“从来不草草了事”。“从来”表示习惯，否定的习惯性动作后不能再加句末“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '137e41b7-345e-410f-abda-3834f0905653') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
