INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87327, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "function", "definition": "不想是心里不愿意做一件事。", "primary_collocate": null, "pronunciation": "bù xiǎng", "ipa": "pu˥˩ ɕjɑŋ˨˩˦", "syllable_count": 2, "sentences": [{"text": "我现在不想说话，让我安静一下。", "target_word": "不想", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不想学游泳，因为他怕水。", "target_word": "不想", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我不想喝咖啡，晚上会睡不着。", "target_word": "不想", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟不想起床，因为今天是星期天。", "target_word": "不想", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我不想买新手机，旧的还能用。", "target_word": "不想", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她不想跟他吵架，所以没有说话。", "target_word": "不想", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我不想迟到，所以早点出发。", "target_word": "不想", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师，我不想坐在最后一排。", "target_word": "不想", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们不想打扰你，你好好休息吧。", "target_word": "不想", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不想做饭，我们去饭馆吃吧。", "target_word": "不想", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "想不想", "label": "正反疑问"}, {"form": "想", "label": "肯定形式"}], "register": "口语", "sense_fingerprint": "不想：心里不愿意做一件事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a05bf854-5e1e-422d-a553-c991fceb6ea9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87327, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "不想", "is_correct": true, "explanation": "不想：心里不愿意做一件事，是本题的正确答案。"}, {"text": "不像", "is_correct": false, "explanation": "xiàng（第四声）与 xiǎng（第三声）声调不同，意思是“不相似”。"}, {"text": "不香", "is_correct": false, "explanation": "xiāng（第一声）与 xiǎng（第三声）声调不同，意思是“没有香味”。"}, {"text": "不讲", "is_correct": false, "explanation": "jiǎng 与 xiǎng 声母不同（j 与 x），意思是“不说、不谈”。"}, {"text": "不祥", "is_correct": false, "explanation": "xiáng（第二声）与 xiǎng（第三声）声调不同，意思是“不吉利”。"}], "explanations": {"不想": "不想：心里不愿意做一件事，是本题的正确答案。", "不像": "xiàng（第四声）与 xiǎng（第三声）声调不同，意思是“不相似”。", "不香": "xiāng（第一声）与 xiǎng（第三声）声调不同，意思是“没有香味”。", "不讲": "jiǎng 与 xiǎng 声母不同（j 与 x），意思是“不说、不谈”。", "不祥": "xiáng（第二声）与 xiǎng（第三声）声调不同，意思是“不吉利”。"}, "sentence_index": null, "correct_answer": "不想"}, "level_3": {"options": [{"text": "不想", "is_correct": true, "explanation": "不想：心里不愿意说话，与“让我安静一下”的语气相合。"}, {"text": "想", "is_correct": false, "explanation": "语义：“想说话”表示愿意说，与“让我安静一下”正好相反。"}, {"text": "要", "is_correct": false, "explanation": "语义：“要说话”表示需要或打算说，与“让我安静一下”相矛盾。"}, {"text": "不去", "is_correct": false, "explanation": "搭配：“去”后不能直接接“说话”，应说“不说话”。"}], "explanations": {"不想": "不想：心里不愿意说话，与“让我安静一下”的语气相合。", "想": "语义：“想说话”表示愿意说，与“让我安静一下”正好相反。", "要": "语义：“要说话”表示需要或打算说，与“让我安静一下”相矛盾。", "不去": "搭配：“去”后不能直接接“说话”，应说“不说话”。"}, "sentence_index": 0, "correct_answer": "不想"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "请在图书馆里不想大声说话。", "explanation": "这里应该用〈不要〉，表示禁止或劝阻；“不想”只表示没有意愿，不能用来禁止别人大声说话。"}, {"text": "禁止停车的地方，请不想停车。", "explanation": "这里应该用〈禁止〉，表示不允许做某事；“不想”只表示没有意愿，写在禁止牌上说“请不想停车”意思不对。"}, {"text": "这个孩子长得不想妈妈。", "explanation": "这里应该用〈不像〉，表示相貌不相似；“不想”是不愿意，不能用来说长相。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8b8e5806-714e-4af5-9dbb-ff619f4a8273') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87327, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "不想", "is_correct": true, "explanation": "不想：心里不愿意做一件事，是本题的正确答案。"}, {"text": "不抢", "is_correct": false, "explanation": "qiǎng 与 xiǎng 声母不同（q 与 x），意思是“不争夺”。"}, {"text": "不小", "is_correct": false, "explanation": "xiǎo 与 xiǎng 韵尾不同（o 与 ng），意思是“不小”。"}, {"text": "不躺", "is_correct": false, "explanation": "tǎng 与 xiǎng 声母不同（t 与 x），意思是“不躺下”。"}, {"text": "不向", "is_correct": false, "explanation": "xiàng（第四声）与 xiǎng（第三声）声调不同，意思是“不朝向”。"}], "explanations": {"不想": "不想：心里不愿意做一件事，是本题的正确答案。", "不抢": "qiǎng 与 xiǎng 声母不同（q 与 x），意思是“不争夺”。", "不小": "xiǎo 与 xiǎng 韵尾不同（o 与 ng），意思是“不小”。", "不躺": "tǎng 与 xiǎng 声母不同（t 与 x），意思是“不躺下”。", "不向": "xiàng（第四声）与 xiǎng（第三声）声调不同，意思是“不朝向”。"}, "sentence_index": null, "correct_answer": "不想"}, "level_3": {"options": [{"text": "不想", "is_correct": true, "explanation": "不想：心里不愿意迟到，与“早点出发”的做法相合。"}, {"text": "愿意", "is_correct": false, "explanation": "语义：“愿意迟到”与后句“早点出发”的意图相矛盾。"}, {"text": "敢", "is_correct": false, "explanation": "语义：“敢迟到”表示不怕迟到，与“早点出发”的做法不符。"}, {"text": "不来", "is_correct": false, "explanation": "搭配：“来”与“迟到”不常搭配，应说“不迟到”。"}], "explanations": {"不想": "不想：心里不愿意迟到，与“早点出发”的做法相合。", "愿意": "语义：“愿意迟到”与后句“早点出发”的意图相矛盾。", "敢": "语义：“敢迟到”表示不怕迟到，与“早点出发”的做法不符。", "不来": "搭配：“来”与“迟到”不常搭配，应说“不迟到”。"}, "sentence_index": 6, "correct_answer": "不想"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "谢谢你的帮忙，不想谢。", "explanation": "这里应该用〈不用〉，表示不必道谢；“不想谢”表示不愿意道谢，与前句的感谢矛盾。"}, {"text": "图书馆里，不想大声喧哗！", "explanation": "这里应该用〈不许〉，表示禁止；“不想”只表示没有意愿，用在图书馆的规定里说“不想大声喧哗”意思不对。"}, {"text": "与其等待，不想主动去问。", "explanation": "这里应该用〈不如〉，表示比较后的选择；“不想”表示不愿意，这句话的意思说不通。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8b8e5806-714e-4af5-9dbb-ff619f4a8273') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87327, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妈妈想不去医院，她很怕打针。", "corrected_sentence": "妈妈不想去医院，她很怕打针。", "error_description": "“不想”的“不”要放在“想”前面，应说“不想去”；“想不去”语序不对，不是常用说法。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8b8e5806-714e-4af5-9dbb-ff619f4a8273') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
