INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87328, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "function", "definition": "不愿意；没有做某事的打算。", "primary_collocate": null, "pronunciation": "bù xiǎng", "ipa": "pu˥˩ ɕjɑŋ˨˩˦", "syllable_count": 2, "sentences": [{"text": "今天太累了，我不想出门。", "target_word": "不想", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不想吃饭，只想睡觉。", "target_word": "不想", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我不想一个人去，你跟我去吧。", "target_word": "不想", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天气这么冷，谁都不想离开家。", "target_word": "不想", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她不想告诉别人这件事。", "target_word": "不想", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我不想再等了，我们先走吧。", "target_word": "不想", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子不想写作业，一直在看电视。", "target_word": "不想", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不想参加今晚的聚会。", "target_word": "不想", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我不想让妈妈担心我。", "target_word": "不想", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个周末我哪儿都不想去。", "target_word": "不想", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "想不想", "label": "正反疑问"}, {"form": "想", "label": "肯定形式"}], "register": "口语", "sense_fingerprint": "不想：不愿意、没有打算做某事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a05bf854-5e1e-422d-a553-c991fceb6ea9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87328, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "不想", "is_correct": true, "explanation": "不想：表示不愿意做某事，是本题的正确答案。"}, {"text": "不像", "is_correct": false, "explanation": "xiàng（第四声）与 xiǎng（第三声）声调不同，意思是“不相似”。"}, {"text": "不香", "is_correct": false, "explanation": "xiāng（第一声）与 xiǎng（第三声）声调不同，意思是“没有香味”。"}, {"text": "不讲", "is_correct": false, "explanation": "jiǎng 与 xiǎng 声母不同（j 与 x），意思是“不说、不谈”。"}, {"text": "不祥", "is_correct": false, "explanation": "xiáng（第二声）与 xiǎng（第三声）声调不同，意思是“不吉利”。"}], "explanations": {"不想": "不想：表示不愿意做某事，是本题的正确答案。", "不像": "xiàng（第四声）与 xiǎng（第三声）声调不同，意思是“不相似”。", "不香": "xiāng（第一声）与 xiǎng（第三声）声调不同，意思是“没有香味”。", "不讲": "jiǎng 与 xiǎng 声母不同（j 与 x），意思是“不说、不谈”。", "不祥": "xiáng（第二声）与 xiǎng（第三声）声调不同，意思是“不吉利”。"}, "sentence_index": null, "correct_answer": "不想"}, "level_3": {"options": [{"text": "不想", "is_correct": true, "explanation": "不想：表示不愿意出门，与“太累了”的理由相合。"}, {"text": "想", "is_correct": false, "explanation": "语义：“想出门”表示愿意去，与“太累了”的理由相矛盾。"}, {"text": "已经", "is_correct": false, "explanation": "语义：“已经出门”表示已经外出，与前句“太累了”的理由和后文的意愿都不合。"}, {"text": "不敢", "is_correct": false, "explanation": "语义：“不敢”表示害怕，而前句说的是累，不是怕。"}], "explanations": {"不想": "不想：表示不愿意出门，与“太累了”的理由相合。", "想": "语义：“想出门”表示愿意去，与“太累了”的理由相矛盾。", "已经": "语义：“已经出门”表示已经外出，与前句“太累了”的理由和后文的意愿都不合。", "不敢": "语义：“不敢”表示害怕，而前句说的是累，不是怕。"}, "sentence_index": 0, "correct_answer": "不想"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "请大家不想在这里吸烟。", "explanation": "这里应该用〈不要〉。禁止或劝阻要用“不要”，“不想”只表示没有意愿，不能用来禁止别人吸烟。"}, {"text": "禁止停车的地方，请不想停车。", "explanation": "这里应该用〈禁止〉，表示不允许做某事；“不想”只表示没有意愿，写在禁止牌上说“请不想停车”意思不对。"}, {"text": "他长得不想他爸爸。", "explanation": "这里应该用〈不像〉。表示相貌不相似要用“不像”；“不想”是不愿意，不能说“长得不想”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8b8e5806-714e-4af5-9dbb-ff619f4a8273') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87328, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "不想", "is_correct": true, "explanation": "不想：表示不愿意做某事，是本题的正确答案。"}, {"text": "不抢", "is_correct": false, "explanation": "qiǎng 与 xiǎng 声母不同（q 与 x），意思是“不争夺”。"}, {"text": "不小", "is_correct": false, "explanation": "xiǎo 与 xiǎng 韵尾不同（o 与 ng），意思是“不小”。"}, {"text": "不躺", "is_correct": false, "explanation": "tǎng 与 xiǎng 声母不同（t 与 x），意思是“不躺下”。"}, {"text": "不向", "is_correct": false, "explanation": "xiàng（第四声）与 xiǎng（第三声）声调不同，意思是“不朝向”。"}], "explanations": {"不想": "不想：表示不愿意做某事，是本题的正确答案。", "不抢": "qiǎng 与 xiǎng 声母不同（q 与 x），意思是“不争夺”。", "不小": "xiǎo 与 xiǎng 韵尾不同（o 与 ng），意思是“不小”。", "不躺": "tǎng 与 xiǎng 声母不同（t 与 x），意思是“不躺下”。", "不向": "xiàng（第四声）与 xiǎng（第三声）声调不同，意思是“不朝向”。"}, "sentence_index": null, "correct_answer": "不想"}, "level_3": {"options": [{"text": "不想", "is_correct": true, "explanation": "不想：表示不愿意写作业，与“一直在看电视”的情况相合。"}, {"text": "要", "is_correct": false, "explanation": "语义：“要写作业”表示需要或打算写，与“一直在看电视”相矛盾。"}, {"text": "得", "is_correct": false, "explanation": "语义：“得写作业”表示必须写，与“一直在看电视”的情况相矛盾。"}, {"text": "不得", "is_correct": false, "explanation": "语域：“不得”是书面的禁止用语，口语中说“孩子不得写作业”很生硬。"}], "explanations": {"不想": "不想：表示不愿意写作业，与“一直在看电视”的情况相合。", "要": "语义：“要写作业”表示需要或打算写，与“一直在看电视”相矛盾。", "得": "语义：“得写作业”表示必须写，与“一直在看电视”的情况相矛盾。", "不得": "语域：“不得”是书面的禁止用语，口语中说“孩子不得写作业”很生硬。"}, "sentence_index": 6, "correct_answer": "不想"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "不想谢，这是我应该做的。", "explanation": "这里应该用〈不用〉，表示不必客气地回应；“不想”表示不愿意，“不想谢”意思不对。"}, {"text": "上课时间，不想玩手机！", "explanation": "这里应该用〈不许〉，表示禁止；“不想”只表示没有意愿，用在课堂规定里说“不想玩手机”意思不对。"}, {"text": "与其在家等，不想现在就出门。", "explanation": "这里应该用〈不如〉，表示比较后的选择；“不想”表示不愿意，这句话的意思说不通。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8b8e5806-714e-4af5-9dbb-ff619f4a8273') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87328, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我想不坐公交车，我们打车去吧。", "corrected_sentence": "我不想坐公交车，我们打车去吧。", "error_description": "“不想”的“不”要放在“想”前面，应说“不想坐”；“想不坐”语序不对，不是常用说法。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8b8e5806-714e-4af5-9dbb-ff619f4a8273') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87328, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他最近不想的吃饭了，身体变差了。", "corrected_sentence": "他最近不想吃饭了，身体变差了。", "error_description": "“不想”后面多加了“的”，应说“不想吃饭了”；“不想的吃饭”不是常用说法。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8b8e5806-714e-4af5-9dbb-ff619f4a8273') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87335, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aabca4c6-7cc0-4a5f-9fbd-a60324832225') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87335, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aabca4c6-7cc0-4a5f-9fbd-a60324832225') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87335, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "反杀是被打的人反过来把对方打倒。", "primary_collocate": null, "pronunciation": "fǎn shā", "ipa": "fan˨˩˦ ʂa˥˥", "syllable_count": 2, "sentences": [{"text": "小偷先动手，没想到他反杀了。", "target_word": "反杀", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "游戏里敌人追着他打，他最后反杀了。", "target_word": "反杀", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大孩子总打他，今天他终于反杀了。", "target_word": "反杀", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电影里，弱小的主人公突然反杀坏人。", "target_word": "反杀", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "对手打了他三拳，他一拳就反杀了。", "target_word": "反杀", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别以为我好欺负，我会反杀你的。", "target_word": "反杀", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他挨了几拳后，突然反杀了对方。", "target_word": "反杀", "complexity_tier": "T3", "furigana": "tā āi le jǐ quán hòu, tū rán fǎn shā le duì fāng.", "sentence_source": "generated"}, {"text": "老虎扑向猎人，猎人却反杀了老虎。", "target_word": "反杀", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "是他们先动手，我才反杀的。", "target_word": "反杀", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看他一直挨打，谁想到他能反杀。", "target_word": "反杀", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "反杀了", "label": "完成体"}, {"form": "反杀过", "label": "经验体"}], "register": "口语", "sense_fingerprint": "反杀：挨打的一方反过来打倒对方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a7ff3108-def9-4a18-b93a-70244681d64f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87335, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "反杀", "is_correct": true, "explanation": "正确答案：反杀，挨打的一方反过来把对方打倒。"}, {"text": "犯傻", "is_correct": false, "explanation": "fàn（第四声）与 fǎn（第三声）声调不同，犯傻意思是做蠢事。"}, {"text": "反伤", "is_correct": false, "explanation": "shāng 与 shā 韵母不同（ang 与 a），反伤意思是反过来造成伤害。"}, {"text": "砍杀", "is_correct": false, "explanation": "kǎn 与 fǎn 声母不同（k 与 f），砍杀意思是用刀砍死。"}], "explanations": {"反杀": "正确答案：反杀，挨打的一方反过来把对方打倒。", "犯傻": "fàn（第四声）与 fǎn（第三声）声调不同，犯傻意思是做蠢事。", "反伤": "shāng 与 shā 韵母不同（ang 与 a），反伤意思是反过来造成伤害。", "砍杀": "kǎn 与 fǎn 声母不同（k 与 f），砍杀意思是用刀砍死。"}, "sentence_index": null, "correct_answer": "反杀"}, "level_3": {"options": [{"text": "反杀", "is_correct": true, "explanation": "正确答案：反杀，“没想到他___了”表示被先动手的人反过来打倒了对方。"}, {"text": "吃饭", "is_correct": false, "explanation": "语义：“吃饭”与“先动手”的情节无关，句子读起来不通。"}, {"text": "颁布", "is_correct": false, "explanation": "搭配：“颁布”只用于法令、命令，不能用于人。"}, {"text": "阵亡", "is_correct": false, "explanation": "语域：“阵亡”是书面语，且只用于战场上牺牲的军人，不适合这个口语语境。"}], "explanations": {"反杀": "正确答案：反杀，“没想到他___了”表示被先动手的人反过来打倒了对方。", "吃饭": "语义：“吃饭”与“先动手”的情节无关，句子读起来不通。", "颁布": "搭配：“颁布”只用于法令、命令，不能用于人。", "阵亡": "语域：“阵亡”是书面语，且只用于战场上牺牲的军人，不适合这个口语语境。"}, "sentence_index": 0, "correct_answer": "反杀"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他被骂了几句，就反杀了两句。", "explanation": "这里应该用〈反击〉。反杀指把对方打倒，不能用来说回嘴。"}, {"text": "对方的观点有漏洞，我马上反杀了他的观点。", "explanation": "这里应该用〈反驳〉。反驳用于观点、说法；反杀是动手打倒对方，不能用于辩论。"}, {"text": "他主动挑起了争端，然后反杀了对方。", "explanation": "这里应该用〈攻击〉。反杀的“反”表示被攻击后反过来击败，他是先挑起争端的一方，应该用〈攻击〉，不能说反杀。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aabca4c6-7cc0-4a5f-9fbd-a60324832225') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87335, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "反杀", "is_correct": true, "explanation": "正确答案：反杀，挨了几拳后反过来打倒对方。"}, {"text": "感谢", "is_correct": false, "explanation": "语义：挨了打之后“感谢”对方不合情理。"}, {"text": "嘉奖", "is_correct": false, "explanation": "语域：“嘉奖”是书面用语，且含表扬之意，与挨打的叙述相悖。"}, {"text": "招待", "is_correct": false, "explanation": "语义：挨了打后“招待”对方与情节不合。"}], "explanations": {"反杀": "正确答案：反杀，挨了几拳后反过来打倒对方。", "感谢": "语义：挨了打之后“感谢”对方不合情理。", "嘉奖": "语域：“嘉奖”是书面用语，且含表扬之意，与挨打的叙述相悖。", "招待": "语义：挨了打后“招待”对方与情节不合。"}, "sentence_index": 6, "correct_answer": "反杀"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "那块石头突然反杀了他。", "explanation": "这里应该用〈砸〉。反杀的施事必须是有意识、能反击的人；石头是无生命的，只能说砸，不能说反杀。"}, {"text": "他把那张旧桌子反杀了。", "explanation": "这里应该用〈砸坏〉。反杀的对象必须是攻击他的人，桌子不能成为对手；把桌子弄坏应说〈砸坏〉。"}, {"text": "他把那碗饭反杀了。", "explanation": "这里应该用〈吃〉。反杀的对象必须是攻击他的人，饭不能成为对手；把饭吃掉应说〈吃〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aabca4c6-7cc0-4a5f-9fbd-a60324832225') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87335, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他只用了一拳，就反杀着对手。", "corrected_sentence": "他只用了一拳，就反杀了对手。", "error_description": "错误：“反杀”后用“着”表示动作持续，与“只用了一拳就”的一次完成矛盾。正确应用“了”：反杀了对手。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aabca4c6-7cc0-4a5f-9fbd-a60324832225') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87335, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他忍了很久，最后把对方反杀。", "corrected_sentence": "他忍了很久，最后把对方反杀了。", "error_description": "错误：“把”字句中动词“反杀”后缺少“了”，句子不完整。正确应为：他忍了很久，最后把对方反杀了。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aabca4c6-7cc0-4a5f-9fbd-a60324832225') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
