INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87347, 1, 'prompt1_core', '{"pos": "连词", "semantic_class": "function", "definition": "尽管是说，虽然这样，可是还是那样。", "primary_collocate": null, "pronunciation": "jǐn guǎn", "ipa": "tɕin˨˩˦ kwan˨˩˦", "syllable_count": 2, "sentences": [{"text": "尽管下着大雨，他还是去上班了。", "target_word": "尽管", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "尽管很累，她还是做完了作业。", "target_word": "尽管", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "尽管天气很冷，孩子们还是在外面玩。", "target_word": "尽管", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "尽管我不喜欢吃鱼，今天还是吃了一点。", "target_word": "尽管", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "尽管房子很小，我们住得很开心。", "target_word": "尽管", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "尽管路很远，他每天都走着去学校。", "target_word": "尽管", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "尽管妈妈说了很多次，弟弟还是不听。", "target_word": "尽管", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "尽管钱不多，她还是给朋友买了礼物。", "target_word": "尽管", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "尽管很忙，爸爸每个周末都陪我。", "target_word": "尽管", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "尽管他今年八十岁了，身体还是很好。", "target_word": "尽管", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "尽管如此", "label": "复合"}, {"form": "儘管", "label": "繁体"}], "register": "中性", "sense_fingerprint": "连词，表示让步：虽然前面是这样，后面的结果仍然相反", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a1b6033-d2c6-4adf-8a03-9e18bc04078f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87347, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "尽管", "is_correct": true, "explanation": "尽管（jǐnguǎn）：让步连词，承认前面的情况，后面引出相反的结果。"}, {"text": "近观", "is_correct": false, "explanation": "近观（jìnguān）与尽管两个音节的声调都不同，意思是近距离观察。"}, {"text": "井管", "is_correct": false, "explanation": "井管（jǐngguǎn）第一音节韵尾是 ng，与尽管的 n 不同，意思是水井的套管。"}, {"text": "金管", "is_correct": false, "explanation": "金管（jīnguǎn）第一音节为第一声，与尽管（jǐn，第三声）声调不同，意思是铜管乐器。"}, {"text": "紧关", "is_correct": false, "explanation": "紧关（jǐnguān）第二音节为第一声，与尽管的 guǎn（第三声）声调不同，意思是要紧、关键。"}], "explanations": {"尽管": "尽管（jǐnguǎn）：让步连词，承认前面的情况，后面引出相反的结果。", "近观": "近观（jìnguān）与尽管两个音节的声调都不同，意思是近距离观察。", "井管": "井管（jǐngguǎn）第一音节韵尾是 ng，与尽管的 n 不同，意思是水井的套管。", "金管": "金管（jīnguǎn）第一音节为第一声，与尽管（jǐn，第三声）声调不同，意思是铜管乐器。", "紧关": "紧关（jǐnguān）第二音节为第一声，与尽管的 guǎn（第三声）声调不同，意思是要紧、关键。"}, "sentence_index": null, "correct_answer": "尽管"}, "level_3": {"options": [{"text": "尽管", "is_correct": true, "explanation": "尽管：让步连词，前一分句说下大雨，后一分句「还是去上班了」正是相反的结果。"}, {"text": "因为", "is_correct": false, "explanation": "语义：「因为」引出原因，与后面「还是去上班了」的逆转相矛盾。"}, {"text": "所以", "is_correct": false, "explanation": "搭配：「所以」需要前面是原因，「下着大雨」只是情况，不能作为结果的前提。"}, {"text": "如果", "is_correct": false, "explanation": "语义：「如果」引出假设，而「下着大雨」是正在发生的事实。"}], "explanations": {"尽管": "尽管：让步连词，前一分句说下大雨，后一分句「还是去上班了」正是相反的结果。", "因为": "语义：「因为」引出原因，与后面「还是去上班了」的逆转相矛盾。", "所以": "搭配：「所以」需要前面是原因，「下着大雨」只是情况，不能作为结果的前提。", "如果": "语义：「如果」引出假设，而「下着大雨」是正在发生的事实。"}, "sentence_index": 0, "correct_answer": "尽管"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "尽管大家都到了，就开始开会吧。", "explanation": "这里应该用〈既然〉。尽管表示让步，前后要相反；「大家都到了」与「开始开会」是推论关系，应用〈既然……就……〉。"}, {"text": "尽管下班，他才回家。", "explanation": "这里应该用〈直到〉。尽管表示让步，前后要相反；「下班」与「回家」是时间上的先后，表示到某时才发生，应用〈直到……才……〉。"}, {"text": "尽管下不下雨，我们都要去。", "explanation": "这里应该用〈无论〉。尽管只接已经发生或确定的事实，不能接「下不下雨」这种任选的情况，任选条件要用〈无论〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f0882abe-bb72-4758-a4df-173b86a28d89') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87347, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "尽管", "is_correct": true, "explanation": "尽管（jǐnguǎn）：让步连词，承认前面的情况，后面引出相反的结果。"}, {"text": "进关", "is_correct": false, "explanation": "进关（jìnguān）两个音节的声调都与尽管不同，意思是进入关口、报关。"}, {"text": "新馆", "is_correct": false, "explanation": "新馆（xīnguǎn）声母 x 与尽管的 j 不同，第一音节声调也不同，意思是新建的场馆。"}, {"text": "进馆", "is_correct": false, "explanation": "进馆（jìnguǎn）第一音节声调与尽管（jǐn，第三声）不同，意思是进入场馆。"}, {"text": "金馆", "is_correct": false, "explanation": "金馆（jīnguǎn）第一音节为第一声，与尽管（jǐn，第三声）声调不同。"}], "explanations": {"尽管": "尽管（jǐnguǎn）：让步连词，承认前面的情况，后面引出相反的结果。", "进关": "进关（jìnguān）两个音节的声调都与尽管不同，意思是进入关口、报关。", "新馆": "新馆（xīnguǎn）声母 x 与尽管的 j 不同，第一音节声调也不同，意思是新建的场馆。", "进馆": "进馆（jìnguǎn）第一音节声调与尽管（jǐn，第三声）不同，意思是进入场馆。", "金馆": "金馆（jīnguǎn）第一音节为第一声，与尽管（jǐn，第三声）声调不同。"}, "sentence_index": null, "correct_answer": "尽管"}, "level_3": {"options": [{"text": "尽管", "is_correct": true, "explanation": "尽管：让步连词，「妈妈说了很多次」与「弟弟还是不听」正是相反的情况。"}, {"text": "因此", "is_correct": false, "explanation": "语义：「因此」表示因果结论，「妈妈说了很多次」不能推出「弟弟还是不听」。"}, {"text": "只要", "is_correct": false, "explanation": "搭配：「只要」需要与后面的「就」呼应，且「说了很多次」是已发生的事实，不是条件。"}, {"text": "而且", "is_correct": false, "explanation": "语义：「而且」表示并列递进，与后面「还是不听」的转折相矛盾。"}], "explanations": {"尽管": "尽管：让步连词，「妈妈说了很多次」与「弟弟还是不听」正是相反的情况。", "因此": "语义：「因此」表示因果结论，「妈妈说了很多次」不能推出「弟弟还是不听」。", "只要": "搭配：「只要」需要与后面的「就」呼应，且「说了很多次」是已发生的事实，不是条件。", "而且": "语义：「而且」表示并列递进，与后面「还是不听」的转折相矛盾。"}, "sentence_index": 6, "correct_answer": "尽管"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "尽管你认真复习，就能通过考试。", "explanation": "这里应该用〈只要〉表示条件。尽管表示让步，「认真复习」与「通过考试」是条件与结果的关系，不能用让步。"}, {"text": "尽管这家书店很安静，很干净。", "explanation": "这里应该用〈而且〉表示并列。尽管要求前后情况相反，而「安静」与「干净」并不相反，应用〈而且〉。"}, {"text": "尽管他吃完饭，去上班了。", "explanation": "这里应该用〈然后〉表示先后顺序。尽管表示让步，前后要相反，「吃完饭」与「去上班」只是先后关系，不能用让步。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f0882abe-bb72-4758-a4df-173b86a28d89') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87347, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "尽管因为天很冷，他还是穿了短袖。", "corrected_sentence": "尽管天很冷，他还是穿了短袖。", "error_description": "连词重复：「尽管」已表示让步，不能再与「因为」（原因）同用。应删去「因为」，说「尽管天很冷，他还是穿了短袖」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f0882abe-bb72-4758-a4df-173b86a28d89') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87347, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "尽管天气不好，他们于是出发了。", "corrected_sentence": "尽管天气不好，他们还是出发了。", "error_description": "关联词搭配错误：「尽管」表示让步，须与「还是」呼应表示转折；「于是」表示顺承的结果，二者不能同用。应说「尽管天气不好，他们还是出发了」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f0882abe-bb72-4758-a4df-173b86a28d89') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
