INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87348, 1, 'prompt1_core', '{"pos": "连词", "semantic_class": "function", "definition": "连词，表示让步，引出与前面相反的话。", "primary_collocate": null, "pronunciation": "jǐn guǎn", "ipa": "tɕin˨˩˦ kwan˨˩˦", "syllable_count": 2, "sentences": [{"text": "尽管他很年轻，但是工作得很认真。", "target_word": "尽管", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家饭馆尽管不大，菜却很好吃。", "target_word": "尽管", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "尽管大家都反对，他还是做了决定。", "target_word": "尽管", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "尽管学了三年中文，她说得还是不太好。", "target_word": "尽管", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "尽管下午有雨，我们还是去公园了。", "target_word": "尽管", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她尽管很害怕，还是走进了黑房子。", "target_word": "尽管", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "尽管我们是好朋友，可是常常不同意对方。", "target_word": "尽管", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "尽管他没有钱，生活过得很快乐。", "target_word": "尽管", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "尽管天黑了，爸爸还是没有回家。", "target_word": "尽管", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "尽管我给他打过电话，他也没有接。", "target_word": "尽管", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "尽管如此", "label": "复合"}, {"form": "儘管", "label": "繁体"}], "register": "中性", "sense_fingerprint": "连词，让步：先承认一件事，再引出相反的情况", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a1b6033-d2c6-4adf-8a03-9e18bc04078f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87348, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "尽管", "is_correct": true, "explanation": "尽管（jǐnguǎn）：让步连词，承认前面的情况，后面引出相反的结果。"}, {"text": "近观", "is_correct": false, "explanation": "近观（jìnguān）与尽管两个音节的声调都不同，意思是近距离观察。"}, {"text": "井管", "is_correct": false, "explanation": "井管（jǐngguǎn）第一音节韵尾是 ng，与尽管的 n 不同，意思是水井的套管。"}, {"text": "金管", "is_correct": false, "explanation": "金管（jīnguǎn）第一音节为第一声，与尽管（jǐn，第三声）声调不同，意思是铜管乐器。"}, {"text": "紧关", "is_correct": false, "explanation": "紧关（jǐnguān）第二音节为第一声，与尽管的 guǎn（第三声）声调不同，意思是要紧、关键。"}], "explanations": {"尽管": "尽管（jǐnguǎn）：让步连词，承认前面的情况，后面引出相反的结果。", "近观": "近观（jìnguān）与尽管两个音节的声调都不同，意思是近距离观察。", "井管": "井管（jǐngguǎn）第一音节韵尾是 ng，与尽管的 n 不同，意思是水井的套管。", "金管": "金管（jīnguǎn）第一音节为第一声，与尽管（jǐn，第三声）声调不同，意思是铜管乐器。", "紧关": "紧关（jǐnguān）第二音节为第一声，与尽管的 guǎn（第三声）声调不同，意思是要紧、关键。"}, "sentence_index": null, "correct_answer": "尽管"}, "level_3": {"options": [{"text": "尽管", "is_correct": true, "explanation": "尽管：让步连词，前一分句「他很年轻」，后一分句「工作得很认真」，与常见预期相反。"}, {"text": "因为", "is_correct": false, "explanation": "语义：「因为」引出原因，与后面的「但是」转折相矛盾。"}, {"text": "所以", "is_correct": false, "explanation": "搭配：「所以」需要前面是原因，「他很年轻」不能推出「工作得很认真」这一结果。"}, {"text": "而且", "is_correct": false, "explanation": "语义：「而且」表示并列递进，与后面的「但是」转折相矛盾。"}], "explanations": {"尽管": "尽管：让步连词，前一分句「他很年轻」，后一分句「工作得很认真」，与常见预期相反。", "因为": "语义：「因为」引出原因，与后面的「但是」转折相矛盾。", "所以": "搭配：「所以」需要前面是原因，「他很年轻」不能推出「工作得很认真」这一结果。", "而且": "语义：「而且」表示并列递进，与后面的「但是」转折相矛盾。"}, "sentence_index": 0, "correct_answer": "尽管"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "尽管你去不去，我都去。", "explanation": "这里应该用〈无论〉。尽管只接已经发生或确定的事实，不能接「去不去」这种任选的情况，任选条件要用〈无论〉。"}, {"text": "尽管你努力，就能进步。", "explanation": "这里应该用〈只要〉表示条件。尽管表示让步，「努力」与「进步」是条件与结果的关系，不是让步关系。"}, {"text": "尽管你来了，就留下吃饭吧。", "explanation": "这里应该用〈既然〉。尽管表示让步，前后要相反；「你来了」与「留下吃饭」是推论关系，应用〈既然……就……〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f0882abe-bb72-4758-a4df-173b86a28d89') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87348, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "尽管", "is_correct": true, "explanation": "尽管（jǐnguǎn）：让步连词，承认前面的情况，后面引出相反的结果。"}, {"text": "进关", "is_correct": false, "explanation": "进关（jìnguān）两个音节的声调都与尽管不同，意思是进入关口、报关。"}, {"text": "新馆", "is_correct": false, "explanation": "新馆（xīnguǎn）声母 x 与尽管的 j 不同，第一音节声调也不同，意思是新建的场馆。"}, {"text": "进馆", "is_correct": false, "explanation": "进馆（jìnguǎn）第一音节声调与尽管（jǐn，第三声）不同，意思是进入场馆。"}, {"text": "金馆", "is_correct": false, "explanation": "金馆（jīnguǎn）第一音节为第一声，与尽管（jǐn，第三声）声调不同。"}], "explanations": {"尽管": "尽管（jǐnguǎn）：让步连词，承认前面的情况，后面引出相反的结果。", "进关": "进关（jìnguān）两个音节的声调都与尽管不同，意思是进入关口、报关。", "新馆": "新馆（xīnguǎn）声母 x 与尽管的 j 不同，第一音节声调也不同，意思是新建的场馆。", "进馆": "进馆（jìnguǎn）第一音节声调与尽管（jǐn，第三声）不同，意思是进入场馆。", "金馆": "金馆（jīnguǎn）第一音节为第一声，与尽管（jǐn，第三声）声调不同。"}, "sentence_index": null, "correct_answer": "尽管"}, "level_3": {"options": [{"text": "尽管", "is_correct": true, "explanation": "尽管：让步连词，「是好朋友」与「常常不同意对方」是相反的情况。"}, {"text": "因此", "is_correct": false, "explanation": "语义：「因此」表示因果结论，「是好朋友」不能推出「常常不同意对方」。"}, {"text": "只要", "is_correct": false, "explanation": "搭配：「只要」需要条件与「就」呼应，「是好朋友」不是条件，且与「可是」的转折不搭。"}, {"text": "因为", "is_correct": false, "explanation": "语义：「因为」引出原因，「是好朋友」并不能导出「常常不同意对方」，且与「可是」的转折相矛盾。"}], "explanations": {"尽管": "尽管：让步连词，「是好朋友」与「常常不同意对方」是相反的情况。", "因此": "语义：「因此」表示因果结论，「是好朋友」不能推出「常常不同意对方」。", "只要": "搭配：「只要」需要条件与「就」呼应，「是好朋友」不是条件，且与「可是」的转折不搭。", "因为": "语义：「因为」引出原因，「是好朋友」并不能导出「常常不同意对方」，且与「可是」的转折相矛盾。"}, "sentence_index": 6, "correct_answer": "尽管"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "尽管孩子睡着，妈妈才离开。", "explanation": "这里应该用〈直到〉。尽管表示让步，前后要相反；「孩子睡着」与「妈妈才离开」是时间上的先后，应用〈直到……才……〉。"}, {"text": "尽管他很聪明，很努力。", "explanation": "这里应该用〈而且〉表示并列。尽管要求前后情况相反，而「聪明」与「努力」并不相反，应用〈而且〉。"}, {"text": "尽管他先写作业，看电视。", "explanation": "这里应该用〈然后〉表示先后顺序。尽管表示让步，前后要相反，「写作业」与「看电视」只是先后关系。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f0882abe-bb72-4758-a4df-173b86a28d89') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87348, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "尽管虽然天气不好，他们还是出发了。", "corrected_sentence": "尽管天气不好，他们还是出发了。", "error_description": "连词重复：「尽管」与「虽然」都表示让步，不能同时使用。应删去「虽然」，说「尽管天气不好，他们还是出发了」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f0882abe-bb72-4758-a4df-173b86a28d89') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87348, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "尽管他没有经验，所以做好了工作。", "corrected_sentence": "尽管他没有经验，还是做好了工作。", "error_description": "关联词搭配错误：「尽管」表示让步，须与「还是」呼应表示转折；「所以」表示因果，二者不能同用。应说「尽管他没有经验，还是做好了工作」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f0882abe-bb72-4758-a4df-173b86a28d89') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
