INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87354, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "副词，用于追问；表示究竟；也表示最终。", "primary_collocate": null, "pronunciation": "dào dǐ", "ipa": "tɑʊ˥˩ ti˨˩˦", "syllable_count": 2, "sentences": [{"text": "你到底想吃什么？", "target_word": "到底", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他到底去不去北京？", "target_word": "到底", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事到底是谁做的？", "target_word": "到底", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "试了很多次，他到底成功了。", "target_word": "到底", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她到底还是原谅了他。", "target_word": "到底", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你到底愿不愿意帮我？", "target_word": "到底", "complexity_tier": "T3", "furigana": "nǐ dào dǐ yuàn bu yuàn yì bāng wǒ", "sentence_source": "generated"}, {"text": "你到底有没有听我说话？", "target_word": "到底", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们到底什么时候出发？", "target_word": "到底", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "等了一个小时，车到底来了。", "target_word": "到底", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "虽然很难，但他到底坚持下来了。", "target_word": "到底", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "到底：追问究竟，或表示最终结果", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a05bf854-5e1e-422d-a553-c991fceb6ea9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87354, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "到底", "is_correct": true, "explanation": "到底：副词，表示追问究竟或说明最终结果，是本题的正确答案。"}, {"text": "倒地", "is_correct": false, "explanation": "dǎo dì（第三、第四声）与 dào dǐ 声调不同，意思是“摔倒在地”。"}, {"text": "到顶", "is_correct": false, "explanation": "dǐng 比 dǐ 多一个 ng 韵尾，意思是“到达顶点”。"}, {"text": "道地", "is_correct": false, "explanation": "dì（第四声）与 dǐ（第三声）声调不同，意思是“地道、纯正”。"}], "explanations": {"到底": "到底：副词，表示追问究竟或说明最终结果，是本题的正确答案。", "倒地": "dǎo dì（第三、第四声）与 dào dǐ 声调不同，意思是“摔倒在地”。", "到顶": "dǐng 比 dǐ 多一个 ng 韵尾，意思是“到达顶点”。", "道地": "dì（第四声）与 dǐ（第三声）声调不同，意思是“地道、纯正”。"}, "sentence_index": null, "correct_answer": "到底"}, "level_3": {"options": [{"text": "到底", "is_correct": true, "explanation": "到底：表示追问究竟，与“想吃什么”的追问相合。"}, {"text": "根本", "is_correct": false, "explanation": "语义：“根本”多用于否定句，不能引出“想吃什么”这样的追问。"}, {"text": "已经", "is_correct": false, "explanation": "搭配：“已经”表示已经完成的事，不能修饰还未确定的“想吃”。"}, {"text": "确实", "is_correct": false, "explanation": "语义：“确实”表示肯定事实，与句中追问的语气不符。"}], "explanations": {"到底": "到底：表示追问究竟，与“想吃什么”的追问相合。", "根本": "语义：“根本”多用于否定句，不能引出“想吃什么”这样的追问。", "已经": "搭配：“已经”表示已经完成的事，不能修饰还未确定的“想吃”。", "确实": "语义：“确实”表示肯定事实，与句中追问的语气不符。"}, "sentence_index": 0, "correct_answer": "到底"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这张票明天到底了。", "explanation": "这里应该用〈到期〉，指期限结束；“到底”表示追问或最终结果，不能用来说票的有效期结束。"}, {"text": "他五点的火车到底的开了。", "explanation": "这里应该用〈开〉，表示车辆出发；“到底”是副词，后面不能直接加“的”。"}, {"text": "连小孩到底知道这个道理。", "explanation": "这里应该用〈都〉，构成“连……都……”的强调；“到底”不能用在这个结构里。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8b8e5806-714e-4af5-9dbb-ff619f4a8273') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87354, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "到底", "is_correct": true, "explanation": "到底：表示追问究竟，与“有没有听”的追问相合。"}, {"text": "明明", "is_correct": false, "explanation": "语义：“明明”强调与事实相反，与“有没有听”的追问不合。"}, {"text": "也", "is_correct": false, "explanation": "搭配：“也”要与前文呼应，问句中单独用“也”不成立。"}, {"text": "偏偏", "is_correct": false, "explanation": "语义：“偏偏”表示故意与情理相反，与“有没有听”的追问不合。"}], "explanations": {"到底": "到底：表示追问究竟，与“有没有听”的追问相合。", "明明": "语义：“明明”强调与事实相反，与“有没有听”的追问不合。", "也": "搭配：“也”要与前文呼应，问句中单独用“也”不成立。", "偏偏": "语义：“偏偏”表示故意与情理相反，与“有没有听”的追问不合。"}, "sentence_index": 6, "correct_answer": "到底"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这口井很到底深。", "explanation": "“到底”不能插在“很”和“深”之间；这里应直接说〈这口井很深〉。"}, {"text": "我劝了很久，他到底的不听。", "explanation": "这里应该用〈偏偏〉，表示故意与情理相反；“到底”后面不能直接加“的”，结构不通。"}, {"text": "没想到他的比赛到底的赢了。", "explanation": "“到底”后面不能加“的”；这里表示出乎意料，应说〈没想到他的比赛竟然赢了〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8b8e5806-714e-4af5-9dbb-ff619f4a8273') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87354, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "经过很多次努力，他了到底成功了。", "corrected_sentence": "经过很多次努力，他到底成功了。", "error_description": "错误：“了”不能放在副词“到底”前面。“他了到底成功了”多出一个“了”，删去即可，应说“他到底成功了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8b8e5806-714e-4af5-9dbb-ff619f4a8273') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
