INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87356, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '15864d4b-d276-4b70-a8ee-d59a3a4261a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87356, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "军队中的普通战士。", "primary_collocate": null, "pronunciation": "shì bīng", "ipa": "ʂɻ̩˥˩ piŋ˥", "syllable_count": 2, "sentences": [{"text": "他在军队里只是一名普通士兵。", "target_word": "士兵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位将军以前也是一个士兵。", "target_word": "士兵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "从士兵到军官，他用了十年。", "target_word": "士兵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "军队里有军官，也有士兵。", "target_word": "士兵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他十八岁就成了一名士兵。", "target_word": "士兵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这支军队有一万名士兵。", "target_word": "士兵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位年轻的士兵还不到二十岁。", "target_word": "士兵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "士兵的工资比军官的低一些。", "target_word": "士兵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电影里的主人公是一位老士兵。", "target_word": "士兵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不想当军官，只想当士兵。", "target_word": "士兵", "complexity_tier": "T3", "furigana": "shì bīng", "sentence_source": "generated"}], "morphological_forms": [{"form": "一名士兵", "label": "量词"}, {"form": "一个士兵", "label": "量词"}, {"form": "士兵们", "label": "复数"}], "register": "中性", "sense_fingerprint": "军队中不是军官的普通战士", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7777e7df-230e-4f7a-be5d-05cc2cb71220') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87356, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "士兵", "is_correct": true, "explanation": "正确：“士兵”指军队中的普通战士，与“只是一名普通”的身份相符。"}, {"text": "将军", "is_correct": false, "explanation": "语义：将军是高级军官，与“只是一名普通”的身份矛盾。"}, {"text": "上校", "is_correct": false, "explanation": "语义：上校是军官军衔，与“只是一名普通”的说法矛盾。"}, {"text": "教授", "is_correct": false, "explanation": "搭配：“教授”是学术职称，不用来指军队里的普通身份。"}], "explanations": {"士兵": "正确：“士兵”指军队中的普通战士，与“只是一名普通”的身份相符。", "将军": "语义：将军是高级军官，与“只是一名普通”的身份矛盾。", "上校": "语义：上校是军官军衔，与“只是一名普通”的说法矛盾。", "教授": "搭配：“教授”是学术职称，不用来指军队里的普通身份。"}, "sentence_index": 0, "correct_answer": "士兵"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他毕业后成了一名士兵，负责指挥整个营。", "explanation": "这里应该用〈军官〉。指挥一个营的是军官，士兵只是普通战士，不负责指挥。"}, {"text": "他是一名士兵，负责带领全排执行任务。", "explanation": "这里应该用〈排长〉。带领全排执行任务的是排长，普通士兵不担任这一职务。"}, {"text": "这位士兵常常在指挥部里决定整场战役的进攻方向。", "explanation": "这里应该用〈将军〉。决定整场战役方向的是将军，普通士兵没有这样的决策权。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '15864d4b-d276-4b70-a8ee-d59a3a4261a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87356, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "士兵", "is_correct": true, "explanation": "正确：“士兵”是年轻的普通战士，与“还不到二十岁”的语境相符。"}, {"text": "老兵", "is_correct": false, "explanation": "搭配：“年轻的”与“老兵”搭配相悖，“老兵”指资历深的战士。"}, {"text": "老人", "is_correct": false, "explanation": "语义：“老人”年纪大，与“年轻的”矛盾。"}, {"text": "中年人", "is_correct": false, "explanation": "语义：“中年人”年龄已偏大，与“年轻的”和“还不到二十岁”矛盾。"}], "explanations": {"士兵": "正确：“士兵”是年轻的普通战士，与“还不到二十岁”的语境相符。", "老兵": "搭配：“年轻的”与“老兵”搭配相悖，“老兵”指资历深的战士。", "老人": "语义：“老人”年纪大，与“年轻的”矛盾。", "中年人": "语义：“中年人”年龄已偏大，与“年轻的”和“还不到二十岁”矛盾。"}, "sentence_index": 6, "correct_answer": "士兵"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他是一头士兵，在部队里认真训练。", "explanation": "量词用错。“头”用于牲畜，指人的“士兵”应该用“名”。"}, {"text": "我哥哥是一把士兵，每天在营区站岗。", "explanation": "量词用错。“把”用于有柄的东西，指人的“士兵”应该用“名”。"}, {"text": "那棵士兵在操场上排队。", "explanation": "量词用错。“棵”用于树木，指人的“士兵”应该用“名”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '15864d4b-d276-4b70-a8ee-d59a3a4261a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87356, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "一名士兵们在门口站岗。", "corrected_sentence": "一名士兵在门口站岗。", "error_description": "错误形式：“一名士兵们”；正确形式：“一名士兵”。“一名”已表示单数，不能再加“们”表示复数。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '15864d4b-d276-4b70-a8ee-d59a3a4261a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87356, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他去年才当上了一条士兵。", "corrected_sentence": "他去年才当上了士兵。", "error_description": "错误形式：“一条士兵”；正确形式：“士兵”（或“一名士兵”）。“条”用于细长的东西，指人应该用“名”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '15864d4b-d276-4b70-a8ee-d59a3a4261a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
