INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87364, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "结束不和睦的状态，恢复友好。", "primary_collocate": null, "pronunciation": "hé hǎo", "ipa": "xɤ˧˥ xɑʊ˨˩˦", "syllable_count": 2, "sentences": [{"text": "两个朋友因误会闹翻，很久以后终于和好了。", "target_word": "和好", "complexity_tier": "T3", "furigana": "liǎng gè péngyou yīn wùhuì nàofān, hěn jiǔ yǐhòu zhōngyú hé hǎo le.", "sentence_source": "generated"}, {"text": "邻居们为了小事不说话，最后和好了。", "target_word": "和好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这对夫妻吵了很久，现在和好了。", "target_word": "和好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两家人多年不来往，今天终于和好。", "target_word": "和好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们两年没说话，现在想和好。", "target_word": "和好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经过大家的帮助，两个同学和好了。", "target_word": "和好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "如果你先道歉，他就会和你和好。", "target_word": "和好", "complexity_tier": "T4", "sentence_source": "generated"}, {"text": "爸爸和叔叔吵架后很久才和好。", "target_word": "和好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这两位邻居因为停车的事闹过矛盾，后来终于和好了。", "target_word": "和好", "complexity_tier": "T3", "furigana": "zhè liǎng wèi línjū yīnwèi tíngchē de shì nàoguò máodùn, hòulái zhōngyú hé hǎo le.", "sentence_source": "generated"}, {"text": "他们和好以后，关系比以前更好。", "target_word": "和好", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "和好了", "label": "体标"}, {"form": "和好如初", "label": "复合"}], "register": "中性", "sense_fingerprint": "动词：双方结束不和睦，恢复友好关系", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9312b6ee-2f6f-44ac-9f74-0846338cf1b7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87364, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "和好", "is_correct": true, "explanation": "正确：和好指闹翻后重新友好，与“很久以后终于”的语境相符。"}, {"text": "结婚", "is_correct": false, "explanation": "语义：句子说的是朋友之间的矛盾，结婚与句意无关。"}, {"text": "出发", "is_correct": false, "explanation": "语义：出发是离开某地，与朋友闹翻后的和解不符。"}, {"text": "闹翻", "is_correct": false, "explanation": "语义：句中已有“闹翻”，再说闹翻与“终于”后的重归于好矛盾。"}], "explanations": {"和好": "正确：和好指闹翻后重新友好，与“很久以后终于”的语境相符。", "结婚": "语义：句子说的是朋友之间的矛盾，结婚与句意无关。", "出发": "语义：出发是离开某地，与朋友闹翻后的和解不符。", "闹翻": "语义：句中已有“闹翻”，再说闹翻与“终于”后的重归于好矛盾。"}, "sentence_index": 0, "correct_answer": "和好"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这台旧电视机，今天终于和好了。", "explanation": "这里应该用〈修好〉。和好只用于人与人之间的关系，不能用于电视机。"}, {"text": "我的数学成绩终于和好了。", "explanation": "这里应该用〈提高〉。和好只用于人与人之间闹别扭后重新友好，成绩只能提高。"}, {"text": "这场雨下了三天，今天终于和好了。", "explanation": "这里应该用〈停〉。和好指人与人之间重归于好，不能用于雨。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '137e41b7-345e-410f-abda-3834f0905653') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
